const DEFAULT_MAX_FUNCTIONS_V1: usize = 1_024;
const DEFAULT_MAX_BLOCKS_V1: usize = 16_384;
const DEFAULT_MAX_STATEMENTS_V1: usize = 1_048_576;
const DEFAULT_MAX_OPERATIONS_V1: usize = 1_048_576;
const DEFAULT_ARGUMENT_CORRESPONDENCE_WORK_V1: usize = 16 * 1024 * 1024;
const DEFAULT_ARGUMENT_CORRESPONDENCE_STORAGE_V1: usize = 16 * 1024 * 1024;
const DEFAULT_STORAGE_LAYOUT_LIMITS_V1: fe2o3_kernel_ir::StorageLayoutLimitsV1 =
    fe2o3_kernel_ir::StorageLayoutLimitsV1 {
        rows: 1 << 20,
        edges: 1 << 22,
        containment_depth: 256,
        object_bytes: (1_u64 << 61) - 1,
    };

/// Independent work limits for semantic-MIR-to-Kernel-IR lowering.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ProductionSemanticKirLimitsV1 {
    max_functions: usize,
    max_blocks: usize,
    max_statements: usize,
    max_operations: usize,
    max_argument_correspondence_work: usize,
    max_argument_correspondence_storage: usize,
    storage_layout_limits: fe2o3_kernel_ir::StorageLayoutLimitsV1,
}

impl ProductionSemanticKirLimitsV1 {
    /// Constructs explicit lowering limits.
    pub const fn new(max_functions: usize, max_blocks: usize, max_statements: usize) -> Self {
        Self::new_with_max_operations(
            max_functions,
            max_blocks,
            max_statements,
            DEFAULT_MAX_OPERATIONS_V1,
        )
    }

    /// Constructs explicit lowering limits, including the module-wide emitted-operation budget.
    pub const fn new_with_max_operations(
        max_functions: usize,
        max_blocks: usize,
        max_statements: usize,
        max_operations: usize,
    ) -> Self {
        Self {
            max_functions,
            max_blocks,
            max_statements,
            max_operations,
            max_argument_correspondence_work: DEFAULT_ARGUMENT_CORRESPONDENCE_WORK_V1,
            max_argument_correspondence_storage: DEFAULT_ARGUMENT_CORRESPONDENCE_STORAGE_V1,
            storage_layout_limits: DEFAULT_STORAGE_LAYOUT_LIMITS_V1,
        }
    }

    /// Bounds argument/call correspondence work and peak logical payload bytes.
    /// Construction and validation are independently bounded phases; validation
    /// includes retained call anchors plus temporary indices. Allocator excess,
    /// immutable source graphs and legacy argument rows are excluded.
    pub const fn with_argument_correspondence_limits(
        mut self,
        max_work: usize,
        max_storage_bytes: usize,
    ) -> Self {
        self.max_argument_correspondence_work = max_work;
        self.max_argument_correspondence_storage = max_storage_bytes;
        self
    }

    /// Retains the caller's physical-layout resource policy without widening it.
    /// These limits grant neither source validity nor target allocation authority.
    pub const fn with_storage_layout_limits(
        mut self,
        limits: fe2o3_kernel_ir::StorageLayoutLimitsV1,
    ) -> Self {
        self.storage_layout_limits = limits;
        self
    }

    /// Returns the retained physical-layout policy for admission and replay.
    pub const fn storage_layout_limits(self) -> fe2o3_kernel_ir::StorageLayoutLimitsV1 {
        self.storage_layout_limits
    }
}

impl Default for ProductionSemanticKirLimitsV1 {
    fn default() -> Self {
        Self::new_with_max_operations(
            DEFAULT_MAX_FUNCTIONS_V1,
            DEFAULT_MAX_BLOCKS_V1,
            DEFAULT_MAX_STATEMENTS_V1,
            DEFAULT_MAX_OPERATIONS_V1,
        )
    }
}

/// A bounded resource charged by production target-neutral lowering.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ProductionSemanticKirResourceV1 {
    /// Semantic functions inspected.
    Functions,
    /// Semantic blocks inspected and materialized.
    Blocks,
    /// Semantic statements inspected.
    Statements,
    /// Kernel IR operations emitted across all blocks.
    Operations,
    /// Sparse exact source-debug bindings retained by lowering.
    DebugBindings,
    /// Work performed by bounded semantic analyses during lowering.
    AnalysisWork,
    /// Exact facts retained by bounded semantic analyses during lowering.
    AnalysisStorage,
}

/// Pointer-independent evidence relating one source block to one Kernel IR block.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct SemanticKirBlockCorrespondenceV1 {
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
    semantic_block: SemanticBlockIdV1,
    kernel_ir_block: BlockId,
    source_statement_count: u32,
}

pub use fe2o3_pliron::source_argument_v1::{
    SemanticKirFunctionCorrespondenceV1, SemanticKirFunctionRoleV1,
    SemanticKirIgnoredParameterBindingV1, SemanticKirParameterBindingV1,
    SemanticKirParameterComponentBindingV1, SemanticKirParameterProjectionV1,
};

impl SemanticKirBlockCorrespondenceV1 {
    /// Returns the semantic root or helper that owns this KIR function instance.
    pub const fn correspondence_owner(self) -> SemanticFunctionIdV1 {
        self.correspondence_owner
    }

    /// Returns the exact semantic function locator.
    pub const fn semantic_function(self) -> SemanticFunctionIdV1 {
        self.semantic_function
    }

    /// Returns the exact semantic block locator.
    pub const fn semantic_block(self) -> SemanticBlockIdV1 {
        self.semantic_block
    }

    /// Returns the corresponding Kernel IR block identity.
    pub const fn kernel_ir_block(self) -> BlockId {
        self.kernel_ir_block
    }

    /// Returns the number of source statements covered by this block rule.
    pub const fn source_statement_count(self) -> u32 {
        self.source_statement_count
    }
}

/// Exact Kernel IR operation span emitted by one semantic MIR statement.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct SemanticKirStatementOperationSpanV1 {
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
    semantic_block: SemanticBlockIdV1,
    statement_ordinal: u32,
    kernel_ir_block: BlockId,
    first_operation_ordinal: u32,
    operation_count: u32,
}

impl SemanticKirStatementOperationSpanV1 {
    /// Returns the semantic root or helper that owns this KIR function instance.
    pub const fn correspondence_owner(self) -> SemanticFunctionIdV1 {
        self.correspondence_owner
    }

    /// Returns the exact semantic function locator.
    pub const fn semantic_function(self) -> SemanticFunctionIdV1 {
        self.semantic_function
    }

    /// Returns the exact semantic block locator.
    pub const fn semantic_block(self) -> SemanticBlockIdV1 {
        self.semantic_block
    }

    /// Returns the zero-based statement ordinal within the semantic block.
    pub const fn statement_ordinal(self) -> u32 {
        self.statement_ordinal
    }

    /// Returns the Kernel IR block that contains the emitted operations.
    pub const fn kernel_ir_block(self) -> BlockId {
        self.kernel_ir_block
    }

    /// Returns the zero-based ordinal of the first emitted operation.
    pub const fn first_operation_ordinal(self) -> u32 {
        self.first_operation_ordinal
    }

    /// Returns the exact number of emitted operations, including zero.
    pub const fn operation_count(self) -> u32 {
        self.operation_count
    }
}

