/// Move-only custody of one semantic module and its complete canonical ranked
/// root roster.
///
/// Roots are retained in the canonical executable order selected by the
/// compiler. Construction requires a nonempty bijection with the semantic
/// root set and rejects duplicate roots or export names.
#[must_use = "dropping the roster abandons its semantic-to-ranked custody"]
pub struct ProductionRankedSemanticProjectionModuleReceiptV1 {
    semantic_ssa: ProductionSemanticSsaOwnerV1,
    roots: Box<[ProductionRankedSemanticProjectionRootV1]>,
}

impl ProductionRankedSemanticProjectionModuleReceiptV1 {
    /// Packages the complete ordered ranked roster after structural custody
    /// checks against the one retained semantic owner.
    pub fn from_unvalidated_projection_roster_candidate(
        semantic: ProductionSemanticMirOwnerV1,
        roots: Vec<ProductionRankedSemanticProjectionRootV1>,
    ) -> Result<Self, ProductionSemanticKirErrorV1> {
        let semantic_ssa = ProductionSemanticSsaOwnerV1::try_new(
            semantic,
            ProductionSemanticSsaLimitsV1::default(),
        )
        .map_err(ProductionSemanticKirErrorV1::SemanticSsa)?;
        Self::from_unvalidated_ssa_projection_roster_candidate(semantic_ssa, roots)
    }

    /// Packages a ranked roster without discarding the exact production SSA plan.
    pub fn from_unvalidated_ssa_projection_roster_candidate(
        semantic_ssa: ProductionSemanticSsaOwnerV1,
        roots: Vec<ProductionRankedSemanticProjectionRootV1>,
    ) -> Result<Self, ProductionSemanticKirErrorV1> {
        semantic_ssa
            .verify_replay()
            .map_err(ProductionSemanticKirErrorV1::SemanticSsa)?;
        let document = semantic_ssa.source_semantic();
        if roots.is_empty() || roots.len() != document.roots().len() {
            return Err(unsupported(
                0,
                None,
                None,
                "ranked projection roster is not a complete semantic root bijection",
            ));
        }
        let semantic_roots = document.roots();
        let mut function_names = BTreeSet::new();
        for (root, expected_root) in roots.iter().zip(semantic_roots) {
            if !(1..=3).contains(&root.launch_rank)
                || root.selected_root != *expected_root
                || !function_names.insert(root.function_name())
            {
                return Err(unsupported(
                    root.selected_root.index(),
                    None,
                    None,
                    "ranked projection roster has a duplicate, missing, or invalid root identity",
                ));
            }
            validate_borrowed_ranked_semantic_projection_candidate_with_generated_effects_v1(
                semantic_ssa.source_owner(),
                root.selected_root,
                &root.lowering,
                &root.ranked_ir,
                &root.access_sources,
                &root.executable_effect_sources,
            )?;
        }
        Ok(Self {
            semantic_ssa,
            roots: roots.into_boxed_slice(),
        })
    }

    /// Returns the exact canonical root count.
    pub fn root_count(&self) -> usize {
        self.roots.len()
    }

    /// A projection roster is custody only, never artifact or launch authority.
    pub const fn grants_artifact_or_launch_authority(&self) -> bool {
        false
    }
}

impl fmt::Debug for ProductionRankedSemanticProjectionReceiptV1 {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ProductionRankedSemanticProjectionReceiptV1")
            .field("function_name", &self.function_name)
            .field("ranked_ir_bytes", &self.ranked_ir.len())
            .field("access_sources", &self.access_sources.len())
            .field(
                "executable_effect_sources",
                &self.executable_effect_sources.len(),
            )
            .finish_non_exhaustive()
    }
}

/// Borrows one exact semantic root and ranked candidate to validate the
/// structural conditions required by projection-receipt custody.
///
/// Success grants no receipt, translation-validation, Kernel IR, artifact, or
/// launch authority. The semantic owner and ranked lowering remain with the
/// caller so a module-wide owner can validate every member of an ordered
/// ranked roster without cloning or splitting custody.
pub fn validate_borrowed_ranked_semantic_projection_candidate_v1(
    semantic: &ProductionSemanticMirOwnerV1,
    selected_root: SemanticFunctionIdV1,
    lowering: &ProductionRankedKernelLoweringInputV1,
    ranked_ir: &str,
    access_sources: &[ProductionRankedAccessSourceV1],
) -> Result<(), ProductionSemanticKirErrorV1> {
    validate_borrowed_ranked_semantic_projection_candidate_with_generated_effects_v1(
        semantic,
        selected_root,
        lowering,
        ranked_ir,
        access_sources,
        &[],
    )
}

/// Validates structural custody including explicit compiler-generated effect
/// relations. This grants no translation or source authority.
#[doc(hidden)]
pub fn validate_borrowed_ranked_semantic_projection_candidate_with_generated_effects_v1(
    semantic: &ProductionSemanticMirOwnerV1,
    selected_root: SemanticFunctionIdV1,
    lowering: &ProductionRankedKernelLoweringInputV1,
    ranked_ir: &str,
    access_sources: &[ProductionRankedAccessSourceV1],
    executable_effect_sources: &[ProductionRankedExecutableEffectSourceV1],
) -> Result<(), ProductionSemanticKirErrorV1> {
    semantic
        .verify_equivalence()
        .map_err(ProductionSemanticKirErrorV1::SemanticOwner)?;
    if !mandatory_generic_checks_are_clean(lowering) {
        return Err(unsupported(
            0,
            None,
            None,
            "ranked projection receipt contains a rejected mandatory kernel check",
        ));
    }
    if ranked_ir.is_empty() {
        return Err(unsupported(
            0,
            None,
            None,
            "ranked projection receipt has empty diagnostic IR",
        ));
    }
    if !ranked_access_sources_are_well_formed(lowering.kernel(), access_sources) {
        return Err(unsupported(
            0,
            None,
            None,
            "ranked projection receipt has invalid access correspondence",
        ));
    }
    if !ranked_executable_effect_sources_are_well_formed(
        lowering.kernel(),
        executable_effect_sources,
    ) {
        return Err(unsupported(
            0,
            None,
            None,
            "ranked projection receipt has invalid generated-effect correspondence",
        ));
    }
    let document = semantic.semantic();
    let root = document
        .roots()
        .binary_search(&selected_root)
        .ok()
        .and_then(|index| document.roots().get(index))
        .and_then(|root| document.functions().get(root.index() as usize))
        .and_then(SemanticFunctionDeclV1::kernel_entry)
        .ok_or_else(|| {
            unsupported(
                0,
                None,
                None,
                "ranked projection receipt has no exact kernel root",
            )
        })?;
    let function_name = std::str::from_utf8(root.export_symbol().as_bytes()).map_err(|_| {
        unsupported(
            0,
            None,
            None,
            "ranked projection receipt has a non-UTF-8 kernel symbol",
        )
    })?;
    if function_name != lowering.kernel().function_name() {
        return Err(unsupported(
            0,
            None,
            None,
            "ranked projection receipt function identity changed",
        ));
    }
    Ok(())
}

impl ProductionRankedSemanticProjectionReceiptV1 {
    /// Packages the result of the compiler's deterministic semantic projector.
    ///
    /// This verifies structural custody only. The independently checked
    /// translation relation is constructed later by
    /// [`ProductionSemanticKirOwnerV1::try_lower_after_ranked_checks`].
    #[doc(hidden)]
    pub fn from_unvalidated_projection_candidate(
        semantic: ProductionSemanticMirOwnerV1,
        lowering: ProductionRankedKernelLoweringInputV1,
        ranked_ir: String,
        access_sources: Vec<ProductionRankedAccessSourceV1>,
    ) -> Result<Self, ProductionSemanticKirErrorV1> {
        Self::from_unvalidated_projection_candidate_with_generated_effects(
            semantic,
            lowering,
            ranked_ir,
            access_sources,
            Vec::new(),
        )
    }

    /// Packages a projection candidate with explicit no-source generated
    /// executable-effect relations.
    #[doc(hidden)]
    pub fn from_unvalidated_projection_candidate_with_generated_effects(
        semantic: ProductionSemanticMirOwnerV1,
        lowering: ProductionRankedKernelLoweringInputV1,
        ranked_ir: String,
        access_sources: Vec<ProductionRankedAccessSourceV1>,
        executable_effect_sources: Vec<ProductionRankedExecutableEffectSourceV1>,
    ) -> Result<Self, ProductionSemanticKirErrorV1> {
        let document = semantic.semantic();
        let [selected_root] = document.roots() else {
            return Err(unsupported(
                0,
                None,
                None,
                "ranked projection receipt has no exact kernel root",
            ));
        };
        validate_borrowed_ranked_semantic_projection_candidate_with_generated_effects_v1(
            &semantic,
            *selected_root,
            &lowering,
            &ranked_ir,
            &access_sources,
            &executable_effect_sources,
        )?;
        let semantic_sha256 = *document.semantic_sha256().as_bytes();
        let function_name = lowering.kernel().function_name().to_owned();
        Ok(Self {
            semantic_sha256,
            function_name,
            semantic,
            lowering,
            ranked_ir,
            access_sources: access_sources.into_boxed_slice(),
            executable_effect_sources: executable_effect_sources.into_boxed_slice(),
        })
    }

    /// Borrows the exact semantic owner retained by this receipt.
    pub const fn semantic(&self) -> &ProductionSemanticMirOwnerV1 {
        &self.semantic
    }

    /// Borrows the owner-held ranked graph and mandatory check reports.
    pub const fn lowering(&self) -> &ProductionRankedKernelLoweringInputV1 {
        &self.lowering
    }

    /// Borrows the bounded diagnostic ranked IR emitted by the projector.
    pub fn ranked_ir(&self) -> &str {
        &self.ranked_ir
    }

    /// A projection receipt is custody only, never artifact or launch authority.
    pub const fn grants_artifact_or_launch_authority(&self) -> bool {
        false
    }
}

/// Independently checked relation between retained semantic MIR effects and
/// the ranked PLIRON program admitted by the mandatory analysis pipeline.
///
/// Construction uses the direct MIR-to-Kernel-IR lowerer as an independent
/// semantic projection. It requires every source-attributed executable read,
/// write, or atomic effect to correspond bijectively to one ranked effect with
/// the same access kind, memory space, external allocation provenance, and
/// atomic ordering/scope contract. Synchronization and cooperative tensor
/// layout contracts are reconciled independently as exact multisets. Memory
/// effect reachability and every represented scalar write expression are also
/// independently reconciled. Volatile, unrepresentable-address-space, or
/// otherwise unattributed effects fail closed.
#[derive(Debug, Eq, PartialEq)]
pub struct ProductionMirPlironTranslationValidationV1 {
    semantic_sha256: [u8; 32],
    memory_effects: usize,
    synchronization_effects: usize,
    tensor_operations: usize,
    value_expressions: usize,
    conservative_ranked_effects: usize,
}

impl ProductionMirPlironTranslationValidationV1 {
    /// Returns the exact admitted semantic MIR identity.
    pub const fn semantic_sha256(&self) -> &[u8; 32] {
        &self.semantic_sha256
    }

    /// Returns bijectively matched executable read, write, and atomic effects.
    pub const fn memory_effects(&self) -> usize {
        self.memory_effects
    }

    /// Returns the number of exactly reconciled synchronization operations.
    pub const fn synchronization_effects(&self) -> usize {
        self.synchronization_effects
    }

    /// Returns the number of exactly reconciled cooperative tensor operations.
    pub const fn tensor_operations(&self) -> usize {
        self.tensor_operations
    }

    /// Returns the number of independently reconstructed scalar write roots.
    pub const fn value_expressions(&self) -> usize {
        self.value_expressions
    }

    /// The compiler projector is not a trusted premise for the effect
    /// occurrence, access kind, memory space, external allocation,
    /// atomic-contract, synchronization-contract, tensor-layout,
    /// memory-effect-flow, and represented scalar-value claims reconciled by
    /// this report.
    ///
    /// This does not apply to ranked address expressions or other claims that
    /// this first validation milestone explicitly leaves outside its scope.
    pub const fn reconciled_projection_remains_trusted(&self) -> bool {
        false
    }

    /// PLIRON does not yet retain a complete physical layout and stride model,
    /// so this report does not claim that every ranked index denotes the same
    /// byte address as Kernel IR.
    pub const fn claims_indexed_address_equivalence(&self) -> bool {
        false
    }

    /// Ranked PLIRON is a verification abstraction, not an executable IR.
    /// This report deliberately makes no claim of whole-program operational
    /// equivalence for source computations that PLIRON does not represent.
    pub const fn claims_complete_operational_equivalence(&self) -> bool {
        false
    }

    /// Returns conservative allocation-level PLIRON effects. These may
    /// over-approximate source behavior but can never erase an executable
    /// source effect.
    pub const fn conservative_ranked_effects(&self) -> usize {
        self.conservative_ranked_effects
    }

    /// This report is compiler correctness evidence only. It grants no object,
    /// publication, load, launch, runtime, or hardware authority.
    pub const fn grants_artifact_or_launch_authority(&self) -> bool {
        false
    }
}

/// Move-only owner of one exact semantic source and its verified Kernel IR.
#[must_use = "dropping the owner abandons the verified target-neutral lowering"]
pub struct ProductionSemanticKirOwnerV1 {
    semantic_ssa: ProductionSemanticSsaOwnerV1,
    module: RetainedProductionKirModuleV1,
    canonical_kernel_ir: ProductionCanonicalKernelIrV1,
    correspondence: SemanticKirCorrespondenceV1,
    limits: ProductionSemanticKirLimitsV1,
    launch_roots: Option<Box<[RetainedRankedLaunchRootV1]>>,
    generic_checks: Box<[RetainedGenericKernelChecksV1]>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct RetainedRankedLaunchRootV1 {
    selected_root: SemanticFunctionIdV1,
    launch_rank: u8,
    global_extents: [u64; 3],
    workgroup_extents: [u64; 3],
    full_physical_workgroups: bool,
}

#[derive(Debug, Eq, PartialEq)]
enum ProductionCanonicalKernelIrV1 {
    V8(VerifiedCanonicalKernelIrV8),
    V9(VerifiedCanonicalKernelIrV9),
    V11(VerifiedCanonicalKernelIrV11),
}

/// Exact canonical Kernel IR wire version retained by production lowering.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum ProductionCanonicalKernelIrVersionV1 {
    /// Exact canonical Kernel IR V8.
    V8,
    /// Exact canonical Kernel IR V9.
    V9,
    /// Exact canonical Kernel IR V11.
    V11,
}

/// Version-bound identity of the canonical Kernel IR bytes retained by the owner.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub struct ProductionCanonicalKernelIrIdentityV1 {
    version: ProductionCanonicalKernelIrVersionV1,
    digest: [u8; 32],
    canonical_length: u64,
}

impl ProductionCanonicalKernelIrIdentityV1 {
    pub(crate) const fn from_canonical_parts(
        version: ProductionCanonicalKernelIrVersionV1,
        digest: [u8; 32],
        canonical_length: u64,
    ) -> Self {
        Self {
            version,
            digest,
            canonical_length,
        }
    }

    /// Returns the exact canonical wire version committed by this identity.
    pub const fn version(&self) -> ProductionCanonicalKernelIrVersionV1 {
        self.version
    }

    /// Returns the version-domain-separated SHA-256 digest.
    pub const fn digest(&self) -> &[u8; 32] {
        &self.digest
    }

    /// Returns the exact retained canonical byte length.
    pub const fn canonical_length(&self) -> u64 {
        self.canonical_length
    }
}

impl ProductionCanonicalKernelIrV1 {
    fn from_module(module: Module) -> Result<Self, ProductionSemanticKirErrorV1> {
        if module_requires_kernel_ir_v11_v1(&module) {
            VerifiedCanonicalKernelIrV11::from_module(module)
                .map(Self::V11)
                .map_err(ProductionSemanticKirErrorV1::CanonicalKernelIrV11)
        } else if module_requires_kernel_ir_v9_v1(&module) {
            VerifiedCanonicalKernelIrV9::from_module(module)
                .map(Self::V9)
                .map_err(ProductionSemanticKirErrorV1::CanonicalKernelIrV9)
        } else {
            VerifiedCanonicalKernelIrV8::from_module(module)
                .map(Self::V8)
                .map_err(ProductionSemanticKirErrorV1::CanonicalKernelIrV8)
        }
    }

    fn revalidate(&self) -> Result<(), ProductionSemanticKirErrorV1> {
        match self {
            Self::V8(owner) => owner
                .revalidate()
                .map_err(ProductionSemanticKirErrorV1::CanonicalKernelIrV8),
            Self::V9(owner) => owner
                .revalidate()
                .map_err(ProductionSemanticKirErrorV1::CanonicalKernelIrV9),
            Self::V11(owner) => owner
                .revalidate()
                .map_err(ProductionSemanticKirErrorV1::CanonicalKernelIrV11),
        }
    }

    fn canonical_bytes(&self) -> &[u8] {
        match self {
            Self::V8(owner) => owner.canonical_bytes(),
            Self::V9(owner) => owner.canonical_bytes(),
            Self::V11(owner) => owner.canonical_bytes(),
        }
    }

    fn identity(&self) -> ProductionCanonicalKernelIrIdentityV1 {
        match self {
            Self::V8(owner) => ProductionCanonicalKernelIrIdentityV1 {
                version: ProductionCanonicalKernelIrVersionV1::V8,
                digest: *owner.identity().digest(),
                canonical_length: owner.identity().canonical_length(),
            },
            Self::V9(owner) => ProductionCanonicalKernelIrIdentityV1 {
                version: ProductionCanonicalKernelIrVersionV1::V9,
                digest: *owner.identity().digest(),
                canonical_length: owner.identity().canonical_length(),
            },
            Self::V11(owner) => ProductionCanonicalKernelIrIdentityV1 {
                version: ProductionCanonicalKernelIrVersionV1::V11,
                digest: *owner.identity().digest(),
                canonical_length: owner.identity().canonical_length(),
            },
        }
    }
}

fn module_requires_kernel_ir_v11_v1(module: &Module) -> bool {
    module.functions.iter().any(|function| {
        function.body.as_ref().is_some_and(|body| {
            body.blocks.iter().any(|block| {
                block.operations.iter().any(|operation| {
                    matches!(
                        operation.kind,
                        OperationKind::Cast {
                            kind: CastKind::RestrictPointerAccess,
                            ..
                        }
                    )
                })
            })
        })
    })
}

fn module_requires_kernel_ir_v9_v1(module: &Module) -> bool {
    !module.storage_layouts.is_empty()
        || module.functions.iter().any(|function| {
            function
                .signature
                .parameters
                .iter()
                .chain(&function.signature.results)
                .any(type_requires_kernel_ir_v9_v1)
                || function.body.as_ref().is_some_and(|body| {
                    body.blocks
                        .iter()
                        .flat_map(|block| &block.parameters)
                        .chain(
                            body.blocks
                                .iter()
                                .flat_map(|block| &block.operations)
                                .flat_map(|operation| &operation.results),
                        )
                        .any(|value| type_requires_kernel_ir_v9_v1(&value.ty))
                        || body.blocks.iter().any(|block| {
                            block.operations.iter().any(|operation| {
                                matches!(
                                    operation.kind,
                                    OperationKind::Gfx950LdsTranspose(_)
                                        | OperationKind::Storage(_)
                                        | OperationKind::GuardedStore { .. }
                                        | OperationKind::Wave(WaveOperation {
                                            kind: WaveOperationKind::ReduceF32 { .. }
                                                | WaveOperationKind::BroadcastF32 { .. },
                                            ..
                                        })
                                )
                            })
                        })
                })
        })
}

fn type_requires_kernel_ir_v9_v1(ty: &Type) -> bool {
    match ty {
        // These require a newer wire; neither frozen V8 nor V9 admits them.
        Type::Vector(_) | Type::Execution(_) | Type::StorageObject(_) => true,
        Type::Pointer(pointer) => {
            pointer.access == AccessMode::WriteOnly
                || type_requires_kernel_ir_v9_v1(&pointer.pointee)
        }
        Type::Slice(slice) => {
            slice.access == AccessMode::WriteOnly || type_requires_kernel_ir_v9_v1(&slice.element)
        }
        Type::Unit | Type::Scalar(_) => false,
    }
}

struct RetainedGenericKernelChecksV1 {
    selected_root: SemanticFunctionIdV1,
    launch_rank: u8,
    semantic_sha256: [u8; 32],
    function_name: String,
    ranked_ir: Box<str>,
    lowering: ProductionRankedKernelLoweringInputV1,
    access_sources: Box<[ProductionRankedAccessSourceV1]>,
    executable_effect_sources: Box<[ProductionRankedExecutableEffectSourceV1]>,
    translation_validation: ProductionMirPlironTranslationValidationV1,
}

impl fmt::Debug for ProductionSemanticKirOwnerV1 {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ProductionSemanticKirOwnerV1")
            .field("module", &self.module.id)
            .field("canonical_kernel_ir", &self.canonical_kernel_ir)
            .field("correspondence", &self.correspondence)
            .field("limits", &self.limits)
            .field("launch_roots", &self.launch_roots)
            .field("retained_generic_checks", &self.generic_checks.len())
            .finish_non_exhaustive()
    }
}

impl ProductionSemanticKirOwnerV1 {
    /// Consumes exact semantic ownership and constructs verified Kernel IR.
    pub fn try_lower(
        semantic: ProductionSemanticMirOwnerV1,
        limits: ProductionSemanticKirLimitsV1,
    ) -> Result<Self, ProductionSemanticKirErrorV1> {
        let mut semantic_ssa = ProductionSemanticSsaOwnerV1::try_new(
            semantic,
            ProductionSemanticSsaLimitsV1::default(),
        )
        .map_err(ProductionSemanticKirErrorV1::SemanticSsa)?;
        let (module, correspondence) =
            if ordinary_source_has_raw_wave64_shuffle_v1(semantic_ssa.source_semantic()) {
                capture_and_lower_fresh_wave64_source_v1(&mut semantic_ssa, limits)?
            } else {
                lower_module(&semantic_ssa, limits, None)?
            };
        let canonical_kernel_ir = ProductionCanonicalKernelIrV1::from_module(module.clone())?;
        let owner = Self {
            semantic_ssa,
            module: RetainedProductionKirModuleV1::Legacy(module),
            canonical_kernel_ir,
            correspondence,
            limits,
            launch_roots: None,
            generic_checks: Vec::new().into_boxed_slice(),
        };
        owner.verify_equivalence()?;
        Ok(owner)
    }

    /// Constructs Kernel IR while retaining the exact ranked graph and every
    /// mandatory generic-check report that admitted the same semantic owner.
    pub fn try_lower_after_ranked_checks(
        receipt: ProductionRankedSemanticProjectionReceiptV1,
        limits: ProductionSemanticKirLimitsV1,
        launch_rank: u8,
    ) -> Result<Self, ProductionSemanticKirErrorV1> {
        let ProductionRankedSemanticProjectionReceiptV1 {
            semantic,
            lowering,
            ranked_ir,
            semantic_sha256,
            function_name: _,
            access_sources,
            executable_effect_sources,
        } = receipt;
        if semantic_sha256 != *semantic.semantic().semantic_sha256().as_bytes() {
            return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
        }
        let selected_root = match semantic.semantic().roots() {
            [selected_root] => *selected_root,
            _ => {
                return Err(unsupported(
                    0,
                    None,
                    None,
                    "singleton ranked projection receipt does not own one exact kernel root",
                ));
            }
        };
        let roster = ProductionRankedSemanticProjectionModuleReceiptV1::from_unvalidated_projection_roster_candidate(
            semantic,
            vec![ProductionRankedSemanticProjectionRootV1::new(
                selected_root,
                launch_rank,
                lowering,
                ranked_ir,
                access_sources.into_vec(),
                executable_effect_sources.into_vec(),
            )],
        )?;
        Self::try_lower_after_ranked_roster_checks(roster, limits)
    }

    /// Constructs one canonical Kernel IR module from the complete ordered
    /// ranked root roster while retaining every root's mandatory checks.
    pub fn try_lower_after_ranked_roster_checks(
        receipt: ProductionRankedSemanticProjectionModuleReceiptV1,
        limits: ProductionSemanticKirLimitsV1,
    ) -> Result<Self, ProductionSemanticKirErrorV1> {
        let ProductionRankedSemanticProjectionModuleReceiptV1 {
            semantic_ssa,
            roots,
        } = receipt;
        semantic_ssa
            .verify_replay()
            .map_err(ProductionSemanticKirErrorV1::SemanticSsa)?;
        let semantic = semantic_ssa.source_owner();
        let launch_roots = roots
            .iter()
            .map(retained_ranked_launch_root_v1)
            .collect::<Result<Vec<_>, _>>()?
            .into_boxed_slice();
        let (module, correspondence) = lower_module(&semantic_ssa, limits, Some(&launch_roots))?;
        let mut generic_checks = Vec::with_capacity(roots.len());
        for root in roots.into_vec() {
            let function_name = root.function_name().to_owned();
            let translation_validation = validate_mir_pliron_translation_with_semantic_v1(
                Some(&semantic_ssa),
                &module,
                &correspondence,
                &function_name,
                &root.lowering,
                &root.access_sources,
                &root.executable_effect_sources,
                limits.max_operations,
            )
            .map_err(ProductionSemanticKirErrorV1::MirPlironTranslation)?;
            generic_checks.push(RetainedGenericKernelChecksV1 {
                selected_root: root.selected_root,
                launch_rank: root.launch_rank,
                semantic_sha256: *semantic.semantic().semantic_sha256().as_bytes(),
                function_name,
                ranked_ir: root.ranked_ir.into_boxed_str(),
                lowering: root.lowering,
                access_sources: root.access_sources,
                executable_effect_sources: root.executable_effect_sources,
                translation_validation,
            });
        }
        let canonical_kernel_ir = ProductionCanonicalKernelIrV1::from_module(module.clone())?;
        let owner = Self {
            semantic_ssa,
            module: RetainedProductionKirModuleV1::Legacy(module),
            canonical_kernel_ir,
            correspondence,
            limits,
            launch_roots: Some(launch_roots),
            generic_checks: generic_checks.into_boxed_slice(),
        };
        owner.verify_equivalence()?;
        Ok(owner)
    }

    /// Re-verifies semantic ownership, Kernel IR, and retained correspondence.
    pub fn verify_equivalence(&self) -> Result<(), ProductionSemanticKirErrorV1> {
        let mut work = fe2o3_kernel_ir::CanonicalKernelIrWorkBudgetV1::new(
            self.limits.max_argument_correspondence_work,
        );
        let mut budget =
            ArgumentBudgetV1::new(&mut work, self.limits.max_argument_correspondence_storage);
        self.verify_equivalence_with_budget_v1(&mut budget)
    }

    /// Replays the same complete source/N and ranked checks while charging new
    /// helper-value caches and expansion to the caller's live ledger. Helper
    /// scratch restores the incoming storage floor; historical lowering and
    /// canonical/index allocations retain their existing separate limits.
    pub fn verify_equivalence_with_budget_v1(
        &self,
        budget: &mut ArgumentBudgetV1<'_>,
    ) -> Result<(), ProductionSemanticKirErrorV1> {
        self.verify_equivalence_with_translation_allowance_v1(budget, None)
    }

    /// Replays the same complete checks, charging helper translation work and
    /// scratch to the original caller ledger while preserving this owner's
    /// legacy local translation ceilings across all roots. All non-helper
    /// lowering, canonical, SSA and correspondence costs retain their old scope.
    pub fn verify_equivalence_with_bounded_translation_budget_v1(
        &self,
        budget: &mut ArgumentBudgetV1<'_>,
    ) -> Result<(), ProductionSemanticKirErrorV1> {
        let mut allowance = native_helper_value_expansion_v1::TranslationAllowanceV1::new(
            budget,
            self.limits.max_argument_correspondence_work,
            self.limits.max_argument_correspondence_storage,
        );
        self.verify_equivalence_with_translation_allowance_v1(budget, Some(&mut allowance))
    }

    fn verify_equivalence_with_translation_allowance_v1(
        &self,
        budget: &mut ArgumentBudgetV1<'_>,
        mut allowance: Option<&mut native_helper_value_expansion_v1::TranslationAllowanceV1>,
    ) -> Result<(), ProductionSemanticKirErrorV1> {
        self.semantic_ssa
            .verify_replay()
            .map_err(ProductionSemanticKirErrorV1::SemanticSsa)?;
        self.canonical_kernel_ir.revalidate()?;
        verify_module(&self.module).map_err(ProductionSemanticKirErrorV1::InvalidKernelIr)?;
        let (rederived_module, rederived_correspondence) = lower_module(
            &self.semantic_ssa,
            self.limits,
            self.launch_roots.as_deref(),
        )?;
        let rederived_canonical_kernel_ir =
            ProductionCanonicalKernelIrV1::from_module(rederived_module.clone())?;
        if self.module() != &rederived_module
            || self.correspondence != rederived_correspondence
            || self.canonical_kernel_ir != rederived_canonical_kernel_ir
            || self.canonical_kernel_ir.canonical_bytes()
                != rederived_canonical_kernel_ir.canonical_bytes()
        {
            return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
        }
        for generic_checks in &self.generic_checks {
            let Some(kernel) = self
                .module
                .kernels
                .iter()
                .find(|kernel| kernel.id.as_str() == generic_checks.function_name)
            else {
                return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
            };
            if generic_checks.semantic_sha256 != self.correspondence.semantic_sha256
                || kernel.entry.as_str() != generic_checks.function_name
                || generic_checks.ranked_ir.is_empty()
                || self
                    .semantic_ssa
                    .source_semantic()
                    .select_kernel_body_for_root_v1(generic_checks.selected_root)
                    .is_none()
                || self.launch_roots.as_deref().is_none_or(|roots| {
                    !roots.iter().any(|root| {
                        root.selected_root == generic_checks.selected_root
                            && root.launch_rank == generic_checks.launch_rank
                    })
                })
                || !mandatory_generic_checks_are_clean(&generic_checks.lowering)
                || !ranked_access_sources_are_well_formed(
                    generic_checks.lowering.kernel(),
                    &generic_checks.access_sources,
                )
                || !ranked_executable_effect_sources_are_well_formed(
                    generic_checks.lowering.kernel(),
                    &generic_checks.executable_effect_sources,
                )
            {
                return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
            }
            let revalidated = validate_mir_pliron_translation_with_allowance_resources_v1(
                Some(&self.semantic_ssa),
                &self.module,
                &self.correspondence,
                &generic_checks.function_name,
                &generic_checks.lowering,
                &generic_checks.access_sources,
                &generic_checks.executable_effect_sources,
                self.limits.max_operations,
                budget,
                allowance.as_deref_mut(),
            )
            .map_err(native_helper_value_expansion_v1::NativeTranslationErrorV1::into_semantic)?;
            if revalidated != generic_checks.translation_validation {
                return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
            }
        }
        Ok(())
    }

    /// Borrows the retained exact semantic owner.
    pub const fn semantic(&self) -> &ProductionSemanticMirOwnerV1 {
        self.semantic_ssa.source_owner()
    }

    /// Returns the exact production SSA identity consumed by KIR lowering.
    pub const fn semantic_ssa_identity(&self) -> ProductionSemanticSsaIdentityV1 {
        self.semantic_ssa.identity()
    }

    /// Returns aggregate planner work and mixed SSA/memory classification.
    pub const fn semantic_ssa_summary(&self) -> ProductionSemanticSsaSummaryV1 {
        self.semantic_ssa.summary()
    }

    /// Borrows the structurally verified Kernel IR module.
    pub const fn module(&self) -> &Module {
        self.module.module()
    }

    /// Borrows the authoritative exact, semantically verified Kernel IR V8 owner, when retained.
    pub const fn canonical_kernel_ir_v8(&self) -> Option<&VerifiedCanonicalKernelIrV8> {
        match &self.canonical_kernel_ir {
            ProductionCanonicalKernelIrV1::V8(owner) => Some(owner),
            ProductionCanonicalKernelIrV1::V9(_) | ProductionCanonicalKernelIrV1::V11(_) => None,
        }
    }

    /// Borrows the typed V8 identity when the retained canonical Kernel IR is V8.
    pub const fn canonical_kernel_ir_v8_identity(
        &self,
    ) -> Option<&VerifiedCanonicalKernelIrIdentityV8> {
        match self.canonical_kernel_ir_v8() {
            Some(owner) => Some(owner.identity()),
            None => None,
        }
    }

    /// Borrows canonical V9 ownership when the lowered module uses the exact
    /// gfx950 collective or LDS transpose surface.
    pub const fn canonical_kernel_ir_v9(&self) -> Option<&VerifiedCanonicalKernelIrV9> {
        match &self.canonical_kernel_ir {
            ProductionCanonicalKernelIrV1::V8(_) => None,
            ProductionCanonicalKernelIrV1::V9(owner) => Some(owner),
            ProductionCanonicalKernelIrV1::V11(_) => None,
        }
    }

    /// Borrows the typed V9 identity for an exact gfx950 collective or LDS transpose module.
    pub const fn canonical_kernel_ir_v9_identity(
        &self,
    ) -> Option<&VerifiedCanonicalKernelIrIdentityV9> {
        match self.canonical_kernel_ir_v9() {
            Some(owner) => Some(owner.identity()),
            None => None,
        }
    }

    /// Borrows canonical V11 ownership when the lowered module uses pointer-access narrowing.
    pub const fn canonical_kernel_ir_v11(&self) -> Option<&VerifiedCanonicalKernelIrV11> {
        match &self.canonical_kernel_ir {
            ProductionCanonicalKernelIrV1::V8(_) | ProductionCanonicalKernelIrV1::V9(_) => None,
            ProductionCanonicalKernelIrV1::V11(owner) => Some(owner),
        }
    }

    /// Borrows the typed V11 identity for a module with pointer-access narrowing.
    pub const fn canonical_kernel_ir_v11_identity(
        &self,
    ) -> Option<&VerifiedCanonicalKernelIrIdentityV11> {
        match self.canonical_kernel_ir_v11() {
            Some(owner) => Some(owner.identity()),
            None => None,
        }
    }

    /// Returns the exact version-bound identity of the retained canonical KIR.
    pub fn canonical_kernel_ir_identity(&self) -> ProductionCanonicalKernelIrIdentityV1 {
        self.canonical_kernel_ir.identity()
    }

    /// Borrows the exact canonical bytes for the retained version-bound Kernel IR.
    pub fn canonical_kernel_ir_bytes(&self) -> &[u8] {
        self.canonical_kernel_ir.canonical_bytes()
    }

    /// Borrows pointer-independent source correspondence evidence.
    pub const fn correspondence(&self) -> &SemanticKirCorrespondenceV1 {
        &self.correspondence
    }

    /// Reports whether mandatory ranked checks remain owned by this lowering.
    pub const fn retains_mandatory_generic_checks(&self) -> bool {
        !self.generic_checks.is_empty()
    }

    /// Borrows independently checked MIR-to-PLIRON translation evidence when
    /// this owner was constructed through the production ranked pipeline.
    pub fn mir_pliron_translation_validation(
        &self,
    ) -> Option<&ProductionMirPlironTranslationValidationV1> {
        let [checks] = self.generic_checks.as_ref() else {
            return None;
        };
        Some(&checks.translation_validation)
    }

    /// Borrows every independently checked MIR-to-PLIRON translation in the
    /// exact semantic-root order retained by this owner.
    pub fn mir_pliron_translation_validations(
        &self,
    ) -> impl ExactSizeIterator<Item = (&str, &ProductionMirPlironTranslationValidationV1)> {
        self.generic_checks.iter().map(|checks| {
            (
                checks.function_name.as_str(),
                &checks.translation_validation,
            )
        })
    }

    pub(crate) fn retained_generic_checks_discharge_unsupported_indices(
        &self,
        kernel_id: &str,
        reasons: &[FormalMemoryIncompleteReason],
    ) -> Result<(), ProductionMemoryDischargeFailureV1> {
        let Some(checks) = self
            .generic_checks
            .iter()
            .find(|checks| checks.function_name == kernel_id)
        else {
            return Err(ProductionMemoryDischargeFailureV1::stage(
                "verified Kernel IR does not retain mandatory ranked checks for the selected kernel",
            ));
        };
        if !mandatory_generic_checks_are_clean(&checks.lowering) {
            return Err(ProductionMemoryDischargeFailureV1::stage(
                "a retained mandatory ranked check is not clean",
            ));
        }
        unsupported_indices_match_ranked_sources_result(
            &self.module,
            &self.correspondence,
            Some(self.semantic_ssa.source_semantic()),
            kernel_id,
            &checks.lowering,
            &checks.access_sources,
            reasons,
            self.limits.max_operations,
        )
    }

    pub(crate) fn retained_generic_checks_discharge_guarded_accesses(
        &self,
        fresh: &crate::production_formal_memory_v1::FreshFormalGuardedReportV1<'_>,
        guarded_locations: &[FunctionOperationLocation],
    ) -> Result<(), ProductionMemoryDischargeFailureV1> {
        let kernel = fresh.kernel();
        let Some(checks) = self
            .generic_checks
            .iter()
            .find(|checks| checks.function_name == kernel.id.as_str())
        else {
            return Err(ProductionMemoryDischargeFailureV1::stage(
                "verified Kernel IR does not retain mandatory ranked checks for the selected kernel",
            ));
        };
        if !mandatory_generic_checks_are_clean(&checks.lowering) {
            return Err(ProductionMemoryDischargeFailureV1::stage(
                "a retained mandatory ranked check is not clean",
            ));
        }
        let mut budget = GuardedAddressProofBudgetV1::new(self.limits.max_operations)?;
        budget.prepay(4)?;
        let Some((report, witness_extents)) = fresh.for_owner(self) else {
            return Err(ProductionMemoryDischargeFailureV1::stage(
                "guarded proof received a report from another semantic owner",
            ));
        };
        guarded_accesses_have_structural_bounds_result(
            &self.module,
            kernel,
            report,
            witness_extents,
            guarded_locations,
            self.limits.max_operations,
            &mut budget,
        )
    }

    pub(crate) fn retained_collective_lowering_discharges_workgroup_memory(
        &self,
        kernel_id: &str,
        reasons: &[FormalMemoryIncompleteReason],
    ) -> Result<(), ProductionMemoryDischargeFailureV1> {
        if reasons.is_empty() || reasons.len() > self.limits.max_operations {
            return Err(ProductionMemoryDischargeFailureV1::stage(
                "workgroup-memory discharge received an empty or oversized reason set",
            ));
        }
        let Some(kernel) = self
            .module
            .kernels
            .iter()
            .find(|kernel| kernel.id.as_str() == kernel_id)
        else {
            return Err(ProductionMemoryDischargeFailureV1::stage(
                "workgroup-memory discharge cannot find the selected kernel",
            ));
        };
        let (correspondence_owner, semantic_function) = self
            .correspondence
            .lowered_functions()
            .iter()
            .find(|function| {
                function.role() == SemanticKirFunctionRoleV1::KernelEntry
                    && function.kernel_ir_function() == &kernel.entry
            })
            .map(|record| (record.correspondence_owner(), record.semantic_function()))
            .ok_or_else(|| {
                ProductionMemoryDischargeFailureV1::stage(
                    "workgroup-memory discharge cannot bind the selected kernel correspondence",
                )
            })?;
        let body = self
            .module
            .function(&kernel.entry)
            .and_then(|function| function.body.as_ref())
            .ok_or_else(|| {
                ProductionMemoryDischargeFailureV1::stage(
                    "workgroup-memory discharge cannot find the selected kernel body",
                )
            })?;
        let mut saw_allocation = false;
        let mut saw_pointer_transport = false;
        for reason in reasons {
            match reason {
                FormalMemoryIncompleteReason::UnsupportedMemoryEffect { location } => {
                    let operation = operation_at_location_v1(body, *location).ok_or_else(|| {
                        ProductionMemoryDischargeFailureV1::access(
                            *location,
                            "workgroup-memory effect location is absent from exact Kernel IR",
                        )
                    })?;
                    match &operation.kind {
                        OperationKind::WorkgroupMemory(_) => {
                            if !matches!(
                                self.terminator_intrinsic_at_location_v1(correspondence_owner, semantic_function, *location),
                                Some(
                                    SemanticCompilerIntrinsicOperationV1::DynamicLdsExactCurrent { .. }
                                        | SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineCreate { .. }
                                )
                            ) {
                                return Err(ProductionMemoryDischargeFailureV1::access(
                                    *location,
                                    "workgroup allocation is not owned by exact dynamic-LDS lowering",
                                ));
                            }
                            saw_allocation = true;
                        }
                        OperationKind::WorkgroupBarrier(_) => {
                            if !matches!(
                                self.terminator_intrinsic_at_location_v1(correspondence_owner, semantic_function, *location),
                                Some(
                                    SemanticCompilerIntrinsicOperationV1::WorkgroupReduceSum { .. }
                                        | SemanticCompilerIntrinsicOperationV1::NeutralWorkgroupReduceSum { .. }
                                        | SemanticCompilerIntrinsicOperationV1::NeutralWorkgroupScanSum { .. }
                                        | SemanticCompilerIntrinsicOperationV1::WorkgroupBarrier
                                        | SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineEvent {
                                            event: SemanticWorkgroupPipelineEventV1::Wait,
                                            ..
                                        }
                                )
                            ) {
                                return Err(ProductionMemoryDischargeFailureV1::access(
                                    *location,
                                    "workgroup barrier is not owned by exact reduction lowering",
                                ));
                            }
                        }
                        _ => {
                            return Err(ProductionMemoryDischargeFailureV1::access(
                                *location,
                                "unsupported memory effect is not an admitted compiler-owned workgroup operation",
                            ));
                        }
                    }
                }
                FormalMemoryIncompleteReason::UnsupportedPointerDerivation {
                    location,
                    pointer,
                } => {
                    let operation = operation_at_location_v1(body, *location).ok_or_else(|| {
                        ProductionMemoryDischargeFailureV1::access(
                            *location,
                            "workgroup pointer transport location is absent from exact Kernel IR",
                        )
                    })?;
                    let [result] = operation.results.as_slice() else {
                        return Err(ProductionMemoryDischargeFailureV1::access(
                            *location,
                            "workgroup pointer transport does not define exactly one value",
                        ));
                    };
                    let direct_allocation = matches!(
                        &operation.kind,
                        OperationKind::WorkgroupMemory(_)
                    ) && matches!(
                        self.terminator_intrinsic_at_location_v1(
                            correspondence_owner,
                            semantic_function,
                            *location
                        ),
                        Some(
                            SemanticCompilerIntrinsicOperationV1::DynamicLdsExactCurrent { .. }
                                | SemanticCompilerIntrinsicOperationV1::WorkgroupPipelineCreate { .. }
                        )
                    );
                    let enum_transport = matches!(
                        &operation.kind,
                        OperationKind::Load { access, .. }
                            if access.address_space == AddressSpace::Private
                    ) && self.synthetic_rule_owns_location_v1(
                        semantic_function,
                        correspondence_owner,
                        *location,
                        SemanticKirSyntheticOperationRuleV1::EnumPayloadStorage,
                    );
                    if result.id != *pointer
                        || !matches!(
                            &result.ty,
                            Type::Pointer(pointer)
                                if pointer.address_space == AddressSpace::Workgroup
                        )
                        || (!direct_allocation && !enum_transport)
                    {
                        return Err(ProductionMemoryDischargeFailureV1::access(
                            *location,
                            "workgroup pointer is not an exact compiler-owned enum transport",
                        ));
                    }
                    saw_allocation |= direct_allocation;
                    saw_pointer_transport |= enum_transport;
                }
                _ => {
                    return Err(ProductionMemoryDischargeFailureV1::stage(
                        "workgroup-memory discharge received another incomplete-reason kind",
                    ));
                }
            }
        }
        if saw_pointer_transport && !saw_allocation {
            return Err(ProductionMemoryDischargeFailureV1::stage(
                "workgroup pointer transport has no compiler-owned allocation effect",
            ));
        }
        Ok(())
    }

    fn terminator_intrinsic_at_location_v1(
        &self,
        correspondence_owner: SemanticFunctionIdV1,
        semantic_function: SemanticFunctionIdV1,
        location: FunctionOperationLocation,
    ) -> Option<SemanticCompilerIntrinsicOperationV1> {
        let span = self
            .correspondence
            .terminator_operation_spans()
            .iter()
            .find(|span| {
                span.correspondence_owner() == correspondence_owner
                    && span.semantic_function() == semantic_function
                    && operation_span_contains_v1(
                        span.kernel_ir_block(),
                        span.first_operation_ordinal(),
                        span.operation_count(),
                        location,
                    )
            })?;
        let semantic = self.semantic_ssa.source_semantic();
        let function = semantic
            .functions()
            .get(span.semantic_function().index() as usize)?;
        let block = function
            .blocks()
            .get(span.semantic_block().index() as usize)?;
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            return None;
        };
        let SemanticCallableDeclV1::CompilerIntrinsic { operation, .. } =
            semantic.callables().get(call.callee().index() as usize)?
        else {
            return None;
        };
        Some(*operation)
    }

    fn synthetic_rule_owns_location_v1(
        &self,
        semantic_function: SemanticFunctionIdV1,
        correspondence_owner: SemanticFunctionIdV1,
        location: FunctionOperationLocation,
        rule: SemanticKirSyntheticOperationRuleV1,
    ) -> bool {
        self.correspondence
            .synthetic_operation_spans()
            .iter()
            .any(|span| {
                span.correspondence_owner() == correspondence_owner
                    && span.semantic_function() == semantic_function
                    && span.rule() == rule
                    && operation_span_contains_v1(
                        span.kernel_ir_block(),
                        span.first_operation_ordinal(),
                        span.operation_count(),
                        location,
                    )
            })
    }

    /// Exact target-neutral lowering evidence is not artifact or launch authority.
    pub const fn grants_artifact_or_launch_authority(&self) -> bool {
        false
    }
}

fn operation_at_location_v1(
    body: &FunctionBody,
    location: FunctionOperationLocation,
) -> Option<&Operation> {
    body.blocks
        .iter()
        .find(|block| block.id == location.block)
        .and_then(|block| block.operations.get(location.operation_index))
}

fn operation_span_contains_v1(
    block: BlockId,
    first: u32,
    count: u32,
    location: FunctionOperationLocation,
) -> bool {
    if location.block != block {
        return false;
    }
    let Ok(operation) = u32::try_from(location.operation_index) else {
        return false;
    };
    first
        .checked_add(count)
        .is_some_and(|end| operation >= first && operation < end)
}

fn ranked_access_sources_are_well_formed(
    recipe: &fe2o3_pliron::ProductionRankedKernelV1,
    sources: &[ProductionRankedAccessSourceV1],
) -> bool {
    if sources.len() > DEFAULT_MAX_OPERATIONS_V1 {
        return false;
    }
    let mut ranked_locations = BTreeSet::new();
    let mut source_ordinals = BTreeMap::<(u32, Option<u32>), BTreeSet<u32>>::new();
    for source in sources {
        let Some(operation) = recipe
            .blocks()
            .get(source.ranked_block as usize)
            .and_then(|block| block.operations().get(source.ranked_operation as usize))
        else {
            return false;
        };
        if !matches!(
            operation,
            ProductionRankedOperationV1::Access { .. }
                | ProductionRankedOperationV1::PredicatedAccess { .. }
                | ProductionRankedOperationV1::ValueAccess { .. }
                | ProductionRankedOperationV1::AtomicAccess { .. }
                | ProductionRankedOperationV1::AtomicValueAccess { .. }
                | ProductionRankedOperationV1::AllocationEffect { .. }
        ) || !ranked_locations.insert((source.ranked_block, source.ranked_operation))
        {
            return false;
        }
        if !source_ordinals
            .entry((source.semantic_block, source.semantic_statement))
            .or_default()
            .insert(source.semantic_access_ordinal)
        {
            return false;
        }
    }
    source_ordinals.values().all(|ordinals| {
        ordinals
            .iter()
            .copied()
            .eq(0..u32::try_from(ordinals.len()).unwrap_or(u32::MAX))
    })
}

fn ranked_executable_effect_sources_are_well_formed(
    recipe: &fe2o3_pliron::ProductionRankedKernelV1,
    sources: &[ProductionRankedExecutableEffectSourceV1],
) -> bool {
    if sources.len() > DEFAULT_MAX_OPERATIONS_V1 {
        return false;
    }
    let mut locations = BTreeSet::new();
    let mut ordinals = BTreeMap::<u32, BTreeSet<u32>>::new();
    for source in sources {
        let Some(operation) = recipe
            .blocks()
            .get(source.ranked_block as usize)
            .and_then(|block| block.operations().get(source.ranked_operation as usize))
        else {
            return false;
        };
        if !matches!(
            operation,
            ProductionRankedOperationV1::AllocationEffect { .. }
                | ProductionRankedOperationV1::Barrier { .. }
                | ProductionRankedOperationV1::Fence { .. }
        ) || !locations.insert((source.ranked_block, source.ranked_operation))
            || source.origin
                != ProductionRankedExecutableEffectOriginV1::GeneratedFromSemanticTerminator
            || source.recipe_identity == [0; 32]
            || !ordinals
                .entry(source.semantic_block)
                .or_default()
                .insert(source.semantic_effect_ordinal)
        {
            return false;
        }
    }
    ordinals.values().all(|values| {
        values
            .iter()
            .copied()
            .eq(0..u32::try_from(values.len()).unwrap_or(u32::MAX))
    })
}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct SemanticAccessSiteV1 {
    block: u32,
    statement: Option<u32>,
    ordinal: u32,
}

// All correlation indexing and dependency propagation share this aggregate cap.
const UNSUPPORTED_INDEX_CORRELATION_STEPS_PER_OPERATION_V1: usize = 64;

struct UnsupportedIndexCorrelationBudgetV1 {
    remaining: usize,
}

trait CorrelationChargeV18 {
    fn charge_many(&mut self, amount: usize) -> Option<()>;

    // Historical correlation has only a finite work counter. Shared source
    // adapters override these hooks on their original live byte ledger.
    fn reserve_private_array_scratch(&mut self, _bytes: usize) -> Option<()> {
        Some(())
    }
    fn release_private_array_scratch(&mut self, _bytes: usize) -> Option<()> {
        Some(())
    }

    fn normalized_node(&mut self) -> Option<()> {
        Some(())
    }
    fn begin_normalized_tree(&mut self) -> Option<()> {
        Some(())
    }
    fn finish_normalized_pair(&mut self) -> Option<()> {
        Some(())
    }

    fn boxed_normalized_node(
        &mut self,
        node: NormalizedScalarExpressionV1,
    ) -> Option<NormalizedScalarNodeV18> {
        Some(NormalizedScalarNodeV18::legacy(node))
    }

    fn charge(&mut self) -> Option<()> {
        self.charge_many(1)
    }
}

impl CorrelationChargeV18 for UnsupportedIndexCorrelationBudgetV1 {
    fn charge_many(&mut self, amount: usize) -> Option<()> {
        self.remaining = self.remaining.checked_sub(amount)?;
        Some(())
    }
}

#[derive(Clone, Copy)]
struct KirMemoryConsumerV1 {
    location: FunctionOperationLocation,
    operation_access_ordinal: u32,
    pointer: ValueId,
    access: dialect_kernel::AccessKindAttr,
    memory_space: dialect_kernel::MemorySpaceAttr,
    atomic: Option<NormalizedAtomicContractV1>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct NormalizedAtomicContractV1 {
    ordering: u8,
    scope: u8,
    failure_ordering: Option<u8>,
}

#[derive(Clone, Copy)]
struct MissingRankedEffectDiagnosticV1 {
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
    site: SemanticAccessSiteV1,
    consumer: KirMemoryConsumerV1,
}

fn write_missing_ranked_effect_v1(
    enabled: bool,
    writer: &mut impl std::io::Write,
    diagnostic: MissingRankedEffectDiagnosticV1,
) {
    if !enabled {
        return;
    }
    let consumer = diagnostic.consumer;
    let access = match consumer.access {
        dialect_kernel::AccessKindAttr::Read => "read",
        dialect_kernel::AccessKindAttr::Write => "write",
        dialect_kernel::AccessKindAttr::AtomicRead => "atomic-read",
        dialect_kernel::AccessKindAttr::AtomicWrite => "atomic-write",
        dialect_kernel::AccessKindAttr::AtomicReadModifyWrite => "atomic-read-modify-write",
    };
    let space = match consumer.memory_space {
        dialect_kernel::MemorySpaceAttr::Private => "private",
        dialect_kernel::MemorySpaceAttr::Workgroup => "workgroup",
        dialect_kernel::MemorySpaceAttr::Global => "global",
    };
    let atomic = consumer.atomic;
    let failure = atomic.and_then(|contract| contract.failure_ordering);
    // Fixed fields only: at most 390 + 3 * size_of::<usize>() bytes, including LF.
    let _ = writeln!(
        writer,
        "MIR_PLIRON_MISSING_RANKED_EFFECT_V1 owner={} function={} semantic_block={} statement_present={} statement={} semantic_access={} kir_block={} kir_operation={} kir_access={} pointer={} access={} space={} atomic_present={} ordering={} scope={} failure_present={} failure_ordering={} counterpart=absent",
        diagnostic.correspondence_owner.index(),
        diagnostic.semantic_function.index(),
        diagnostic.site.block,
        u8::from(diagnostic.site.statement.is_some()),
        diagnostic.site.statement.unwrap_or(0),
        diagnostic.site.ordinal,
        consumer.location.block.0,
        consumer.location.operation_index,
        consumer.operation_access_ordinal,
        consumer.pointer.0,
        access,
        space,
        u8::from(atomic.is_some()),
        atomic.map_or(0, |contract| contract.ordering),
        atomic.map_or(0, |contract| contract.scope),
        u8::from(failure.is_some()),
        failure.unwrap_or(0),
    );
}

fn trace_missing_ranked_effect_v1(diagnostic: MissingRankedEffectDiagnosticV1) {
    if std::env::var_os("FE2O3_TRACE_RANKED_CUSTODY_V1").is_none() {
        return;
    }
    write_missing_ranked_effect_v1(true, &mut std::io::stderr().lock(), diagnostic);
}

fn missing_ranked_effect_v1(
    diagnostic: MissingRankedEffectDiagnosticV1,
    observe: impl FnOnce(MissingRankedEffectDiagnosticV1),
) -> ProductionMirPlironTranslationErrorV1 {
    observe(diagnostic);
    ProductionMirPlironTranslationErrorV1::MissingRankedEffect {
        semantic_block: diagnostic.site.block,
        semantic_statement: diagnostic.site.statement,
        semantic_access_ordinal: diagnostic.site.ordinal,
    }
}

