trait SemanticExpressionLeavesV18 {
    fn global_invocation_1d(
        &self,
        _scalar: ProductionSemanticScalarTypeV2,
        _budget: &mut dyn CorrelationChargeV18,
    ) -> Option<NormalizedScalarExpressionV1> {
        None
    }
    fn begin_node(&self) -> Option<()> {
        Some(())
    }
    fn symbol(
        &self,
        symbol: u32,
        scalar: ProductionSemanticScalarTypeV2,
        budget: &mut dyn CorrelationChargeV18,
    ) -> Option<NormalizedScalarExpressionV1>;
    fn load(
        &self,
        load: &fe2o3_pliron::ProductionSemanticLoadV2,
        budget: &mut dyn CorrelationChargeV18,
    ) -> Option<NormalizedScalarExpressionV1>;
}

struct RankedExpressionLeavesV18<'a> {
    recipe: &'a fe2o3_pliron::ProductionRankedKernelV1,
    ranked: &'a dyn RankedCorrelationQueriesV18,
}

impl SemanticExpressionLeavesV18 for RankedExpressionLeavesV18<'_> {
    fn symbol(
        &self,
        symbol: u32,
        scalar: ProductionSemanticScalarTypeV2,
        _: &mut dyn CorrelationChargeV18,
    ) -> Option<NormalizedScalarExpressionV1> {
        Some(NormalizedScalarExpressionV1::Symbol { symbol, scalar })
    }

    fn load(
        &self,
        load: &fe2o3_pliron::ProductionSemanticLoadV2,
        _: &mut dyn CorrelationChargeV18,
    ) -> Option<NormalizedScalarExpressionV1> {
        let ranked = self.ranked;
        let recipe = self.recipe;
        let site = ranked.site((load.block, load.operation))?;
        let source = ranked.source(site)?;
        if source.access != dialect_kernel::AccessKindAttr::Read {
            return None;
        }
        let IndexedRankedAllocationV1::View(source_view) = source.allocation else {
            return None;
        };
        if source_view != load.view {
            return None;
        }
        let ProductionRankedValueV1::Local(view) = source_view else {
            return None;
        };
        let definition = ranked.view(view)?;
        if definition.memory_space != dialect_kernel::MemorySpaceAttr::Global
            || definition.allocation_origin != load.allocation_origin
        {
            return None;
        }
        let operation = recipe
            .blocks()
            .get(load.block as usize)?
            .operations()
            .get(load.operation as usize)?;
        let indices = match operation {
            ProductionRankedOperationV1::Access { indices, .. }
            | ProductionRankedOperationV1::ValueAccess { indices, .. }
            | ProductionRankedOperationV1::AtomicAccess { indices, .. }
            | ProductionRankedOperationV1::AtomicValueAccess { indices, .. } => indices,
            _ => return None,
        };
        if indices.as_slice() != load.indices.as_ref() {
            return None;
        }
        Some(NormalizedScalarExpressionV1::Load {
            site,
            scalar: load.scalar,
        })
    }
}

fn normalize_ranked_expression_v1(
    expression: &ProductionSemanticExpressionV2,
    recipe: &fe2o3_pliron::ProductionRankedKernelV1,
    ranked: &dyn RankedCorrelationQueriesV18,
    depth: usize,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<NormalizedScalarExpressionV1> {
    normalize_semantic_expression_v18(
        expression,
        &RankedExpressionLeavesV18 { recipe, ranked },
        depth,
        budget,
    )
}

fn normalize_semantic_expression_v18(
    expression: &ProductionSemanticExpressionV2,
    leaves: &dyn SemanticExpressionLeavesV18,
    depth: usize,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<NormalizedScalarExpressionV1> {
    budget.charge()?;
    budget.normalized_node()?;
    leaves.begin_node()?;
    if depth > MAX_PRODUCTION_SEMANTIC_EXPRESSION_DEPTH_V2 {
        return None;
    }
    let next = depth.checked_add(1)?;
    Some(match expression {
        ProductionSemanticExpressionV2::GlobalInvocation1d { scalar } => {
            leaves.global_invocation_1d(*scalar, budget)?
        }
        ProductionSemanticExpressionV2::Symbol { symbol, scalar } => {
            leaves.symbol(*symbol, *scalar, budget)?
        }
        ProductionSemanticExpressionV2::Constant { scalar, bits } => {
            NormalizedScalarExpressionV1::Constant {
                scalar: *scalar,
                bits: *bits,
            }
        }
        ProductionSemanticExpressionV2::Load(load) => leaves.load(load, budget)?,
        ProductionSemanticExpressionV2::Unary {
            operation,
            scalar,
            operand,
        } => NormalizedScalarExpressionV1::Unary {
            operation: *operation,
            scalar: *scalar,
            operand: normalized_scalar_box_v18(
                normalize_semantic_expression_v18(operand, leaves, next, budget)?,
                budget,
            )?,
        },
        ProductionSemanticExpressionV2::Binary {
            operation,
            scalar,
            overflow,
            lhs,
            rhs,
        } => NormalizedScalarExpressionV1::Binary {
            operation: *operation,
            scalar: *scalar,
            overflow: *overflow,
            lhs: normalized_scalar_box_v18(
                normalize_semantic_expression_v18(lhs, leaves, next, budget)?,
                budget,
            )?,
            rhs: normalized_scalar_box_v18(
                normalize_semantic_expression_v18(rhs, leaves, next, budget)?,
                budget,
            )?,
        },
        ProductionSemanticExpressionV2::Compare {
            operation,
            operand_scalar,
            lhs,
            rhs,
        } => NormalizedScalarExpressionV1::Compare {
            operation: *operation,
            operand_scalar: *operand_scalar,
            lhs: normalized_scalar_box_v18(
                normalize_semantic_expression_v18(lhs, leaves, next, budget)?,
                budget,
            )?,
            rhs: normalized_scalar_box_v18(
                normalize_semantic_expression_v18(rhs, leaves, next, budget)?,
                budget,
            )?,
        },
        ProductionSemanticExpressionV2::Select {
            scalar,
            condition,
            when_true,
            when_false,
        } => NormalizedScalarExpressionV1::Select {
            scalar: *scalar,
            condition: normalized_scalar_box_v18(
                normalize_semantic_expression_v18(condition, leaves, next, budget)?,
                budget,
            )?,
            when_true: normalized_scalar_box_v18(
                normalize_semantic_expression_v18(when_true, leaves, next, budget)?,
                budget,
            )?,
            when_false: normalized_scalar_box_v18(
                normalize_semantic_expression_v18(when_false, leaves, next, budget)?,
                budget,
            )?,
        },
        ProductionSemanticExpressionV2::Cast {
            kind,
            source,
            target,
            operand,
        } => {
            let operand = normalize_semantic_expression_v18(operand, leaves, next, budget)?;
            if source == target {
                operand
            } else {
                NormalizedScalarExpressionV1::Cast {
                    kind: *kind,
                    source: *source,
                    target: *target,
                    operand: normalized_scalar_box_v18(operand, budget)?,
                }
            }
        }
    })
}

#[allow(clippy::too_many_arguments)]
fn normalize_kir_expression_v1(
    function: &Function,
    kir: &dyn KirCorrelationGraphV18,
    semantic_sites: &dyn SemanticAccessQueriesV18,
    value: ValueId,
    depth: usize,
    visiting: &mut BTreeSet<ValueId>,
    budget: &mut dyn CorrelationChargeV18,
    helpers: &mut native_helper_value_expansion_v1::NativeValueExpansion<'_, '_>,
) -> Option<NormalizedScalarExpressionV1> {
    normalize_kir_expression_with_visiting_v18(
        function,
        kir,
        semantic_sites,
        value,
        depth,
        visiting,
        budget,
        helpers,
    )
}

trait ScalarValueVisitingV18 {
    fn insert_value(
        &mut self,
        value: ValueId,
        budget: &mut dyn CorrelationChargeV18,
    ) -> Option<bool>;
    fn remove_value(&mut self, value: ValueId, budget: &mut dyn CorrelationChargeV18)
    -> Option<()>;
}

impl ScalarValueVisitingV18 for BTreeSet<ValueId> {
    fn insert_value(&mut self, value: ValueId, _: &mut dyn CorrelationChargeV18) -> Option<bool> {
        Some(self.insert(value))
    }
    fn remove_value(&mut self, value: ValueId, _: &mut dyn CorrelationChargeV18) -> Option<()> {
        self.remove(&value);
        Some(())
    }
}

#[allow(clippy::too_many_arguments)]
fn normalize_kir_expression_with_visiting_v18(
    function: &Function,
    kir: &dyn KirCorrelationGraphV18,
    semantic_sites: &dyn SemanticAccessQueriesV18,
    value: ValueId,
    depth: usize,
    visiting: &mut dyn ScalarValueVisitingV18,
    budget: &mut dyn CorrelationChargeV18,
    helpers: &mut native_helper_value_expansion_v1::NativeValueExpansion<'_, '_>,
) -> Option<NormalizedScalarExpressionV1> {
    budget.charge()?;
    budget.normalized_node()?;
    helpers.charge_normalization_node_v1()?;
    if depth > MAX_PRODUCTION_SEMANTIC_EXPRESSION_DEPTH_V2
        || !visiting.insert_value(value, budget)?
    {
        return None;
    }
    let result = normalize_kir_expression_inner_v1(
        function,
        kir,
        semantic_sites,
        value,
        depth,
        visiting,
        budget,
        helpers,
    );
    visiting.remove_value(value, budget)?;
    result
}

#[allow(clippy::too_many_arguments)]
fn normalize_kir_expression_inner_v1(
    function: &Function,
    kir: &dyn KirCorrelationGraphV18,
    semantic_sites: &dyn SemanticAccessQueriesV18,
    value: ValueId,
    depth: usize,
    visiting: &mut dyn ScalarValueVisitingV18,
    budget: &mut dyn CorrelationChargeV18,
    helpers: &mut native_helper_value_expansion_v1::NativeValueExpansion<'_, '_>,
) -> Option<NormalizedScalarExpressionV1> {
    // A source-owned boundary already checks every incoming edge. Resolving it
    // to one predecessor would discard that relation (or reject a genuine phi).
    if let Some(leaf) = kir.scalar_leaf(function, value)? {
        return Some(leaf);
    }
    let origin = unique_kir_ssa_origin_v1(kir, value, budget)?;
    if origin != value {
        if let Some(leaf) = kir.scalar_leaf(function, origin)? {
            return Some(leaf);
        }
    }
    let value = origin;
    if let Some(argument) = kir.scalar_parameter(function, value)? {
        let scalar = kir_semantic_scalar_v1(function.signature.parameters.get(argument as usize)?)?;
        return kir.scalar_argument(function, argument, scalar);
    }
    let operation = kir.definition(value)?;
    let scalar = kir.scalar_result(function, operation, value)?;
    let next = depth.checked_add(1)?;
    if let OperationKind::Call { arguments, .. } = &operation.kind {
        return helpers.call(
            function,
            kir,
            semantic_sites,
            kir.definition_location(value)?,
            operation,
            arguments,
            next,
            visiting,
            budget,
        );
    }
    if let OperationKind::Binary {
        op: BinaryOp::Checked(operator),
        lhs,
        rhs,
    } = &operation.kind
        && operation
            .results
            .get(1)
            .is_some_and(|result| result.id == value)
    {
        let [payload, overflow] = operation.results.as_slice() else {
            return None;
        };
        let integer = kir_semantic_scalar_v1(&payload.ty)?;
        checked_arithmetic_scalar_v41(integer)?;
        if scalar != ProductionSemanticScalarTypeV2::Bool
            || overflow.ty != Type::BOOL
            || payload.id == overflow.id
            || kir_value_scalar_v1(function, kir, *lhs)? != integer
            || kir_value_scalar_v1(function, kir, *rhs)? != integer
        {
            return None;
        }
        let operands = [*lhs, *rhs];
        let next = next.checked_add(CHECKED_ARITHMETIC_DEPTH_V41)?;
        return normalize_checked_overflow_v41(*operator, integer, budget, |index, budget| {
            match index {
                Some(index) => normalize_kir_expression_with_visiting_v18(
                    function,
                    kir,
                    semantic_sites,
                    operands[index],
                    next,
                    visiting,
                    budget,
                    helpers,
                )
                .map(Some),
                None => {
                    helpers.charge_normalization_node_v1()?;
                    Some(None)
                }
            }
        });
    }
    let mut recurse = |operand,
                       visiting: &mut dyn ScalarValueVisitingV18,
                       budget: &mut dyn CorrelationChargeV18| {
        normalize_kir_expression_with_visiting_v18(
            function,
            kir,
            semantic_sites,
            operand,
            next,
            visiting,
            budget,
            helpers,
        )
    };
    Some(match &operation.kind {
        OperationKind::Intrinsic(intrinsic) => {
            source_global_invocation_intrinsic_v35(intrinsic, scalar)?
        }
        OperationKind::InlineAssembly(_) => {
            return kir
                .inline_scalar()
                .normalize(operation, value, budget, |input, budget| {
                    recurse(input, visiting, budget)
                });
        }
        OperationKind::Constant(constant) => {
            let (constant_scalar, bits) = normalize_kir_constant_v1(constant)?;
            if constant_scalar != scalar {
                return None;
            }
            NormalizedScalarExpressionV1::Constant { scalar, bits }
        }
        OperationKind::Unary { op, operand } => NormalizedScalarExpressionV1::Unary {
            operation: match op {
                UnaryOp::Not => ProductionSemanticUnaryOpV2::Not,
                UnaryOp::Negate => ProductionSemanticUnaryOpV2::Negate,
            },
            scalar,
            operand: normalized_scalar_box_v18(recurse(*operand, visiting, budget)?, budget)?,
        },
        OperationKind::Binary { op, lhs, rhs } => {
            let (operation, overflow) = normalize_kir_binary_v1(*op, operation, value)?;
            let overflow = kir.scalar_binary_overflow(function, value, overflow)?;
            NormalizedScalarExpressionV1::Binary {
                operation,
                scalar,
                overflow,
                lhs: normalized_scalar_box_v18(recurse(*lhs, visiting, budget)?, budget)?,
                rhs: normalized_scalar_box_v18(recurse(*rhs, visiting, budget)?, budget)?,
            }
        }
        OperationKind::Compare {
            predicate,
            lhs,
            rhs,
        } => {
            let lhs_scalar = kir_value_scalar_v1(function, kir, *lhs)?;
            NormalizedScalarExpressionV1::Compare {
                operation: normalize_kir_comparison_v1(*predicate),
                operand_scalar: lhs_scalar,
                lhs: normalized_scalar_box_v18(recurse(*lhs, visiting, budget)?, budget)?,
                rhs: normalized_scalar_box_v18(recurse(*rhs, visiting, budget)?, budget)?,
            }
        }
        OperationKind::Select {
            condition,
            true_value,
            false_value,
        } => NormalizedScalarExpressionV1::Select {
            scalar,
            condition: normalized_scalar_box_v18(recurse(*condition, visiting, budget)?, budget)?,
            when_true: normalized_scalar_box_v18(recurse(*true_value, visiting, budget)?, budget)?,
            when_false: normalized_scalar_box_v18(
                recurse(*false_value, visiting, budget)?,
                budget,
            )?,
        },
        OperationKind::Cast { kind, value, to } => {
            let source = kir_value_scalar_v1(function, kir, *value)?;
            let target = kir_semantic_scalar_v1(to)?;
            let operand = recurse(*value, visiting, budget)?;
            if source == target {
                operand
            } else {
                NormalizedScalarExpressionV1::Cast {
                    kind: normalize_kir_cast_v1(*kind, source, target)?,
                    source,
                    target,
                    operand: normalized_scalar_box_v18(operand, budget)?,
                }
            }
        }
        OperationKind::Load { .. } => {
            let location = kir.definition_location(value)?;
            let site = semantic_sites.access_site(location, 0)?;
            NormalizedScalarExpressionV1::Load { site, scalar }
        }
        _ => return None,
    })
}

fn kir_value_scalar_v1(
    function: &Function,
    kir: &dyn KirCorrelationGraphV18,
    value: ValueId,
) -> Option<ProductionSemanticScalarTypeV2> {
    kir.scalar_type(function, value)
}

fn kir_semantic_scalar_v1(ty: &Type) -> Option<ProductionSemanticScalarTypeV2> {
    let Type::Scalar(scalar) = ty else {
        return None;
    };
    Some(match scalar {
        ScalarType::Bool => ProductionSemanticScalarTypeV2::Bool,
        ScalarType::I8 => ProductionSemanticScalarTypeV2::Integer {
            signed: true,
            bits: 8,
        },
        ScalarType::I16 => ProductionSemanticScalarTypeV2::Integer {
            signed: true,
            bits: 16,
        },
        ScalarType::I32 => ProductionSemanticScalarTypeV2::Integer {
            signed: true,
            bits: 32,
        },
        ScalarType::I64 => ProductionSemanticScalarTypeV2::Integer {
            signed: true,
            bits: 64,
        },
        ScalarType::U8 => ProductionSemanticScalarTypeV2::Integer {
            signed: false,
            bits: 8,
        },
        ScalarType::U16 => ProductionSemanticScalarTypeV2::Integer {
            signed: false,
            bits: 16,
        },
        ScalarType::U32 => ProductionSemanticScalarTypeV2::Integer {
            signed: false,
            bits: 32,
        },
        ScalarType::U64 | ScalarType::Index => ProductionSemanticScalarTypeV2::Integer {
            signed: false,
            bits: 64,
        },
        ScalarType::F32 => ProductionSemanticScalarTypeV2::Float { bits: 32 },
        ScalarType::F64 => ProductionSemanticScalarTypeV2::Float { bits: 64 },
        ScalarType::I128 | ScalarType::U128 | ScalarType::F16 | ScalarType::Bf16 => return None,
    })
}

fn normalize_kir_constant_v1(constant: &Constant) -> Option<(ProductionSemanticScalarTypeV2, u64)> {
    let bits = match constant {
        Constant::Bool(value) => u64::from(*value),
        Constant::I8(value) => u64::from(*value as u8),
        Constant::I16(value) => u64::from(*value as u16),
        Constant::I32(value) => u64::from(*value as u32),
        Constant::I64(value) => *value as u64,
        Constant::U8(value) => u64::from(*value),
        Constant::U16(value) => u64::from(*value),
        Constant::U32(value) => u64::from(*value),
        Constant::U64(value) | Constant::Index(value) | Constant::F64Bits(value) => *value,
        Constant::F32Bits(value) => u64::from(*value),
        Constant::F16Bits(_) | Constant::Bf16Bits(_) => return None,
    };
    Some((kir_semantic_scalar_v1(&constant.ty())?, bits))
}

fn normalize_kir_binary_v1(
    operation: BinaryOp,
    definition: &Operation,
    value: ValueId,
) -> Option<(ProductionSemanticBinaryOpV2, ProductionOverflowContractV2)> {
    if matches!(
        operation,
        BinaryOp::Add | BinaryOp::Subtract | BinaryOp::Multiply
    ) && definition
        .results
        .iter()
        .find(|result| result.id == value)?
        .ty
        .as_scalar()?
        .is_integer()
    {
        // Plain KIR arithmetic is partial on overflow. A value match alone
        // cannot establish the no-overflow premise needed to use it here.
        return None;
    }
    let (operation, overflow) = match operation {
        BinaryOp::Add => (
            ProductionSemanticBinaryOpV2::Add,
            ProductionOverflowContractV2::Wrapping,
        ),
        BinaryOp::Subtract => (
            ProductionSemanticBinaryOpV2::Subtract,
            ProductionOverflowContractV2::Wrapping,
        ),
        BinaryOp::Multiply => (
            ProductionSemanticBinaryOpV2::Multiply,
            ProductionOverflowContractV2::Wrapping,
        ),
        BinaryOp::Divide => (
            ProductionSemanticBinaryOpV2::Divide,
            ProductionOverflowContractV2::Wrapping,
        ),
        BinaryOp::Remainder => (
            ProductionSemanticBinaryOpV2::Remainder,
            ProductionOverflowContractV2::Wrapping,
        ),
        BinaryOp::BitAnd => (
            ProductionSemanticBinaryOpV2::BitAnd,
            ProductionOverflowContractV2::Wrapping,
        ),
        BinaryOp::BitOr => (
            ProductionSemanticBinaryOpV2::BitOr,
            ProductionOverflowContractV2::Wrapping,
        ),
        BinaryOp::BitXor => (
            ProductionSemanticBinaryOpV2::BitXor,
            ProductionOverflowContractV2::Wrapping,
        ),
        BinaryOp::ShiftLeft => (
            ProductionSemanticBinaryOpV2::ShiftLeft,
            ProductionOverflowContractV2::Wrapping,
        ),
        BinaryOp::ShiftRight => (
            ProductionSemanticBinaryOpV2::ShiftRight,
            ProductionOverflowContractV2::Wrapping,
        ),
        BinaryOp::Checked(operation) => {
            if definition.results.first().map(|result| result.id) != Some(value) {
                return None;
            }
            let operation = match operation {
                CheckedBinaryOperator::Add => ProductionSemanticBinaryOpV2::Add,
                CheckedBinaryOperator::Subtract => ProductionSemanticBinaryOpV2::Subtract,
                CheckedBinaryOperator::Multiply => ProductionSemanticBinaryOpV2::Multiply,
            };
            (operation, ProductionOverflowContractV2::Checked)
        }
    };
    Some((operation, overflow))
}

const fn normalize_kir_comparison_v1(
    predicate: ComparePredicate,
) -> ProductionSemanticComparisonV2 {
    match predicate {
        ComparePredicate::Equal => ProductionSemanticComparisonV2::Equal,
        ComparePredicate::NotEqual => ProductionSemanticComparisonV2::NotEqual,
        ComparePredicate::LessThan => ProductionSemanticComparisonV2::LessThan,
        ComparePredicate::LessThanOrEqual => ProductionSemanticComparisonV2::LessOrEqual,
        ComparePredicate::GreaterThan => ProductionSemanticComparisonV2::GreaterThan,
        ComparePredicate::GreaterThanOrEqual => ProductionSemanticComparisonV2::GreaterOrEqual,
    }
}

fn normalize_kir_cast_v1(
    kind: CastKind,
    source: ProductionSemanticScalarTypeV2,
    target: ProductionSemanticScalarTypeV2,
) -> Option<ProductionSemanticCastV2> {
    match kind {
        CastKind::Truncate | CastKind::ZeroExtend | CastKind::SignExtend | CastKind::Bitcast
            if matches!(
                (source, target),
                (
                    ProductionSemanticScalarTypeV2::Bool
                        | ProductionSemanticScalarTypeV2::Integer { .. },
                    ProductionSemanticScalarTypeV2::Bool
                        | ProductionSemanticScalarTypeV2::Integer { .. }
                )
            ) =>
        {
            Some(ProductionSemanticCastV2::Integer)
        }
        CastKind::FloatExtend | CastKind::FloatTruncate | CastKind::Bitcast
            if source.is_float() && target.is_float() =>
        {
            Some(ProductionSemanticCastV2::FloatToFloat)
        }
        CastKind::IntegerToFloat if source.is_integer() && target.is_float() => {
            Some(ProductionSemanticCastV2::IntegerToFloat)
        }
        CastKind::FloatToInteger if source.is_float() && target.is_integer() => {
            Some(ProductionSemanticCastV2::FloatToIntegerSaturating)
        }
        _ => None,
    }
}

fn expected_gfx950_workgroup_allocation_identity_v1(
    operation: &Operation,
    operation_access_ordinal: u32,
) -> Option<(u64, u64)> {
    let format = match &operation.kind {
        OperationKind::Gfx950LdsTranspose(Gfx950LdsTransposeOperationV1 {
            kind: Gfx950LdsTransposeOperationKindV1::Stage { format, .. },
            ..
        }) if operation_access_ordinal == 1 => *format,
        OperationKind::Gfx950LdsTranspose(Gfx950LdsTransposeOperationV1 {
            kind: Gfx950LdsTransposeOperationKindV1::Read { format, .. },
            ..
        }) if operation_access_ordinal == 0 => *format,
        _ => return None,
    };
    Some(match format {
        Gfx950LdsTransposeFormatV1::Fp4E2M1 => (
            dialect_kernel::GFX950_TRANSPOSE_FP4_WORKGROUP_ALLOCATION_ORIGIN_V1,
            dialect_kernel::GFX950_TRANSPOSE_FP4_WORKGROUP_NOALIAS_CLASS_V1,
        ),
        Gfx950LdsTransposeFormatV1::Fp8E4M3 => (
            dialect_kernel::GFX950_TRANSPOSE_FP8_WORKGROUP_ALLOCATION_ORIGIN_V1,
            dialect_kernel::GFX950_TRANSPOSE_FP8_WORKGROUP_NOALIAS_CLASS_V1,
        ),
    })
}

const NEUTRAL_WORKGROUP_RECIPE_IDENTITY_DOMAIN_V1: &[u8] =
    b"FE2O3/NEUTRAL-WORKGROUP-ALLOCATION/V1\0";
const NEUTRAL_WORKGROUP_SCAN_RECIPE_IDENTITY_DOMAIN_V1: &[u8] =
    b"FE2O3/NEUTRAL-WORKGROUP-SCAN-ALLOCATION/V1\0";

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NeutralWorkgroupRecipeKindV1 {
    Reduction,
    InclusiveScan,
    ExclusiveScan,
}

impl NeutralWorkgroupRecipeKindV1 {
    const fn from_scan(kind: SemanticWorkgroupScanKindV1) -> Self {
        match kind {
            SemanticWorkgroupScanKindV1::Inclusive => Self::InclusiveScan,
            SemanticWorkgroupScanKindV1::Exclusive => Self::ExclusiveScan,
        }
    }

    const fn identity_tag(self) -> u8 {
        match self {
            Self::Reduction => 0,
            Self::InclusiveScan => 1,
            Self::ExclusiveScan => 2,
        }
    }
}

#[derive(Clone, Copy)]
struct NeutralWorkgroupRecipeContractV1 {
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
    producer_block: u32,
    consumer_block: u32,
    kind: NeutralWorkgroupRecipeKindV1,
    elements: u32,
    scalar: ScalarType,
    recipe_identity: [u8; 32],
    allocation_origin: u64,
    noalias_class: u64,
    input: ValueId,
    output: ValueId,
}

#[derive(Clone, Copy)]
struct NeutralWorkgroupRecipeIdentityInputV1 {
    producer_block: u32,
    consumer_block: u32,
    dynamic_lds: SemanticTypeIdV1,
    element_storage: SemanticTypeIdV1,
    element: SemanticTypeIdV1,
    elements: u32,
    scalar_tag: u8,
    kind: NeutralWorkgroupRecipeKindV1,
}

fn neutral_workgroup_recipe_identity_from_semantic_v1(
    function: &SemanticFunctionDeclV1,
    input: NeutralWorkgroupRecipeIdentityInputV1,
) -> [u8; 32] {
    let mut hasher = Sha256::new();
    match input.kind {
        NeutralWorkgroupRecipeKindV1::Reduction => {
            hasher.update(NEUTRAL_WORKGROUP_RECIPE_IDENTITY_DOMAIN_V1);
            hasher.update(b"recipe-v1\0");
        }
        NeutralWorkgroupRecipeKindV1::InclusiveScan
        | NeutralWorkgroupRecipeKindV1::ExclusiveScan => {
            hasher.update(NEUTRAL_WORKGROUP_SCAN_RECIPE_IDENTITY_DOMAIN_V1);
            hasher.update(b"scan-recipe-v1\0");
            hasher.update([input.kind.identity_tag()]);
        }
    }
    hasher.update(function.identity().as_bytes());
    for value in [
        u64::from(input.producer_block),
        u64::from(input.consumer_block),
        u64::from(input.dynamic_lds.index()),
        u64::from(input.element_storage.index()),
        u64::from(input.element.index()),
        u64::from(input.elements),
        u64::from(input.scalar_tag),
    ] {
        hasher.update(value.to_le_bytes());
    }
    hasher.finalize().into()
}

fn neutral_workgroup_recipe_contracts_v1(
    semantic: &AdmittedInertSemanticMirV1,
    correspondence: &SemanticKirCorrespondenceV1,
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
) -> Result<Vec<(u32, NeutralWorkgroupRecipeContractV1)>, ProductionMirPlironTranslationErrorV1> {
    neutral_workgroup_recipe_contracts_core_v18(
        semantic,
        &LegacyGeneratedRecipeSourceV18 {
            correspondence,
            body: None,
            owner: correspondence_owner,
            function: semantic_function,
        },
        correspondence_owner,
        semantic_function,
    )
}

fn neutral_workgroup_recipe_contracts_core_v18(
    semantic: &AdmittedInertSemanticMirV1,
    source: &dyn GeneratedRecipeSourceV18,
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
) -> Result<Vec<(u32, NeutralWorkgroupRecipeContractV1)>, ProductionMirPlironTranslationErrorV1> {
    let function = semantic
        .functions()
        .get(semantic_function.index() as usize)
        .ok_or(ProductionMirPlironTranslationErrorV1::KernelShape)?;
    let mut producers_count = 0usize;
    let mut contracts_count = 0usize;
    for block in function.blocks() {
        source.charge(4)?;
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        let Some(SemanticCallableDeclV1::CompilerIntrinsic { operation, .. }) =
            semantic.callables().get(call.callee().index() as usize)
        else {
            continue;
        };
        if call
            .destination()
            .is_some_and(|destination| destination.place().projections().is_empty())
        {
            producers_count = producers_count
                .checked_add(1)
                .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
        }
        if matches!(
            operation,
            SemanticCompilerIntrinsicOperationV1::NeutralWorkgroupReduceSum { .. }
                | SemanticCompilerIntrinsicOperationV1::NeutralWorkgroupScanSum { .. }
        ) {
            contracts_count = contracts_count
                .checked_add(1)
                .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
        }
    }
    let mut producers = generated_rows_v18(source, producers_count)?;
    for (block_index, block) in function.blocks().iter().enumerate() {
        source.charge(4)?;
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        let Some(destination) = call.destination() else {
            continue;
        };
        if !destination.place().projections().is_empty() {
            continue;
        }
        let Some(SemanticCallableDeclV1::CompilerIntrinsic { operation, .. }) =
            semantic.callables().get(call.callee().index() as usize)
        else {
            continue;
        };
        generated_push_v18(
            &mut producers,
            (destination.place().local().index(), block_index, operation),
        )?;
    }
    if producers.len() != producers_count {
        return Err(ProductionMirPlironTranslationErrorV1::ResourceLimit);
    }
    generated_sort_v18(&mut producers, |row| [row.0 as usize, row.1], source)?;
    let mut contracts = generated_rows_v18(source, contracts_count)?;
    for (consumer_block, block) in function.blocks().iter().enumerate() {
        source.charge(24)?;
        let SemanticTerminatorKindV1::Call(call) = block.terminator().kind() else {
            continue;
        };
        let Some(SemanticCallableDeclV1::CompilerIntrinsic { operation, .. }) =
            semantic.callables().get(call.callee().index() as usize)
        else {
            continue;
        };
        let (context, dynamic_lds, element_storage, element, kind) = match operation {
            SemanticCompilerIntrinsicOperationV1::NeutralWorkgroupReduceSum {
                context,
                dynamic_lds,
                element_storage,
                element,
            } => (
                context,
                dynamic_lds,
                element_storage,
                element,
                NeutralWorkgroupRecipeKindV1::Reduction,
            ),
            SemanticCompilerIntrinsicOperationV1::NeutralWorkgroupScanSum {
                context,
                dynamic_lds,
                element_storage,
                element,
                kind,
            } => (
                context,
                dynamic_lds,
                element_storage,
                element,
                NeutralWorkgroupRecipeKindV1::from_scan(*kind),
            ),
            _ => continue,
        };
        let [context_argument, dynamic_argument, value] = call.arguments() else {
            return Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: consumer_block as u32,
                    semantic_effect_ordinal: 0,
                },
            );
        };
        let (SemanticOperandV1::Copy(dynamic_place) | SemanticOperandV1::Move(dynamic_place)) =
            dynamic_argument
        else {
            return Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: consumer_block as u32,
                    semantic_effect_ordinal: 0,
                },
            );
        };
        let Some(destination) = call.destination() else {
            return Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: consumer_block as u32,
                    semantic_effect_ordinal: 0,
                },
            );
        };
        let context_is_exact = matches!(
            semantic
                .types()
                .get(context_argument.ty().index() as usize)
                .map(SemanticTypeDeclV1::shape),
            Some(SemanticTypeShapeV1::Pointer(pointer))
                if pointer.pointee() == *context
                    && pointer.kind() == SemanticPointerKindV1::Reference
                    && pointer.mutability() == SemanticMutabilityV1::Immutable
                    && pointer.address_space() == 0
                    && pointer.pointer_width_bits() == 64
                    && pointer.metadata() == SemanticPointerMetadataV1::None
        );
        if !context_is_exact
            || !dynamic_place.projections().is_empty()
            || dynamic_place.ty() != *dynamic_lds
            || value.ty() != *element
            || !destination.place().projections().is_empty()
        {
            return Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: consumer_block as u32,
                    semantic_effect_ordinal: 0,
                },
            );
        }
        let range = generated_range_v18(
            &producers,
            |row| [row.0 as usize],
            [dynamic_place.local().index() as usize],
            source,
        )?;
        let [(_, producer_block, producer)] = &producers[range] else {
            return Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: consumer_block as u32,
                    semantic_effect_ordinal: 0,
                },
            );
        };
        let SemanticCompilerIntrinsicOperationV1::DynamicLdsExactCurrent {
            dynamic_lds: producer_dynamic_lds,
            element_storage: producer_storage,
            elements,
            ..
        } = producer
        else {
            return Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: consumer_block as u32,
                    semantic_effect_ordinal: 0,
                },
            );
        };
        let elements = u32::try_from(*elements).map_err(|_| {
            ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                semantic_block: consumer_block as u32,
                semantic_effect_ordinal: 0,
            }
        })?;
        let (scalar, scalar_tag) = match semantic
            .types()
            .get(element.index() as usize)
            .map(|ty| ty.shape())
        {
            Some(SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Integer {
                signed: false,
                bits: 32,
            })) => (ScalarType::U32, 1),
            Some(SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Integer {
                signed: true,
                bits: 32,
            })) => (ScalarType::I32, 2),
            Some(SemanticTypeShapeV1::Scalar(SemanticScalarTypeV1::Float { bits: 32 })) => {
                (ScalarType::F32, 3)
            }
            _ => {
                return Err(
                    ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                        semantic_block: consumer_block as u32,
                        semantic_effect_ordinal: 0,
                    },
                );
            }
        };
        let extent_is_supported = elements != 0
            && elements <= 256
            && (kind != NeutralWorkgroupRecipeKindV1::Reduction || elements.is_power_of_two());
        if *producer_dynamic_lds != *dynamic_lds
            || *producer_storage != *element_storage
            || !extent_is_supported
        {
            return Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: consumer_block as u32,
                    semantic_effect_ordinal: 0,
                },
            );
        }
        let recipe_identity = neutral_workgroup_recipe_identity_from_semantic_v1(
            function,
            NeutralWorkgroupRecipeIdentityInputV1 {
                producer_block: *producer_block as u32,
                consumer_block: consumer_block as u32,
                dynamic_lds: *dynamic_lds,
                element_storage: *element_storage,
                element: *element,
                elements,
                scalar_tag,
                kind,
            },
        );
        let (allocation_origin, noalias_class) =
            dialect_kernel::neutral_workgroup_allocation_contract_v1(recipe_identity);
        let values = source.values(consumer_block as u32).ok_or(
            ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                semantic_block: consumer_block as u32,
                semantic_effect_ordinal: 0,
            },
        )?;
        if values.destination_local != destination.place().local() {
            return Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: consumer_block as u32,
                    semantic_effect_ordinal: 0,
                },
            );
        }
        generated_push_v18(
            &mut contracts,
            (
                consumer_block as u32,
                NeutralWorkgroupRecipeContractV1 {
                    correspondence_owner,
                    semantic_function,
                    producer_block: *producer_block as u32,
                    consumer_block: consumer_block as u32,
                    kind,
                    elements,
                    scalar,
                    recipe_identity,
                    allocation_origin,
                    noalias_class,
                    input: values.input,
                    output: values.output,
                },
            ),
        )?;
    }
    if contracts.len() != contracts_count {
        return Err(ProductionMirPlironTranslationErrorV1::ResourceLimit);
    }
    generated_sort_v18(&mut contracts, |row| [row.0 as usize], source)?;
    for pair in contracts.windows(2) {
        source.charge(2)?;
        if pair[0].0 >= pair[1].0 {
            return Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: pair[1].0,
                    semantic_effect_ordinal: 0,
                },
            );
        }
    }
    Ok(contracts)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NormalizedGeneratedExecutableEffectV1 {
    Memory {
        access: dialect_kernel::AccessKindAttr,
        memory_space: dialect_kernel::MemorySpaceAttr,
        allocation_origin: u64,
        noalias_class: u64,
    },
    Synchronization(NormalizedSynchronizationV1),
}

#[derive(Clone, Copy)]
struct ReplayedGeneratedEffectV1 {
    effect: NormalizedGeneratedExecutableEffectV1,
    location: FunctionOperationLocation,
    operation_access_ordinal: u32,
}

#[derive(Clone, Copy)]
struct ValidatedGeneratedMemoryEffectV1 {
    semantic_block: u32,
    semantic_effect_ordinal: u32,
    ranked_block: u32,
    ranked_operation: u32,
}

#[derive(Default)]
struct ValidatedGeneratedEffectsV1 {
    memory: Vec<GeneratedMemoryRowV18>,
    locations: Vec<GeneratedLocationRowV18>,
}

struct GeneratedMemoryRowV18 {
    location: FunctionOperationLocation,
    access: u32,
    insertion: usize,
    value: ValidatedGeneratedMemoryEffectV1,
}

struct GeneratedLocationRowV18 {
    location: (u32, u32),
    semantic_block: u32,
    effect: u32,
    insertion: usize,
}

fn generated_memory_key_v18(row: &GeneratedMemoryRowV18) -> [usize; 3] {
    [
        row.location.block.0 as usize,
        row.location.operation_index,
        row.access as usize,
    ]
}

impl ValidatedGeneratedEffectsV1 {
    fn memory(
        &self,
        location: FunctionOperationLocation,
        access: u32,
        budget: &mut dyn CorrelationChargeV18,
    ) -> Result<Option<&ValidatedGeneratedMemoryEffectV1>, ProductionMirPlironTranslationErrorV1>
    {
        let key = [
            location.block.0 as usize,
            location.operation_index,
            access as usize,
        ];
        let index = private_array_partition_v1(
            &self.memory,
            generated_memory_key_v18,
            key,
            false,
            &mut PrivateArrayCorrelationWorkV1 { budget },
        )?;
        Ok(self
            .memory
            .get(index)
            .filter(|row| generated_memory_key_v18(row) == key)
            .map(|row| &row.value))
    }

    fn has_location(
        &self,
        location: (u32, u32),
        budget: &mut dyn CorrelationChargeV18,
    ) -> Result<bool, ProductionMirPlironTranslationErrorV1> {
        let key = [location.0 as usize, location.1 as usize];
        let index = private_array_partition_v1(
            &self.locations,
            |row| [row.location.0 as usize, row.location.1 as usize],
            key,
            false,
            &mut PrivateArrayCorrelationWorkV1 { budget },
        )?;
        Ok(self
            .locations
            .get(index)
            .is_some_and(|row| row.location == location))
    }
}

fn exact_operation_result_v1(operation: &Operation, ty: &Type) -> Option<ValueId> {
    let [result] = operation.results.as_slice() else {
        return None;
    };
    (&result.ty == ty).then_some(result.id)
}

fn exact_workgroup_sum_result_v1(
    operation: &Operation,
    scalar: &Type,
    lhs: ValueId,
    rhs: ValueId,
) -> Option<ValueId> {
    let OperationKind::Binary {
        op,
        lhs: actual_lhs,
        rhs: actual_rhs,
    } = &operation.kind
    else {
        return None;
    };
    if *actual_lhs != lhs || *actual_rhs != rhs {
        return None;
    }
    match scalar {
        Type::Scalar(ScalarType::U32 | ScalarType::I32)
            if *op == BinaryOp::Checked(CheckedBinaryOperator::Add) =>
        {
            let [value, overflow] = operation.results.as_slice() else {
                return None;
            };
            (&value.ty == scalar && overflow.ty == Type::BOOL && value.id != overflow.id)
                .then_some(value.id)
        }
        Type::Scalar(ScalarType::F32) if *op == BinaryOp::Add => {
            exact_operation_result_v1(operation, scalar)
        }
        _ => None,
    }
}

fn is_exact_neutral_barrier_v1(operation: &Operation) -> bool {
    matches!(
        &operation.kind,
        OperationKind::WorkgroupBarrier(WorkgroupBarrier {
            memory_scope: SynchronizationScope::Workgroup,
            semantics,
            convergence: Convergence::Uniform {
                scope: SynchronizationScope::Workgroup,
            },
        }) if semantics.ordering == MemoryOrdering::AcquireRelease
            && semantics.address_spaces == BTreeSet::from([AddressSpace::Workgroup])
    )
}

fn take_neutral_recipe_operation_v1<'a>(
    operations: &'a NeutralRecipeOperationsV18<'a>,
    cursor: &mut usize,
    semantic_block: u32,
    effect_ordinal: u32,
) -> Result<(&'a Operation, FunctionOperationLocation), ProductionMirPlironTranslationErrorV1> {
    let result = operations.get(*cursor).ok_or(
        ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
            semantic_block,
            semantic_effect_ordinal: effect_ordinal,
        },
    )?;
    *cursor = cursor
        .checked_add(1)
        .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
    Ok(result)
}

fn unique_ssa_operation_origin_v1(
    body: &FunctionBody,
    kir: &dyn KirCorrelationGraphV18,
    value: ValueId,
) -> Option<ValueId> {
    let mut pending = vec![value];
    let mut visited = BTreeSet::new();
    let mut origins = BTreeSet::new();
    while let Some(value) = pending.pop() {
        if !visited.insert(value) {
            continue;
        }
        if kir.definition(value).is_some() {
            origins.insert(value);
            if origins.len() > 1 {
                return None;
            }
            continue;
        }
        let mut parameter = body.blocks.iter().filter_map(|block| {
            block
                .parameters
                .iter()
                .position(|candidate| candidate.id == value)
                .map(|ordinal| (block.id, ordinal))
        });
        let (target, ordinal) = parameter.next()?;
        if parameter.next().is_some() {
            return None;
        }
        let mut incoming = 0_usize;
        let mut append = |edge_target: BlockId, arguments: &[ValueId]| -> Option<()> {
            if edge_target != target {
                return Some(());
            }
            pending.push(*arguments.get(ordinal)?);
            incoming = incoming.checked_add(1)?;
            Some(())
        };
        for predecessor in &body.blocks {
            match predecessor.terminator.as_ref()? {
                Terminator::Branch { target, arguments } => append(*target, arguments)?,
                Terminator::ConditionalBranch {
                    then_target,
                    then_arguments,
                    else_target,
                    else_arguments,
                    ..
                } => {
                    append(*then_target, then_arguments)?;
                    append(*else_target, else_arguments)?;
                }
                Terminator::Switch {
                    cases,
                    default_target,
                    default_arguments,
                    ..
                } => {
                    for case in cases {
                        append(case.target, &case.arguments)?;
                    }
                    append(*default_target, default_arguments)?;
                }
                Terminator::IntegerSwitch {
                    cases,
                    default_target,
                    default_arguments,
                    ..
                } => {
                    for case in cases {
                        append(case.target, &case.arguments)?;
                    }
                    append(*default_target, default_arguments)?;
                }
                Terminator::Return { .. } | Terminator::Unreachable => {}
            }
        }
        if incoming == 0 {
            return None;
        }
    }
    let mut origins = origins.into_iter();
    let origin = origins.next()?;
    origins.next().is_none().then_some(origin)
}

#[allow(clippy::too_many_arguments)]
fn replay_neutral_memory_event_v1<'a>(
    operations: &'a NeutralRecipeOperationsV18<'a>,
    cursor: &mut usize,
    contract: NeutralWorkgroupRecipeContractV1,
    events: &mut Vec<ReplayedGeneratedEffectV1>,
    scalar: &Type,
    pointer: ValueId,
    kind: dialect_kernel::AccessKindAttr,
    effect_ordinal: u32,
) -> Result<&'a Operation, ProductionMirPlironTranslationErrorV1> {
    let mismatch = || ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
        semantic_block: contract.consumer_block,
        semantic_effect_ordinal: effect_ordinal,
    };
    let (operation, location) = take_neutral_recipe_operation_v1(
        operations,
        cursor,
        contract.consumer_block,
        effect_ordinal,
    )?;
    let valid_access = |access: &MemoryAccess| {
        access.address_space == AddressSpace::Workgroup && access.alignment == 4 && !access.volatile
    };
    let valid = match (&operation.kind, kind) {
        (
            OperationKind::Store {
                pointer: actual,
                access,
                ..
            },
            dialect_kernel::AccessKindAttr::Write,
        ) => *actual == pointer && valid_access(access),
        (
            OperationKind::Load {
                pointer: actual,
                access,
            },
            dialect_kernel::AccessKindAttr::Read,
        ) => {
            *actual == pointer
                && valid_access(access)
                && exact_operation_result_v1(operation, scalar).is_some()
        }
        _ => false,
    };
    if !valid {
        return Err(mismatch());
    }
    generated_push_v18(
        events,
        ReplayedGeneratedEffectV1 {
            effect: NormalizedGeneratedExecutableEffectV1::Memory {
                access: kind,
                memory_space: dialect_kernel::MemorySpaceAttr::Workgroup,
                allocation_origin: contract.allocation_origin,
                noalias_class: contract.noalias_class,
            },
            location,
            operation_access_ordinal: 0,
        },
    )?;
    Ok(operation)
}

#[allow(clippy::too_many_arguments)]
fn replay_neutral_barrier_event_v1(
    operations: &NeutralRecipeOperationsV18<'_>,
    cursor: &mut usize,
    contract: NeutralWorkgroupRecipeContractV1,
    events: &mut Vec<ReplayedGeneratedEffectV1>,
    effect_ordinal: u32,
) -> Result<(), ProductionMirPlironTranslationErrorV1> {
    let (operation, location) = take_neutral_recipe_operation_v1(
        operations,
        cursor,
        contract.consumer_block,
        effect_ordinal,
    )?;
    if !is_exact_neutral_barrier_v1(operation) {
        return Err(
            ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                semantic_block: contract.consumer_block,
                semantic_effect_ordinal: effect_ordinal,
            },
        );
    }
    generated_push_v18(
        events,
        ReplayedGeneratedEffectV1 {
            effect: NormalizedGeneratedExecutableEffectV1::Synchronization(
                NormalizedSynchronizationV1 {
                    execution_scope: Some(normalize_kir_scope_v1(SynchronizationScope::Workgroup)),
                    memory_scope: normalize_kir_scope_v1(SynchronizationScope::Workgroup),
                    ordering: normalize_kir_order_v1(MemoryOrdering::AcquireRelease)
                        .ok_or(ProductionMirPlironTranslationErrorV1::SynchronizationMismatch)?,
                    address_space: normalize_kir_address_space_v1(AddressSpace::Workgroup),
                },
            ),
            location,
            operation_access_ordinal: 0,
        },
    )?;
    Ok(())
}

fn replay_neutral_workgroup_reduce_recipe_core_v18(
    contract: NeutralWorkgroupRecipeContractV1,
    body: &FunctionBody,
    source: &dyn GeneratedRecipeSourceV18,
    kir: &dyn KirCorrelationGraphV18,
) -> Result<Vec<ReplayedGeneratedEffectV1>, ProductionMirPlironTranslationErrorV1> {
    let mismatch = |ordinal| ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
        semantic_block: contract.consumer_block,
        semantic_effect_ordinal: ordinal,
    };
    let operations = source
        .operations(contract.consumer_block)
        .ok_or_else(|| mismatch(0))?;
    let scalar = Type::Scalar(contract.scalar);
    let pointer_ty = Type::pointer(
        scalar.clone(),
        AddressSpace::Workgroup,
        AccessMode::ReadWrite,
    );
    let mut cursor = 0_usize;
    let expected_events = contract
        .elements
        .checked_ilog2()
        .and_then(|rounds| rounds.checked_mul(5))
        .and_then(|events| events.checked_add(4))
        .and_then(|events| usize::try_from(events).ok())
        .ok_or_else(|| mismatch(0))?;
    let mut events = generated_rows_v18(source, expected_events)?;
    macro_rules! next_operation {
        ($ordinal:expr) => {
            take_neutral_recipe_operation_v1(
                &operations,
                &mut cursor,
                contract.consumer_block,
                $ordinal,
            )?
        };
    }
    if operations.get(0).is_some_and(|(operation, _)| {
        matches!(operation.kind, OperationKind::Constant(_))
            && exact_operation_result_v1(operation, &scalar) == Some(contract.input)
    }) {
        cursor = 1;
    }
    let (rank_operation, _) = next_operation!(0);
    let rank = match &rank_operation.kind {
        OperationKind::Intrinsic(IntrinsicOperation {
            kind:
                IntrinsicKind::InvocationIndex {
                    kind: IndexKind::Local,
                    axis: Axis::X,
                },
            result_type: Type::Scalar(ScalarType::Index),
        }) => exact_operation_result_v1(rank_operation, &Type::INDEX),
        _ => None,
    }
    .ok_or_else(|| mismatch(0))?;
    let (initial_gep, _) = next_operation!(0);
    let (base, initial_pointer) = match &initial_gep.kind {
        OperationKind::GetElementPointer { base, offset } if *offset == rank => {
            (*base, exact_operation_result_v1(initial_gep, &pointer_ty))
        }
        _ => (ValueId(u32::MAX), None),
    };
    let initial_pointer = initial_pointer.ok_or_else(|| mismatch(0))?;
    let allocation_base = source
        .operation_origin(body, kir, base)
        .ok_or_else(|| mismatch(0))?;
    let allocation = kir.definition(allocation_base).ok_or_else(|| mismatch(0))?;
    let allocation_location = kir
        .definition_location(allocation_base)
        .ok_or_else(|| mismatch(0))?;
    if source.producer_contains(contract.producer_block, allocation_location) != Some(true) {
        return Err(mismatch(0));
    }
    if !matches!(
        &allocation.kind,
        OperationKind::WorkgroupMemory(WorkgroupMemory {
            element,
            extent: WorkgroupMemoryExtent::Static(elements),
            alignment: 4,
        }) if element == &scalar && *elements == contract.elements
    ) || exact_operation_result_v1(allocation, &pointer_ty) != Some(allocation_base)
    {
        return Err(mismatch(0));
    }
    let initial_store = replay_neutral_memory_event_v1(
        &operations,
        &mut cursor,
        contract,
        &mut events,
        &scalar,
        initial_pointer,
        dialect_kernel::AccessKindAttr::Write,
        0,
    )?;
    if !matches!(
        &initial_store.kind,
        OperationKind::Store { value, .. } if *value == contract.input
    ) {
        return Err(mismatch(0));
    }
    let mut effect_ordinal = 1_u32;
    replay_neutral_barrier_event_v1(
        &operations,
        &mut cursor,
        contract,
        &mut events,
        effect_ordinal,
    )?;
    effect_ordinal += 1;
    let mut offset = contract.elements >> 1;
    while offset != 0 {
        let (offset_operation, _) = next_operation!(effect_ordinal);
        let offset_value = match &offset_operation.kind {
            OperationKind::Constant(Constant::Index(value)) if *value == u64::from(offset) => {
                exact_operation_result_v1(offset_operation, &Type::INDEX)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let (active_operation, _) = next_operation!(effect_ordinal);
        let active = match &active_operation.kind {
            OperationKind::Compare {
                predicate: ComparePredicate::LessThan,
                lhs,
                rhs,
            } if *lhs == rank && *rhs == offset_value => {
                exact_operation_result_v1(active_operation, &Type::BOOL)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let (pair_operation, _) = next_operation!(effect_ordinal);
        let pair = match &pair_operation.kind {
            OperationKind::Binary {
                op: BinaryOp::Add,
                lhs,
                rhs,
            } if *lhs == rank && *rhs == offset_value => {
                exact_operation_result_v1(pair_operation, &Type::INDEX)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let (zero_operation, _) = next_operation!(effect_ordinal);
        let zero = match &zero_operation.kind {
            OperationKind::Constant(Constant::Index(0)) => {
                exact_operation_result_v1(zero_operation, &Type::INDEX)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let (safe_operation, _) = next_operation!(effect_ordinal);
        let safe_pair = match &safe_operation.kind {
            OperationKind::Select {
                condition,
                true_value,
                false_value,
            } if *condition == active && *true_value == pair && *false_value == zero => {
                exact_operation_result_v1(safe_operation, &Type::INDEX)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let (lhs_gep, _) = next_operation!(effect_ordinal);
        let lhs_pointer = match &lhs_gep.kind {
            OperationKind::GetElementPointer {
                base: actual_base,
                offset,
            } if *actual_base == base && *offset == rank => {
                exact_operation_result_v1(lhs_gep, &pointer_ty)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let lhs_operation = replay_neutral_memory_event_v1(
            &operations,
            &mut cursor,
            contract,
            &mut events,
            &scalar,
            lhs_pointer,
            dialect_kernel::AccessKindAttr::Read,
            effect_ordinal,
        )?;
        let lhs = exact_operation_result_v1(lhs_operation, &scalar)
            .ok_or_else(|| mismatch(effect_ordinal))?;
        effect_ordinal += 1;
        let (rhs_gep, _) = next_operation!(effect_ordinal);
        let rhs_pointer = match &rhs_gep.kind {
            OperationKind::GetElementPointer {
                base: actual_base,
                offset,
            } if *actual_base == base && *offset == safe_pair => {
                exact_operation_result_v1(rhs_gep, &pointer_ty)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let rhs_operation = replay_neutral_memory_event_v1(
            &operations,
            &mut cursor,
            contract,
            &mut events,
            &scalar,
            rhs_pointer,
            dialect_kernel::AccessKindAttr::Read,
            effect_ordinal,
        )?;
        let rhs = exact_operation_result_v1(rhs_operation, &scalar)
            .ok_or_else(|| mismatch(effect_ordinal))?;
        effect_ordinal += 1;
        let (sum_operation, _) = next_operation!(effect_ordinal);
        let sum = exact_workgroup_sum_result_v1(sum_operation, &scalar, lhs, rhs)
            .ok_or_else(|| mismatch(effect_ordinal))?;
        let (select_operation, _) = next_operation!(effect_ordinal);
        let selected = match &select_operation.kind {
            OperationKind::Select {
                condition,
                true_value,
                false_value,
            } if *condition == active && *true_value == sum && *false_value == lhs => {
                exact_operation_result_v1(select_operation, &scalar)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        replay_neutral_barrier_event_v1(
            &operations,
            &mut cursor,
            contract,
            &mut events,
            effect_ordinal,
        )?;
        effect_ordinal += 1;
        let (store_gep, _) = next_operation!(effect_ordinal);
        let store_pointer = match &store_gep.kind {
            OperationKind::GetElementPointer {
                base: actual_base,
                offset,
            } if *actual_base == base && *offset == rank => {
                exact_operation_result_v1(store_gep, &pointer_ty)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let store_operation = replay_neutral_memory_event_v1(
            &operations,
            &mut cursor,
            contract,
            &mut events,
            &scalar,
            store_pointer,
            dialect_kernel::AccessKindAttr::Write,
            effect_ordinal,
        )?;
        if !matches!(
            &store_operation.kind,
            OperationKind::Store { value, .. } if *value == selected
        ) {
            return Err(mismatch(effect_ordinal));
        }
        effect_ordinal += 1;
        replay_neutral_barrier_event_v1(
            &operations,
            &mut cursor,
            contract,
            &mut events,
            effect_ordinal,
        )?;
        effect_ordinal += 1;
        offset >>= 1;
    }
    let (zero_operation, _) = next_operation!(effect_ordinal);
    let zero = match &zero_operation.kind {
        OperationKind::Constant(Constant::Index(0)) => {
            exact_operation_result_v1(zero_operation, &Type::INDEX)
        }
        _ => None,
    }
    .ok_or_else(|| mismatch(effect_ordinal))?;
    let (final_gep, _) = next_operation!(effect_ordinal);
    let final_pointer = match &final_gep.kind {
        OperationKind::GetElementPointer {
            base: actual_base,
            offset,
        } if *actual_base == base && *offset == zero => {
            exact_operation_result_v1(final_gep, &pointer_ty)
        }
        _ => None,
    }
    .ok_or_else(|| mismatch(effect_ordinal))?;
    let final_load = replay_neutral_memory_event_v1(
        &operations,
        &mut cursor,
        contract,
        &mut events,
        &scalar,
        final_pointer,
        dialect_kernel::AccessKindAttr::Read,
        effect_ordinal,
    )?;
    if exact_operation_result_v1(final_load, &scalar) != Some(contract.output) {
        return Err(mismatch(effect_ordinal));
    }
    effect_ordinal += 1;
    replay_neutral_barrier_event_v1(
        &operations,
        &mut cursor,
        contract,
        &mut events,
        effect_ordinal,
    )?;
    effect_ordinal += 1;
    let expected_effects = contract
        .elements
        .ilog2()
        .checked_mul(5)
        .and_then(|effects| effects.checked_add(4))
        .ok_or_else(|| mismatch(effect_ordinal))?;
    if cursor != operations.len() || effect_ordinal != expected_effects {
        return Err(mismatch(effect_ordinal));
    }
    Ok(events)
}

fn exact_scalar_additive_identity_v1(scalar: ScalarType) -> Constant {
    match scalar {
        ScalarType::U32 => Constant::U32(0),
        ScalarType::I32 => Constant::I32(0),
        ScalarType::F32 => Constant::F32Bits(0.0_f32.to_bits()),
        _ => unreachable!("neutral workgroup recipe admission limits scalar types"),
    }
}

fn replay_neutral_workgroup_scan_recipe_core_v18(
    contract: NeutralWorkgroupRecipeContractV1,
    body: &FunctionBody,
    source: &dyn GeneratedRecipeSourceV18,
    kir: &dyn KirCorrelationGraphV18,
) -> Result<Vec<ReplayedGeneratedEffectV1>, ProductionMirPlironTranslationErrorV1> {
    let mismatch = |ordinal| ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
        semantic_block: contract.consumer_block,
        semantic_effect_ordinal: ordinal,
    };
    let operations = source
        .operations(contract.consumer_block)
        .ok_or_else(|| mismatch(0))?;
    let scalar = Type::Scalar(contract.scalar);
    let pointer_ty = Type::pointer(
        scalar.clone(),
        AddressSpace::Workgroup,
        AccessMode::ReadWrite,
    );
    let mut cursor = 0_usize;
    let expected_events = Some(workgroup_scan_rounds_v1(contract.elements))
        .and_then(|rounds| rounds.checked_mul(5))
        .and_then(|events| events.checked_add(4))
        .and_then(|events| usize::try_from(events).ok())
        .ok_or_else(|| mismatch(0))?;
    let mut events = generated_rows_v18(source, expected_events)?;
    macro_rules! next_operation {
        ($ordinal:expr) => {
            take_neutral_recipe_operation_v1(
                &operations,
                &mut cursor,
                contract.consumer_block,
                $ordinal,
            )?
        };
    }

    if operations.get(0).is_some_and(|(operation, _)| {
        matches!(operation.kind, OperationKind::Constant(_))
            && exact_operation_result_v1(operation, &scalar) == Some(contract.input)
    }) {
        cursor = 1;
    }

    let (rank_operation, _) = next_operation!(0);
    let rank = match &rank_operation.kind {
        OperationKind::Intrinsic(IntrinsicOperation {
            kind:
                IntrinsicKind::InvocationIndex {
                    kind: IndexKind::Local,
                    axis: Axis::X,
                },
            result_type: Type::Scalar(ScalarType::Index),
        }) => exact_operation_result_v1(rank_operation, &Type::INDEX),
        _ => None,
    }
    .ok_or_else(|| mismatch(0))?;
    let (initial_gep, _) = next_operation!(0);
    let (base, initial_pointer) = match &initial_gep.kind {
        OperationKind::GetElementPointer { base, offset } if *offset == rank => {
            (*base, exact_operation_result_v1(initial_gep, &pointer_ty))
        }
        _ => (ValueId(u32::MAX), None),
    };
    let initial_pointer = initial_pointer.ok_or_else(|| mismatch(0))?;
    let allocation_base = source
        .operation_origin(body, kir, base)
        .ok_or_else(|| mismatch(0))?;
    let allocation = kir.definition(allocation_base).ok_or_else(|| mismatch(0))?;
    let allocation_location = kir
        .definition_location(allocation_base)
        .ok_or_else(|| mismatch(0))?;
    if source.producer_contains(contract.producer_block, allocation_location) != Some(true) {
        return Err(mismatch(0));
    }
    if !matches!(
        &allocation.kind,
        OperationKind::WorkgroupMemory(WorkgroupMemory {
            element,
            extent: WorkgroupMemoryExtent::Static(elements),
            alignment: 4,
        }) if element == &scalar && *elements == contract.elements
    ) || exact_operation_result_v1(allocation, &pointer_ty) != Some(allocation_base)
    {
        return Err(mismatch(0));
    }
    let initial_store = replay_neutral_memory_event_v1(
        &operations,
        &mut cursor,
        contract,
        &mut events,
        &scalar,
        initial_pointer,
        dialect_kernel::AccessKindAttr::Write,
        0,
    )?;
    if !matches!(
        &initial_store.kind,
        OperationKind::Store { value, .. } if *value == contract.input
    ) {
        return Err(mismatch(0));
    }
    let mut effect_ordinal = 1_u32;
    replay_neutral_barrier_event_v1(
        &operations,
        &mut cursor,
        contract,
        &mut events,
        effect_ordinal,
    )?;
    effect_ordinal += 1;

    let mut offset = 1_u32;
    while offset < contract.elements {
        let (offset_operation, _) = next_operation!(effect_ordinal);
        let offset_value = match &offset_operation.kind {
            OperationKind::Constant(Constant::Index(value)) if *value == u64::from(offset) => {
                exact_operation_result_v1(offset_operation, &Type::INDEX)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let (active_operation, _) = next_operation!(effect_ordinal);
        let active = match &active_operation.kind {
            OperationKind::Compare {
                predicate: ComparePredicate::GreaterThanOrEqual,
                lhs,
                rhs,
            } if *lhs == rank && *rhs == offset_value => {
                exact_operation_result_v1(active_operation, &Type::BOOL)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let (safe_rank_operation, _) = next_operation!(effect_ordinal);
        let safe_rank = match &safe_rank_operation.kind {
            OperationKind::Select {
                condition,
                true_value,
                false_value,
            } if *condition == active && *true_value == rank && *false_value == offset_value => {
                exact_operation_result_v1(safe_rank_operation, &Type::INDEX)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let (source_operation, _) = next_operation!(effect_ordinal);
        let safe_source = match &source_operation.kind {
            OperationKind::Binary {
                op: BinaryOp::Subtract,
                lhs,
                rhs,
            } if *lhs == safe_rank && *rhs == offset_value => {
                exact_operation_result_v1(source_operation, &Type::INDEX)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let (current_gep, _) = next_operation!(effect_ordinal);
        let current_pointer = match &current_gep.kind {
            OperationKind::GetElementPointer {
                base: actual_base,
                offset,
            } if *actual_base == base && *offset == rank => {
                exact_operation_result_v1(current_gep, &pointer_ty)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let current_operation = replay_neutral_memory_event_v1(
            &operations,
            &mut cursor,
            contract,
            &mut events,
            &scalar,
            current_pointer,
            dialect_kernel::AccessKindAttr::Read,
            effect_ordinal,
        )?;
        let current = exact_operation_result_v1(current_operation, &scalar)
            .ok_or_else(|| mismatch(effect_ordinal))?;
        effect_ordinal += 1;
        let (prefix_gep, _) = next_operation!(effect_ordinal);
        let prefix_pointer = match &prefix_gep.kind {
            OperationKind::GetElementPointer {
                base: actual_base,
                offset,
            } if *actual_base == base && *offset == safe_source => {
                exact_operation_result_v1(prefix_gep, &pointer_ty)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let prefix_operation = replay_neutral_memory_event_v1(
            &operations,
            &mut cursor,
            contract,
            &mut events,
            &scalar,
            prefix_pointer,
            dialect_kernel::AccessKindAttr::Read,
            effect_ordinal,
        )?;
        let prefix = exact_operation_result_v1(prefix_operation, &scalar)
            .ok_or_else(|| mismatch(effect_ordinal))?;
        effect_ordinal += 1;
        let (sum_operation, _) = next_operation!(effect_ordinal);
        let sum = exact_workgroup_sum_result_v1(sum_operation, &scalar, prefix, current)
            .ok_or_else(|| mismatch(effect_ordinal))?;
        let (select_operation, _) = next_operation!(effect_ordinal);
        let selected = match &select_operation.kind {
            OperationKind::Select {
                condition,
                true_value,
                false_value,
            } if *condition == active && *true_value == sum && *false_value == current => {
                exact_operation_result_v1(select_operation, &scalar)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        replay_neutral_barrier_event_v1(
            &operations,
            &mut cursor,
            contract,
            &mut events,
            effect_ordinal,
        )?;
        effect_ordinal += 1;
        let (store_gep, _) = next_operation!(effect_ordinal);
        let store_pointer = match &store_gep.kind {
            OperationKind::GetElementPointer {
                base: actual_base,
                offset,
            } if *actual_base == base && *offset == rank => {
                exact_operation_result_v1(store_gep, &pointer_ty)
            }
            _ => None,
        }
        .ok_or_else(|| mismatch(effect_ordinal))?;
        let store_operation = replay_neutral_memory_event_v1(
            &operations,
            &mut cursor,
            contract,
            &mut events,
            &scalar,
            store_pointer,
            dialect_kernel::AccessKindAttr::Write,
            effect_ordinal,
        )?;
        if !matches!(
            &store_operation.kind,
            OperationKind::Store { value, .. } if *value == selected
        ) {
            return Err(mismatch(effect_ordinal));
        }
        effect_ordinal += 1;
        replay_neutral_barrier_event_v1(
            &operations,
            &mut cursor,
            contract,
            &mut events,
            effect_ordinal,
        )?;
        effect_ordinal += 1;
        offset <<= 1;
    }

    match contract.kind {
        NeutralWorkgroupRecipeKindV1::InclusiveScan => {
            let (final_gep, _) = next_operation!(effect_ordinal);
            let final_pointer = match &final_gep.kind {
                OperationKind::GetElementPointer {
                    base: actual_base,
                    offset,
                } if *actual_base == base && *offset == rank => {
                    exact_operation_result_v1(final_gep, &pointer_ty)
                }
                _ => None,
            }
            .ok_or_else(|| mismatch(effect_ordinal))?;
            let final_load = replay_neutral_memory_event_v1(
                &operations,
                &mut cursor,
                contract,
                &mut events,
                &scalar,
                final_pointer,
                dialect_kernel::AccessKindAttr::Read,
                effect_ordinal,
            )?;
            if exact_operation_result_v1(final_load, &scalar) != Some(contract.output) {
                return Err(mismatch(effect_ordinal));
            }
        }
        NeutralWorkgroupRecipeKindV1::ExclusiveScan => {
            let (one_operation, _) = next_operation!(effect_ordinal);
            let one = match &one_operation.kind {
                OperationKind::Constant(Constant::Index(1)) => {
                    exact_operation_result_v1(one_operation, &Type::INDEX)
                }
                _ => None,
            }
            .ok_or_else(|| mismatch(effect_ordinal))?;
            let (active_operation, _) = next_operation!(effect_ordinal);
            let has_predecessor = match &active_operation.kind {
                OperationKind::Compare {
                    predicate: ComparePredicate::GreaterThanOrEqual,
                    lhs,
                    rhs,
                } if *lhs == rank && *rhs == one => {
                    exact_operation_result_v1(active_operation, &Type::BOOL)
                }
                _ => None,
            }
            .ok_or_else(|| mismatch(effect_ordinal))?;
            let (safe_rank_operation, _) = next_operation!(effect_ordinal);
            let safe_rank = match &safe_rank_operation.kind {
                OperationKind::Select {
                    condition,
                    true_value,
                    false_value,
                } if *condition == has_predecessor
                    && *true_value == rank
                    && *false_value == one =>
                {
                    exact_operation_result_v1(safe_rank_operation, &Type::INDEX)
                }
                _ => None,
            }
            .ok_or_else(|| mismatch(effect_ordinal))?;
            let (predecessor_operation, _) = next_operation!(effect_ordinal);
            let safe_predecessor = match &predecessor_operation.kind {
                OperationKind::Binary {
                    op: BinaryOp::Subtract,
                    lhs,
                    rhs,
                } if *lhs == safe_rank && *rhs == one => {
                    exact_operation_result_v1(predecessor_operation, &Type::INDEX)
                }
                _ => None,
            }
            .ok_or_else(|| mismatch(effect_ordinal))?;
            let (prior_gep, _) = next_operation!(effect_ordinal);
            let prior_pointer = match &prior_gep.kind {
                OperationKind::GetElementPointer {
                    base: actual_base,
                    offset,
                } if *actual_base == base && *offset == safe_predecessor => {
                    exact_operation_result_v1(prior_gep, &pointer_ty)
                }
                _ => None,
            }
            .ok_or_else(|| mismatch(effect_ordinal))?;
            let prior_operation = replay_neutral_memory_event_v1(
                &operations,
                &mut cursor,
                contract,
                &mut events,
                &scalar,
                prior_pointer,
                dialect_kernel::AccessKindAttr::Read,
                effect_ordinal,
            )?;
            let prior = exact_operation_result_v1(prior_operation, &scalar)
                .ok_or_else(|| mismatch(effect_ordinal))?;
            let (identity_operation, _) = next_operation!(effect_ordinal);
            let identity = match &identity_operation.kind {
                OperationKind::Constant(constant)
                    if *constant == exact_scalar_additive_identity_v1(contract.scalar) =>
                {
                    exact_operation_result_v1(identity_operation, &scalar)
                }
                _ => None,
            }
            .ok_or_else(|| mismatch(effect_ordinal))?;
            let (select_operation, _) = next_operation!(effect_ordinal);
            let output = match &select_operation.kind {
                OperationKind::Select {
                    condition,
                    true_value,
                    false_value,
                } if *condition == has_predecessor
                    && *true_value == prior
                    && *false_value == identity =>
                {
                    exact_operation_result_v1(select_operation, &scalar)
                }
                _ => None,
            }
            .ok_or_else(|| mismatch(effect_ordinal))?;
            if output != contract.output {
                return Err(mismatch(effect_ordinal));
            }
        }
        NeutralWorkgroupRecipeKindV1::Reduction => return Err(mismatch(effect_ordinal)),
    }
    effect_ordinal += 1;
    replay_neutral_barrier_event_v1(
        &operations,
        &mut cursor,
        contract,
        &mut events,
        effect_ordinal,
    )?;
    effect_ordinal += 1;
    let expected_effects = workgroup_scan_rounds_v1(contract.elements)
        .checked_mul(5)
        .and_then(|effects| effects.checked_add(4))
        .ok_or_else(|| mismatch(effect_ordinal))?;
    if cursor != operations.len() || effect_ordinal != expected_effects {
        return Err(mismatch(effect_ordinal));
    }
    Ok(events)
}

fn replay_neutral_workgroup_recipe_v1(
    contract: NeutralWorkgroupRecipeContractV1,
    body: &FunctionBody,
    correspondence: &SemanticKirCorrespondenceV1,
    kir: &dyn KirCorrelationGraphV18,
) -> Result<Vec<ReplayedGeneratedEffectV1>, ProductionMirPlironTranslationErrorV1> {
    replay_neutral_workgroup_recipe_core_v18(
        contract,
        body,
        &LegacyGeneratedRecipeSourceV18 {
            correspondence,
            body: Some(body),
            owner: contract.correspondence_owner,
            function: contract.semantic_function,
        },
        kir,
    )
}

fn replay_neutral_workgroup_recipe_core_v18(
    contract: NeutralWorkgroupRecipeContractV1,
    body: &FunctionBody,
    source: &dyn GeneratedRecipeSourceV18,
    kir: &dyn KirCorrelationGraphV18,
) -> Result<Vec<ReplayedGeneratedEffectV1>, ProductionMirPlironTranslationErrorV1> {
    match contract.kind {
        NeutralWorkgroupRecipeKindV1::Reduction => {
            replay_neutral_workgroup_reduce_recipe_core_v18(contract, body, source, kir)
        }
        NeutralWorkgroupRecipeKindV1::InclusiveScan
        | NeutralWorkgroupRecipeKindV1::ExclusiveScan => {
            replay_neutral_workgroup_scan_recipe_core_v18(contract, body, source, kir)
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn validate_generated_executable_effect_relations_v1(
    semantic: Option<&AdmittedInertSemanticMirV1>,
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
    body: &FunctionBody,
    correspondence: &SemanticKirCorrespondenceV1,
    recipe: &fe2o3_pliron::ProductionRankedKernelV1,
    sources: &[ProductionRankedExecutableEffectSourceV1],
    kir: &dyn KirCorrelationGraphV18,
) -> Result<ValidatedGeneratedEffectsV1, ProductionMirPlironTranslationErrorV1> {
    validate_generated_executable_effect_relations_core_v18(
        semantic,
        correspondence_owner,
        semantic_function,
        body,
        &LegacyGeneratedRecipeSourceV18 {
            correspondence,
            body: Some(body),
            owner: correspondence_owner,
            function: semantic_function,
        },
        recipe,
        sources,
        kir,
    )
}

#[allow(clippy::too_many_arguments)]
fn validate_generated_executable_effect_relations_core_v18(
    semantic: Option<&AdmittedInertSemanticMirV1>,
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
    body: &FunctionBody,
    source_reader: &dyn GeneratedRecipeSourceV18,
    recipe: &fe2o3_pliron::ProductionRankedKernelV1,
    sources: &[ProductionRankedExecutableEffectSourceV1],
    kir: &dyn KirCorrelationGraphV18,
) -> Result<ValidatedGeneratedEffectsV1, ProductionMirPlironTranslationErrorV1> {
    let contracts = match semantic {
        Some(semantic) => neutral_workgroup_recipe_contracts_core_v18(
            semantic,
            source_reader,
            correspondence_owner,
            semantic_function,
        )?,
        None if sources.is_empty() => return Ok(ValidatedGeneratedEffectsV1::default()),
        None => {
            return Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: sources[0].semantic_block,
                    semantic_effect_ordinal: 0,
                },
            );
        }
    };
    let mut ordered_sources = generated_rows_v18(source_reader, sources.len())?;
    for source in sources {
        source_reader.charge(1)?;
        generated_push_v18(&mut ordered_sources, *source)?;
    }
    generated_sort_v18(
        &mut ordered_sources,
        |row| {
            [
                row.semantic_block as usize,
                row.semantic_effect_ordinal as usize,
            ]
        },
        source_reader,
    )?;
    let mismatch = |semantic_block, semantic_effect_ordinal| {
        ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
            semantic_block,
            semantic_effect_ordinal,
        }
    };
    let mut blocks = 0usize;
    let mut previous = None;
    for source in &ordered_sources {
        source_reader.charge(2)?;
        if previous != Some(source.semantic_block) {
            if contracts.get(blocks).map(|row| row.0) != Some(source.semantic_block) {
                return Err(mismatch(
                    ordered_sources.first().map_or(0, |row| row.semantic_block),
                    0,
                ));
            }
            blocks = blocks
                .checked_add(1)
                .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
            previous = Some(source.semantic_block);
        }
    }
    if blocks != contracts.len() {
        return Err(mismatch(
            ordered_sources
                .first()
                .map(|row| row.semantic_block)
                .or_else(|| contracts.first().map(|row| row.0))
                .unwrap_or(0),
            0,
        ));
    }
    let mut generated_memory = generated_rows_v18(source_reader, sources.len())?;
    let mut used_ranked_locations = generated_rows_v18(source_reader, sources.len())?;
    let mut allocations = generated_rows_v18(source_reader, contracts.len())?;
    let allocation_key = |row: &(u64, u64, u32)| {
        [
            (row.0 >> 32) as usize,
            row.0 as u32 as usize,
            (row.1 >> 32) as usize,
            row.1 as u32 as usize,
        ]
    };
    for (semantic_block, contract) in &contracts {
        source_reader.charge(1)?;
        generated_push_v18(
            &mut allocations,
            (
                contract.allocation_origin,
                contract.noalias_class,
                *semantic_block,
            ),
        )?;
    }
    generated_sort_v18(&mut allocations, allocation_key, source_reader)?;
    for pair in allocations.windows(2) {
        source_reader.charge(4)?;
        if allocation_key(&pair[0]) == allocation_key(&pair[1]) {
            return Err(mismatch(pair[1].2, 0));
        }
    }
    for &(semantic_block, contract) in &contracts {
        source_reader.charge(1)?;
        let range = generated_range_v18(
            &ordered_sources,
            |row| [row.semantic_block as usize],
            [semantic_block as usize],
            source_reader,
        )?;
        let ranked_sources = &ordered_sources[range];
        let replayed =
            replay_neutral_workgroup_recipe_core_v18(contract, body, source_reader, kir)?;
        if ranked_sources.len() != replayed.len() {
            return Err(mismatch(
                semantic_block,
                u32::try_from(ranked_sources.len().min(replayed.len())).unwrap_or(u32::MAX),
            ));
        }
        let mut previous_ranked = None;
        for (ordinal, (source, replayed)) in ranked_sources.iter().zip(&replayed).enumerate() {
            source_reader.charge(12)?;
            let ordinal = u32::try_from(ordinal).map_err(|_| mismatch(semantic_block, u32::MAX))?;
            if source.semantic_effect_ordinal != ordinal
                || source.origin
                    != ProductionRankedExecutableEffectOriginV1::GeneratedFromSemanticTerminator
                || source.recipe_identity != contract.recipe_identity
                || previous_ranked.is_some_and(|(block, operation): (u32, u32)| {
                    block != source.ranked_block
                        || operation.checked_add(1) != Some(source.ranked_operation)
                })
            {
                return Err(mismatch(semantic_block, ordinal));
            }
            previous_ranked = Some((source.ranked_block, source.ranked_operation));
            let ranked_operation = recipe
                .blocks()
                .get(source.ranked_block as usize)
                .and_then(|block| block.operations().get(source.ranked_operation as usize))
                .ok_or_else(|| mismatch(semantic_block, ordinal))?;
            let normalized = match ranked_operation {
                ProductionRankedOperationV1::AllocationEffect {
                    kind,
                    memory_space,
                    allocation_origin,
                    noalias_class,
                } => NormalizedGeneratedExecutableEffectV1::Memory {
                    access: *kind,
                    memory_space: *memory_space,
                    allocation_origin: *allocation_origin,
                    noalias_class: *noalias_class,
                },
                ProductionRankedOperationV1::Barrier {
                    execution_scope,
                    memory_scope,
                    address_space,
                    order,
                } => NormalizedGeneratedExecutableEffectV1::Synchronization(
                    NormalizedSynchronizationV1 {
                        execution_scope: Some(normalize_ranked_hierarchy_v1(*execution_scope)),
                        memory_scope: normalize_ranked_memory_scope_v1(*memory_scope),
                        ordering: normalize_ranked_order_v1(*order),
                        address_space: normalize_ranked_address_space_v1(*address_space),
                    },
                ),
                _ => return Err(mismatch(semantic_block, ordinal)),
            };
            if normalized != replayed.effect {
                return Err(mismatch(semantic_block, ordinal));
            }
            let insertion = used_ranked_locations.len();
            generated_push_v18(
                &mut used_ranked_locations,
                GeneratedLocationRowV18 {
                    location: (source.ranked_block, source.ranked_operation),
                    semantic_block,
                    effect: ordinal,
                    insertion,
                },
            )?;
            if matches!(
                replayed.effect,
                NormalizedGeneratedExecutableEffectV1::Memory { .. }
            ) {
                generated_push_v18(
                    &mut generated_memory,
                    GeneratedMemoryRowV18 {
                        location: replayed.location,
                        access: replayed.operation_access_ordinal,
                        insertion,
                        value: ValidatedGeneratedMemoryEffectV1 {
                            semantic_block,
                            semantic_effect_ordinal: ordinal,
                            ranked_block: source.ranked_block,
                            ranked_operation: source.ranked_operation,
                        },
                    },
                )?;
            }
        }
    }
    generated_sort_v18(
        &mut used_ranked_locations,
        |row| {
            [
                row.location.0 as usize,
                row.location.1 as usize,
                row.insertion,
            ]
        },
        source_reader,
    )?;
    generated_sort_v18(
        &mut generated_memory,
        |row| {
            let key = generated_memory_key_v18(row);
            [key[0], key[1], key[2], row.insertion]
        },
        source_reader,
    )?;
    let mut duplicate = None;
    for pair in used_ranked_locations.windows(2) {
        source_reader.charge(3)?;
        if pair[0].location == pair[1].location
            && duplicate.is_none_or(|(index, _, _)| pair[1].insertion < index)
        {
            duplicate = Some((pair[1].insertion, pair[1].semantic_block, pair[1].effect));
        }
    }
    for pair in generated_memory.windows(2) {
        source_reader.charge(4)?;
        if generated_memory_key_v18(&pair[0]) == generated_memory_key_v18(&pair[1])
            && duplicate.is_none_or(|(index, _, _)| pair[1].insertion < index)
        {
            duplicate = Some((
                pair[1].insertion,
                pair[1].value.semantic_block,
                pair[1].value.semantic_effect_ordinal,
            ));
        }
    }
    if let Some((_, block, ordinal)) = duplicate {
        return Err(mismatch(block, ordinal));
    }
    for (block, contents) in recipe.blocks().iter().enumerate() {
        source_reader.charge(1)?;
        for (operation, effect) in contents.operations().iter().enumerate() {
            source_reader.charge(2)?;
            let ProductionRankedOperationV1::AllocationEffect {
                allocation_origin,
                noalias_class,
                ..
            } = effect
            else {
                continue;
            };
            let range = generated_range_v18(
                &allocations,
                allocation_key,
                allocation_key(&(*allocation_origin, *noalias_class, 0)),
                source_reader,
            )?;
            let Some(allocation) = allocations.get(range.start).filter(|_| !range.is_empty())
            else {
                continue;
            };
            let location = (
                u32::try_from(block)
                    .map_err(|_| ProductionMirPlironTranslationErrorV1::ResourceLimit)?,
                u32::try_from(operation)
                    .map_err(|_| ProductionMirPlironTranslationErrorV1::ResourceLimit)?,
            );
            let range = generated_range_v18(
                &used_ranked_locations,
                |row| [row.location.0 as usize, row.location.1 as usize],
                [location.0 as usize, location.1 as usize],
                source_reader,
            )?;
            if range.is_empty() {
                return Err(mismatch(allocation.2, u32::MAX));
            }
        }
    }
    Ok(ValidatedGeneratedEffectsV1 {
        memory: generated_memory,
        locations: used_ranked_locations,
    })
}

#[cfg(test)]
fn validate_mir_pliron_translation_v1(
    module: &Module,
    correspondence: &SemanticKirCorrespondenceV1,
    kernel_id: &str,
    lowering: &ProductionRankedKernelLoweringInputV1,
    sources: &[ProductionRankedAccessSourceV1],
    max_operations: usize,
) -> Result<ProductionMirPlironTranslationValidationV1, ProductionMirPlironTranslationErrorV1> {
    validate_mir_pliron_translation_with_semantic_v1(
        None,
        module,
        correspondence,
        kernel_id,
        lowering,
        sources,
        &[],
        max_operations,
    )
}

#[allow(clippy::too_many_arguments)]
fn validate_mir_pliron_translation_inner_v1(
    semantic: Option<&AdmittedInertSemanticMirV1>,
    module: &Module,
    correspondence: &SemanticKirCorrespondenceV1,
    kernel_id: &str,
    recipe: &fe2o3_pliron::ProductionRankedKernelV1,
    sources: &[ProductionRankedAccessSourceV1],
    executable_effect_sources: &[ProductionRankedExecutableEffectSourceV1],
    max_operations: usize,
    helpers: &mut native_helper_value_expansion_v1::NativeValueExpansion<'_, '_>,
) -> Result<ProductionMirPlironTranslationValidationV1, ProductionMirPlironTranslationErrorV1> {
    let Some(kernel) = module
        .kernels
        .iter()
        .find(|kernel| kernel.id.as_str() == kernel_id)
    else {
        return Err(ProductionMirPlironTranslationErrorV1::KernelShape);
    };
    let Some(function) = module
        .functions
        .iter()
        .find(|function| function.id == kernel.entry)
    else {
        return Err(ProductionMirPlironTranslationErrorV1::KernelShape);
    };
    let Some(body) = function.body.as_ref() else {
        return Err(ProductionMirPlironTranslationErrorV1::KernelShape);
    };
    let work_limit = max_operations
        .checked_mul(UNSUPPORTED_INDEX_CORRELATION_STEPS_PER_OPERATION_V1)
        .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
    let mut budget = UnsupportedIndexCorrelationBudgetV1 {
        remaining: work_limit,
    };
    let mut kir = build_kir_correlation_index(body, max_operations, &mut budget)
        .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
    let (correspondence_owner, semantic_function) = correspondence
        .lowered_functions()
        .iter()
        .find(|record| {
            record.role() == SemanticKirFunctionRoleV1::KernelEntry
                && record.kernel_ir_function() == &kernel.entry
        })
        .map(|record| (record.correspondence_owner(), record.semantic_function()))
        .ok_or(ProductionMirPlironTranslationErrorV1::KernelShape)?;
    kir.inline_scalar = Gfx942InlineScalarCorrespondenceV30::build(
        semantic,
        correspondence,
        correspondence_owner,
        semantic_function,
        function,
        &kir,
        &mut budget,
    )?;
    let generated_memory_effects = validate_generated_executable_effect_relations_v1(
        semantic,
        correspondence_owner,
        semantic_function,
        body,
        correspondence,
        recipe,
        executable_effect_sources,
        &kir,
    )?;
    let semantic_sites = index_semantic_access_sites(
        correspondence,
        correspondence_owner,
        semantic_function,
        &kir,
        &mut budget,
    )
    .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
    let ranked = index_ranked_correlation(recipe, sources, max_operations, &mut budget)
        .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
    if let Some(location) = kir.unmodeled_memory_effects.first().copied() {
        return Err(
            ProductionMirPlironTranslationErrorV1::UnattributedExecutableEffect { location },
        );
    }

    let private_array_relation = PrivateArrayFinalRelationV1::new(
        module,
        correspondence,
        semantic,
        correspondence_owner,
        semantic_function,
        function,
        recipe,
        max_operations,
        &mut budget,
    )?;
    let mut source_relation = LegacyTranslationSourceV18 {
        semantic,
        correspondence,
        owner: correspondence_owner,
        function: semantic_function,
        sites: &semantic_sites,
        private_arrays: private_array_relation,
    };
    validate_translation_core_v18(
        function,
        recipe,
        &kir,
        &semantic_sites,
        &ranked,
        &generated_memory_effects,
        &kir.memory_consumers,
        &mut source_relation,
        &mut TranslationCoreScratchV18::legacy(),
        &mut budget,
        helpers,
    )
    .map(|checked| checked.translation)
}

#[allow(clippy::too_many_arguments)]
fn validate_translation_core_v18(
    function: &Function,
    recipe: &fe2o3_pliron::ProductionRankedKernelV1,
    kir: &dyn KirCorrelationGraphV18,
    semantic_sites: &dyn SemanticAccessQueriesV18,
    ranked: &dyn RankedCorrelationQueriesV18,
    generated_memory_effects: &ValidatedGeneratedEffectsV1,
    consumers: &[KirMemoryConsumerV1],
    source_relation: &mut dyn TranslationSourceRelationV18,
    scratch: &mut TranslationCoreScratchV18,
    budget: &mut dyn CorrelationChargeV18,
    helpers: &mut native_helper_value_expansion_v1::NativeValueExpansion<'_, '_>,
) -> Result<TranslationValidationV18, ProductionMirPlironTranslationErrorV1> {
    let body = function
        .body
        .as_ref()
        .ok_or(ProductionMirPlironTranslationErrorV1::KernelShape)?;
    let (correspondence_owner, semantic_function) = source_relation.diagnostic_subject();
    let mut memory_effects = 0_usize;
    let mut pending_source_storage_effects = 0_usize;
    let mut value_expressions = 0_usize;
    for consumer in consumers {
        budget
            .charge()
            .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
        let (site, current_consumer) = match source_relation.effect(*consumer, kir, budget)? {
            TranslationEffectDispositionV18::Ranked { site, consumer } => (site, consumer),
            TranslationEffectDispositionV18::LegacyCompilerStorage => continue,
            TranslationEffectDispositionV18::PendingSourceStorage => {
                pending_source_storage_effects = pending_source_storage_effects
                    .checked_add(1)
                    .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
                continue;
            }
        };
        let consumer = &current_consumer;
        if let Some(generated) = generated_memory_effects.memory(
            consumer.location,
            consumer.operation_access_ordinal,
            budget,
        )? {
            if generated.semantic_block != site.block {
                return Err(
                    ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                        semantic_block: generated.semantic_block,
                        semantic_effect_ordinal: generated.semantic_effect_ordinal,
                    },
                );
            }
            scratch
                .push_effect(
                    (
                        site,
                        consumer.location,
                        consumer.operation_access_ordinal,
                        (generated.ranked_block, generated.ranked_operation),
                    ),
                    budget,
                )
                .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
            memory_effects = memory_effects
                .checked_add(1)
                .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
            continue;
        }
        let (logical_site, source) = ranked_source_for_semantic_effect_v1(ranked, site)
            .ok_or_else(|| {
                missing_ranked_effect_v1(
                    MissingRankedEffectDiagnosticV1 {
                        correspondence_owner,
                        semantic_function,
                        site,
                        consumer: *consumer,
                    },
                    trace_missing_ranked_effect_v1,
                )
            })?;
        if source.access != consumer.access {
            return Err(ProductionMirPlironTranslationErrorV1::AccessKindMismatch {
                location: consumer.location,
            });
        }
        if source.atomic != consumer.atomic {
            return Err(
                ProductionMirPlironTranslationErrorV1::AtomicContractMismatch {
                    location: consumer.location,
                },
            );
        }
        let definition = match source.allocation {
            IndexedRankedAllocationV1::View(ProductionRankedValueV1::Local(view)) => {
                ranked.view(view)
            }
            IndexedRankedAllocationV1::View(_) => None,
            IndexedRankedAllocationV1::Direct(definition) => Some(definition),
        };
        let definition = definition.ok_or(
            ProductionMirPlironTranslationErrorV1::AllocationOriginMismatch {
                location: consumer.location,
            },
        )?;
        if definition.memory_space != consumer.memory_space {
            return Err(ProductionMirPlironTranslationErrorV1::MemorySpaceMismatch {
                location: consumer.location,
            });
        }
        if consumer.memory_space == dialect_kernel::MemorySpaceAttr::Workgroup {
            let operation = kir.operation(consumer.location).ok_or(
                ProductionMirPlironTranslationErrorV1::AllocationOriginMismatch {
                    location: consumer.location,
                },
            )?;
            let expected = expected_gfx950_workgroup_allocation_identity_v1(
                operation,
                consumer.operation_access_ordinal,
            );
            match (source.allocation, expected) {
                (IndexedRankedAllocationV1::View(_), None) => {}
                (IndexedRankedAllocationV1::Direct(definition), Some((origin, class)))
                    if definition.allocation_origin == origin
                        && definition.noalias_class == class => {}
                _ => {
                    return Err(
                        ProductionMirPlironTranslationErrorV1::AllocationOriginMismatch {
                            location: consumer.location,
                        },
                    );
                }
            }
        }
        if consumer.memory_space == dialect_kernel::MemorySpaceAttr::Global {
            let parameter = scratch
                .external_parameter(function, kir, consumer.pointer, budget)
                .ok_or(
                    ProductionMirPlironTranslationErrorV1::AllocationOriginMismatch {
                        location: consumer.location,
                    },
                )?;
            let source_parameter =
                source_relation.source_parameter(function, parameter, consumer.location)?;
            let expected_origin = u64::from(source_parameter).checked_add(1).ok_or(
                ProductionMirPlironTranslationErrorV1::AllocationOriginMismatch {
                    location: consumer.location,
                },
            )?;
            if definition.allocation_origin != expected_origin {
                return Err(
                    ProductionMirPlironTranslationErrorV1::AllocationOriginMismatch {
                        location: consumer.location,
                    },
                );
            }
        }
        if consumer.memory_space == dialect_kernel::MemorySpaceAttr::Private {
            source_relation.check_private_access(recipe, source, *consumer, site, budget)?;
        }
        let first_logical_use = scratch
            .use_location(
                (source.ranked_block, source.ranked_operation),
                ranked,
                budget,
            )
            .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
        if !first_logical_use && !matches!(source.allocation, IndexedRankedAllocationV1::Direct(_))
        {
            return Err(ProductionMirPlironTranslationErrorV1::ExtraRankedEffect {
                ranked_block: source.ranked_block,
                ranked_operation: source.ranked_operation,
            });
        }
        if let Some(ranked_value) = source.value {
            let operation = kir.operation(consumer.location).ok_or(
                ProductionMirPlironTranslationErrorV1::ValueExpressionMismatch {
                    location: consumer.location,
                },
            )?;
            let executable_value = kir_written_value_v1(operation).ok_or(
                ProductionMirPlironTranslationErrorV1::ValueExpressionMismatch {
                    location: consumer.location,
                },
            )?;
            let ProductionRankedValueV1::Local(ranked_value) = ranked_value else {
                return Err(
                    ProductionMirPlironTranslationErrorV1::ValueExpressionMismatch {
                        location: consumer.location,
                    },
                );
            };
            let (ranked_expression, numerical_contract) = ranked.expression(ranked_value).ok_or(
                ProductionMirPlironTranslationErrorV1::ValueExpressionMismatch {
                    location: consumer.location,
                },
            )?;
            if numerical_contract
                != ProductionNumericalContractV2::exact_for_expression(ranked_expression)
            {
                return Err(
                    ProductionMirPlironTranslationErrorV1::ValueExpressionMismatch {
                        location: consumer.location,
                    },
                );
            }
            let checked = validate_translation_scalar_pair_v18(
                function,
                kir,
                semantic_sites,
                executable_value,
                ranked_expression,
                recipe,
                ranked,
                consumer.location,
                scratch,
                budget,
                helpers,
            );
            let released = budget.finish_normalized_pair();
            checked?;
            released.ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
            value_expressions = value_expressions
                .checked_add(1)
                .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
        }
        if first_logical_use {
            scratch
                .push_effect(
                    (
                        logical_site,
                        consumer.location,
                        consumer.operation_access_ordinal,
                        (source.ranked_block, source.ranked_operation),
                    ),
                    budget,
                )
                .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
        }
        memory_effects = memory_effects
            .checked_add(1)
            .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
    }
    for (site, source) in ranked.sources() {
        budget
            .charge()
            .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
        let is_private = match source.allocation {
            IndexedRankedAllocationV1::View(ProductionRankedValueV1::Local(view)) => {
                ranked.view(view).is_some_and(|definition| {
                    definition.memory_space == dialect_kernel::MemorySpaceAttr::Private
                })
            }
            IndexedRankedAllocationV1::View(_) => false,
            IndexedRankedAllocationV1::Direct(definition) => {
                definition.memory_space == dialect_kernel::MemorySpaceAttr::Private
            }
        };
        let required =
            source_relation.requires_ranked_consumption(*site, source, is_private, budget)?;
        if !scratch
            .contains_location(
                (source.ranked_block, source.ranked_operation),
                ranked,
                budget,
            )
            .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?
            && required
        {
            return Err(ProductionMirPlironTranslationErrorV1::ExtraRankedEffect {
                ranked_block: source.ranked_block,
                ranked_operation: source.ranked_operation,
            });
        }
    }
    // Supplied source rows cannot hide additional effects in the actual recipe.
    // Private producer omissions retain their existing, narrower checks above.
    for (block, contents) in recipe.blocks().iter().enumerate() {
        budget
            .charge()
            .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
        for (operation, effect) in contents.operations().iter().enumerate() {
            budget
                .charge()
                .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
            let space = match effect {
                ProductionRankedOperationV1::Access { view, .. }
                | ProductionRankedOperationV1::PredicatedAccess { view, .. }
                | ProductionRankedOperationV1::ValueAccess { view, .. }
                | ProductionRankedOperationV1::AtomicAccess { view, .. }
                | ProductionRankedOperationV1::AtomicValueAccess { view, .. } => {
                    let ProductionRankedValueV1::Local(value) = view else {
                        return Err(ProductionMirPlironTranslationErrorV1::KernelShape);
                    };
                    ranked
                        .view(*value)
                        .ok_or(ProductionMirPlironTranslationErrorV1::KernelShape)?
                        .memory_space
                }
                ProductionRankedOperationV1::AllocationEffect { memory_space, .. } => *memory_space,
                _ => continue,
            };
            if space == dialect_kernel::MemorySpaceAttr::Private
                && source_relation.legacy_private_recipe_exclusion()
            {
                continue;
            }
            let location = (
                u32::try_from(block)
                    .map_err(|_| ProductionMirPlironTranslationErrorV1::ResourceLimit)?,
                u32::try_from(operation)
                    .map_err(|_| ProductionMirPlironTranslationErrorV1::ResourceLimit)?,
            );
            budget
                .charge()
                .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
            let ordinary = ranked.site(location).is_some();
            let generated = generated_memory_effects.has_location(location, budget)?;
            if ordinary == generated {
                return Err(ProductionMirPlironTranslationErrorV1::ExtraRankedEffect {
                    ranked_block: location.0,
                    ranked_operation: location.1,
                });
            }
        }
    }
    source_relation.check_effect_control_flow(body, recipe, scratch.effects(), budget)?;

    let (synchronization_effects, tensor_operations) =
        source_relation.check_contract_multisets(function, recipe, helpers)?;
    let conservative_ranked_effects = scratch
        .conservative_effects(recipe, budget)
        .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
    Ok(TranslationValidationV18 {
        pending_source_storage_effects,
        translation: ProductionMirPlironTranslationValidationV1 {
            semantic_sha256: *source_relation.semantic_sha256(),
            memory_effects,
            synchronization_effects,
            tensor_operations,
            value_expressions,
            conservative_ranked_effects,
        },
    })
}

#[allow(clippy::too_many_arguments)]
fn validate_translation_scalar_pair_v18(
    function: &Function,
    kir: &dyn KirCorrelationGraphV18,
    sites: &dyn SemanticAccessQueriesV18,
    value: ValueId,
    expression: &ProductionSemanticExpressionV2,
    recipe: &fe2o3_pliron::ProductionRankedKernelV1,
    ranked: &dyn RankedCorrelationQueriesV18,
    location: FunctionOperationLocation,
    scratch: &mut TranslationCoreScratchV18,
    budget: &mut dyn CorrelationChargeV18,
    helpers: &mut native_helper_value_expansion_v1::NativeValueExpansion<'_, '_>,
) -> Result<(), ProductionMirPlironTranslationErrorV1> {
    let mismatch = || ProductionMirPlironTranslationErrorV1::ValueExpressionMismatch { location };
    budget.begin_normalized_tree().ok_or_else(mismatch)?;
    let expected = normalize_ranked_expression_v1(expression, recipe, ranked, 0, budget)
        .ok_or_else(mismatch)?;
    budget.begin_normalized_tree().ok_or_else(mismatch)?;
    let actual = scratch
        .normalize_actual(function, kir, sites, value, budget, helpers)
        .ok_or_else(mismatch)?;
    if !scalar_value_expressions_correspond_v1(&expected, &actual, 0, budget)
        .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?
    {
        return Err(mismatch());
    }
    Ok(())
}

fn ranked_source_for_semantic_effect_v1<'index>(
    ranked: &'index dyn RankedCorrelationQueriesV18,
    site: SemanticAccessSiteV1,
) -> Option<(SemanticAccessSiteV1, &'index IndexedRankedAccessSourceV1)> {
    if let Some(source) = ranked.source(site) {
        return Some((site, source));
    }
    let source = ranked.conservative_source(site.block, site.statement)?;
    let source_site = ranked.site((source.ranked_block, source.ranked_operation))?;
    Some((source_site, source))
}

fn compiler_owned_enum_payload_access_v1(
    pointer: ValueId,
    kir: &dyn KirCorrelationGraphV18,
    correspondence: &SemanticKirCorrespondenceV1,
    visiting: &mut BTreeSet<ValueId>,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<bool> {
    budget.charge()?;
    let pointer = unique_kir_ssa_origin_v1(kir, pointer, budget)?;
    if !visiting.insert(pointer) {
        return Some(false);
    }
    let Some(definition) = kir.definition(pointer) else {
        visiting.remove(&pointer);
        return Some(false);
    };
    let Some(location) = kir.definition_location(pointer) else {
        visiting.remove(&pointer);
        return Some(false);
    };
    let synthetic_allocation = matches!(
        definition.kind,
        OperationKind::Alloca {
            address_space: AddressSpace::Private,
            ..
        }
    ) && correspondence
        .synthetic_operation_spans()
        .iter()
        .any(|span| {
            span.rule() == SemanticKirSyntheticOperationRuleV1::EnumPayloadStorage
                && operation_span_contains_v1(
                    span.kernel_ir_block(),
                    span.first_operation_ordinal(),
                    span.operation_count(),
                    location,
                )
        });
    let result = if synthetic_allocation {
        true
    } else {
        match &definition.kind {
            OperationKind::GetElementPointer { base, .. } => {
                compiler_owned_enum_payload_access_v1(*base, kir, correspondence, visiting, budget)?
            }
            OperationKind::Cast { value, .. } => compiler_owned_enum_payload_access_v1(
                *value,
                kir,
                correspondence,
                visiting,
                budget,
            )?,
            OperationKind::Select {
                true_value,
                false_value,
                ..
            } => {
                compiler_owned_enum_payload_access_v1(
                    *true_value,
                    kir,
                    correspondence,
                    visiting,
                    budget,
                )? && compiler_owned_enum_payload_access_v1(
                    *false_value,
                    kir,
                    correspondence,
                    visiting,
                    budget,
                )?
            }
            _ => false,
        }
    };
    visiting.remove(&pointer);
    Some(result)
}

fn compiler_owned_retained_local_storage_access_v1(
    consumer: KirMemoryConsumerV1,
    kir: &dyn KirCorrelationGraphV18,
    correspondence: &SemanticKirCorrespondenceV1,
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
    visiting: &mut BTreeSet<ValueId>,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<bool> {
    budget.charge()?;
    if consumer.memory_space != dialect_kernel::MemorySpaceAttr::Private
        || consumer.atomic.is_some()
    {
        return Some(false);
    }
    let operation = kir.operation(consumer.location)?;
    let exact_slot_access = match (&operation.kind, consumer.access) {
        (OperationKind::Load { pointer, access }, dialect_kernel::AccessKindAttr::Read) => {
            *pointer == consumer.pointer && access.address_space == AddressSpace::Private
        }
        (
            OperationKind::Store {
                pointer, access, ..
            },
            dialect_kernel::AccessKindAttr::Write,
        ) => *pointer == consumer.pointer && access.address_space == AddressSpace::Private,
        _ => false,
    };
    if !exact_slot_access {
        return Some(false);
    }
    compiler_owned_retained_local_storage_pointer_v1(
        consumer.pointer,
        kir,
        correspondence,
        correspondence_owner,
        semantic_function,
        visiting,
        budget,
    )
}

fn compiler_owned_retained_local_storage_pointer_v1(
    pointer: ValueId,
    kir: &dyn KirCorrelationGraphV18,
    correspondence: &SemanticKirCorrespondenceV1,
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
    visiting: &mut BTreeSet<ValueId>,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<bool> {
    budget.charge()?;
    let pointer = unique_kir_ssa_origin_v1(kir, pointer, budget)?;
    if !visiting.insert(pointer) {
        return Some(false);
    }
    let Some(definition) = kir.definition(pointer) else {
        visiting.remove(&pointer);
        return Some(false);
    };
    let Some(location) = kir.definition_location(pointer) else {
        visiting.remove(&pointer);
        return Some(false);
    };
    let synthetic_allocation = retained_local_storage_allocation_v1(
        definition,
        location,
        correspondence,
        correspondence_owner,
        semantic_function,
    );
    let result = if synthetic_allocation {
        true
    } else {
        match &definition.kind {
            OperationKind::Cast {
                kind: CastKind::RestrictPointerAccess,
                value,
                ..
            } => compiler_owned_retained_local_storage_pointer_v1(
                *value,
                kir,
                correspondence,
                correspondence_owner,
                semantic_function,
                visiting,
                budget,
            )?,
            _ => false,
        }
    };
    visiting.remove(&pointer);
    Some(result)
}

fn retained_local_storage_allocation_v1(
    definition: &Operation,
    location: FunctionOperationLocation,
    correspondence: &SemanticKirCorrespondenceV1,
    owner: SemanticFunctionIdV1,
    function: SemanticFunctionIdV1,
) -> bool {
    matches!(
        definition.kind,
        OperationKind::Alloca {
            address_space: AddressSpace::Private,
            count: None,
            ..
        }
    ) && correspondence
        .synthetic_operation_spans()
        .iter()
        .any(|span| {
            span.correspondence_owner() == owner
                && span.semantic_function() == function
                && span.rule() == SemanticKirSyntheticOperationRuleV1::RetainedLocalStorage
                && operation_span_contains_v1(
                    span.kernel_ir_block(),
                    span.first_operation_ordinal(),
                    span.operation_count(),
                    location,
                )
        })
}

fn kir_written_value_v1(operation: &Operation) -> Option<ValueId> {
    match &operation.kind {
        OperationKind::Store { value, .. } | OperationKind::GuardedStore { value, .. } => {
            Some(*value)
        }
        OperationKind::Atomic(atomic)
            if matches!(atomic.kind, AtomicKind::Store | AtomicKind::Exchange) =>
        {
            atomic.value
        }
        _ => None,
    }
}

#[derive(Debug, Eq, PartialEq)]
struct NormalizedEffectFlowV1 {
    entry_effects: BTreeSet<SemanticAccessSiteV1>,
    next_effects: BTreeSet<(SemanticAccessSiteV1, SemanticAccessSiteV1)>,
}

#[path = "production_semantic_kir_v1/effect_control_flow_v1.rs"]
mod effect_control_flow_v1;
use effect_control_flow_v1::validate_effect_control_flow_v1;
#[cfg(test)]
use effect_control_flow_v1::{expand_optional_effects_v1, ranked_total_fallback_cfg_v1};

fn effect_flow_signature_v1(
    entry: u32,
    events: &BTreeMap<u32, Vec<(u64, SemanticAccessSiteV1)>>,
    successors: &BTreeMap<u32, Vec<u32>>,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<NormalizedEffectFlowV1> {
    let mut walk = LegacyEffectSignatureV18 {
        walk: LegacyEffectWalkV18 {
            events,
            successors,
            found: BTreeSet::new(),
            visited: BTreeSet::new(),
            pending: VecDeque::new(),
        },
        signature: NormalizedEffectFlowV1 {
            entry_effects: BTreeSet::new(),
            next_effects: BTreeSet::new(),
        },
    };
    effect_flow_signature_core_v18(
        entry,
        events.iter().flat_map(|(&block, rows)| {
            rows.iter()
                .map(move |&(operation, site)| (block, operation, site))
        }),
        &mut walk,
        budget,
    )?;
    Some(walk.signature)
}

trait EffectSignatureWalkV18: EffectWalkV18 {
    fn contains_entry(&mut self, entry: u32) -> Option<bool>;
    fn reset(&mut self) -> Option<()>;
    fn emit(
        &mut self,
        from: Option<Self::Site>,
        budget: &mut dyn CorrelationChargeV18,
    ) -> Option<()>;
}

fn effect_flow_signature_core_v18<W: EffectSignatureWalkV18>(
    entry: u32,
    events: impl Iterator<Item = (u32, u64, W::Site)>,
    walk: &mut W,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<()> {
    if !walk.contains_entry(entry)? {
        return None;
    }
    walk.reset()?;
    first_reachable_effects_core_v18(entry, None, walk, budget)?;
    walk.emit(None, budget)?;
    for (block, operation, site) in events {
        budget.charge()?;
        walk.reset()?;
        first_reachable_effects_core_v18(block, Some(operation), walk, budget)?;
        walk.emit(Some(site), budget)?;
    }
    Some(())
}

trait EffectWalkV18 {
    type Site: Copy;
    fn first_event(&mut self, block: u32, after: Option<u64>) -> Option<Option<Self::Site>>;
    fn extend_successors(&mut self, block: u32) -> Option<()>;
    fn pop(&mut self) -> Option<Option<u32>>;
    fn visit(&mut self, block: u32) -> Option<bool>;
    fn found(&mut self, site: Self::Site) -> Option<()>;
}

struct LegacyEffectWalkV18<'a> {
    events: &'a BTreeMap<u32, Vec<(u64, SemanticAccessSiteV1)>>,
    successors: &'a BTreeMap<u32, Vec<u32>>,
    found: BTreeSet<SemanticAccessSiteV1>,
    visited: BTreeSet<u32>,
    pending: VecDeque<u32>,
}

impl EffectWalkV18 for LegacyEffectWalkV18<'_> {
    type Site = SemanticAccessSiteV1;
    fn first_event(
        &mut self,
        block: u32,
        after: Option<u64>,
    ) -> Option<Option<SemanticAccessSiteV1>> {
        Some(
            self.events
                .get(&block)
                .and_then(|events| {
                    events
                        .iter()
                        .find(|(operation, _)| after.is_none_or(|after| *operation > after))
                })
                .map(|(_, site)| *site),
        )
    }
    fn extend_successors(&mut self, block: u32) -> Option<()> {
        self.pending
            .extend(self.successors.get(&block)?.iter().copied());
        Some(())
    }
    fn pop(&mut self) -> Option<Option<u32>> {
        Some(self.pending.pop_front())
    }
    fn visit(&mut self, block: u32) -> Option<bool> {
        Some(self.visited.insert(block))
    }
    fn found(&mut self, site: SemanticAccessSiteV1) -> Option<()> {
        self.found.insert(site);
        Some(())
    }
}

struct LegacyEffectSignatureV18<'a> {
    walk: LegacyEffectWalkV18<'a>,
    signature: NormalizedEffectFlowV1,
}

impl EffectWalkV18 for LegacyEffectSignatureV18<'_> {
    type Site = SemanticAccessSiteV1;
    fn first_event(
        &mut self,
        block: u32,
        after: Option<u64>,
    ) -> Option<Option<SemanticAccessSiteV1>> {
        self.walk.first_event(block, after)
    }
    fn extend_successors(&mut self, block: u32) -> Option<()> {
        self.walk.extend_successors(block)
    }
    fn pop(&mut self) -> Option<Option<u32>> {
        self.walk.pop()
    }
    fn visit(&mut self, block: u32) -> Option<bool> {
        self.walk.visit(block)
    }
    fn found(&mut self, site: SemanticAccessSiteV1) -> Option<()> {
        self.walk.found(site)
    }
}

impl EffectSignatureWalkV18 for LegacyEffectSignatureV18<'_> {
    fn contains_entry(&mut self, entry: u32) -> Option<bool> {
        Some(self.walk.successors.contains_key(&entry))
    }
    fn reset(&mut self) -> Option<()> {
        self.walk.found = BTreeSet::new();
        self.walk.visited = BTreeSet::new();
        self.walk.pending = VecDeque::new();
        Some(())
    }
    fn emit(
        &mut self,
        from: Option<SemanticAccessSiteV1>,
        budget: &mut dyn CorrelationChargeV18,
    ) -> Option<()> {
        match from {
            None => self.signature.entry_effects = std::mem::take(&mut self.walk.found),
            Some(site) => {
                for next in &self.walk.found {
                    budget.charge()?;
                    self.signature.next_effects.insert((site, *next));
                }
            }
        }
        Some(())
    }
}

fn first_reachable_effects_core_v18(
    block: u32,
    after_operation: Option<u64>,
    walk: &mut impl EffectWalkV18,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<()> {
    budget.charge()?;
    if let Some(site) = walk.first_event(block, after_operation)? {
        return walk.found(site);
    }
    walk.extend_successors(block)?;
    while let Some(current) = walk.pop()? {
        budget.charge()?;
        if !walk.visit(current)? {
            continue;
        }
        if let Some(site) = walk.first_event(current, None)? {
            walk.found(site)?;
            continue;
        }
        walk.extend_successors(current)?;
    }
    Some(())
}

fn kir_terminator_successors_v1(terminator: &Terminator) -> Option<Vec<u32>> {
    let successors = match terminator {
        Terminator::Branch { target, .. } => vec![target.0],
        Terminator::ConditionalBranch {
            then_target,
            else_target,
            ..
        } => vec![then_target.0, else_target.0],
        Terminator::Switch {
            cases,
            default_target,
            ..
        } => cases
            .iter()
            .map(|case| case.target.0)
            .chain([default_target.0])
            .collect(),
        Terminator::IntegerSwitch {
            cases,
            default_target,
            ..
        } => cases
            .iter()
            .map(|case| case.target.0)
            .chain([default_target.0])
            .collect(),
        Terminator::Return { .. } | Terminator::Unreachable => Vec::new(),
    };
    Some(successors)
}

fn ranked_terminator_successors_v1(
    terminator: &fe2o3_pliron::ProductionRankedTerminatorV1,
) -> Vec<u32> {
    let (successors, count) = ranked_terminator_successors_v18(terminator);
    successors[..count].to_vec()
}

fn ranked_terminator_successors_v18(
    terminator: &fe2o3_pliron::ProductionRankedTerminatorV1,
) -> ([u32; 2], usize) {
    use fe2o3_pliron::ProductionRankedTerminatorV1 as RankedTerminator;
    match terminator {
        RankedTerminator::IndexLessThan {
            true_block,
            false_block,
            ..
        }
        | RankedTerminator::IndexLessThanArgs {
            true_block,
            false_block,
            ..
        }
        | RankedTerminator::IndexEqual {
            true_block,
            false_block,
            ..
        }
        | RankedTerminator::IndexEqualArgs {
            true_block,
            false_block,
            ..
        } => ([*true_block, *false_block], 2),
        RankedTerminator::AnalysisSplit {
            first_block,
            second_block,
            ..
        }
        | RankedTerminator::AnalysisSplitArgs {
            first_block,
            second_block,
            ..
        } => ([*first_block, *second_block], 2),
        RankedTerminator::Branch { target }
        | RankedTerminator::BranchArgs { target, .. }
        | RankedTerminator::BranchArgsAdd { target, .. }
        | RankedTerminator::BranchArgsAddAt { target, .. } => ([*target, 0], 1),
        RankedTerminator::Return | RankedTerminator::Trap => ([0, 0], 0),
    }
}

fn external_allocation_parameter_v1(
    function: &Function,
    kir: &dyn KirCorrelationGraphV18,
    value: ValueId,
    visited: &mut BTreeSet<ValueId>,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<u32> {
    function.body.as_ref()?;
    external_allocation_parameter_core_v18(
        function,
        kir,
        &mut AllocationWalkScratchV18::Legacy {
            visited,
            pending: vec![value],
            origins: BTreeSet::new(),
        },
        budget,
    )
}

fn external_allocation_parameter_core_v18(
    function: &Function,
    kir: &dyn KirCorrelationGraphV18,
    scratch: &mut AllocationWalkScratchV18<'_>,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<u32> {
    while let Some(value) = scratch.pop() {
        budget.charge()?;
        if !scratch.insert(value, kir, budget)? {
            continue;
        }
        if let Some(index) = scratch.parameter(function, kir, value)? {
            let ty = function.signature.parameters.get(index)?;
            if !matches!(ty, Type::Pointer(_) | Type::Slice(_)) {
                return None;
            }
            scratch.origin(u32::try_from(index).ok()?)?;
            continue;
        }
        if let Some(operation) = kir.definition(value) {
            match &operation.kind {
                OperationKind::SliceData { slice } => scratch.push(*slice, budget)?,
                OperationKind::GetElementPointer { base, .. } => scratch.push(*base, budget)?,
                OperationKind::Cast { value, .. } => scratch.push(*value, budget)?,
                OperationKind::Select {
                    true_value,
                    false_value,
                    ..
                } => {
                    scratch.push(*true_value, budget)?;
                    scratch.push(*false_value, budget)?;
                }
                _ => return None,
            }
            continue;
        }
        let count = kir.visit_incoming(value, &mut |input| scratch.push(input, budget))??;
        if count == 0 {
            return None;
        }
    }
    scratch.result()
}

fn unique_kir_ssa_origin_v1(
    kir: &dyn KirCorrelationGraphV18,
    value: ValueId,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<ValueId> {
    kir.unique_origin(value, budget)
}

fn walk_unique_kir_ssa_origin_v1(
    kir: &dyn KirCorrelationGraphV18,
    value: ValueId,
    budget: &mut dyn CorrelationChargeV18,
) -> Option<ValueId> {
    let mut pending = vec![value];
    let mut visited = BTreeSet::new();
    let mut origins = BTreeSet::new();
    while let Some(value) = pending.pop() {
        budget.charge()?;
        if !visited.insert(value) {
            continue;
        }
        if let Some(count) = kir.visit_incoming(value, &mut |input| {
            pending.push(input);
            Some(())
        })? {
            if count == 0 {
                return None;
            }
        } else {
            origins.insert(value);
            if origins.len() > 1 {
                return None;
            }
        }
    }
    let mut origins = origins.into_iter();
    let origin = origins.next()?;
    origins.next().is_none().then_some(origin)
}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct NormalizedSynchronizationV1 {
    execution_scope: Option<u8>,
    memory_scope: u8,
    ordering: u8,
    address_space: u8,
}

fn kir_synchronization_contracts_v1(
    body: &FunctionBody,
) -> Result<Vec<NormalizedSynchronizationV1>, ProductionMirPlironTranslationErrorV1> {
    let mut contracts = Vec::new();
    visit_kir_synchronization_contracts_v18(
        body,
        &mut TranslationContractCollectorV18::Legacy(&mut contracts),
    )?;
    contracts.sort_unstable();
    Ok(contracts)
}

fn visit_kir_synchronization_contracts_v18(
    body: &FunctionBody,
    collector: &mut TranslationContractCollectorV18<'_, '_, NormalizedSynchronizationV1>,
) -> Result<(), ProductionMirPlironTranslationErrorV1> {
    collector.charge(body.blocks.len())?;
    for operation in body.blocks.iter().flat_map(|block| &block.operations) {
        collector.charge(1)?;
        let contract = match &operation.kind {
            OperationKind::Barrier(barrier) => Some(NormalizedSynchronizationV1 {
                execution_scope: Some(normalize_kir_scope_v1(barrier.execution_scope)),
                memory_scope: normalize_kir_scope_v1(barrier.memory_scope),
                ordering: normalize_kir_order_v1(barrier.semantics.ordering)
                    .ok_or(ProductionMirPlironTranslationErrorV1::SynchronizationMismatch)?,
                address_space: singleton_kir_address_space_v1(&barrier.semantics.address_spaces)?,
            }),
            OperationKind::WorkgroupBarrier(barrier) => Some(NormalizedSynchronizationV1 {
                execution_scope: Some(normalize_kir_scope_v1(SynchronizationScope::Workgroup)),
                memory_scope: normalize_kir_scope_v1(barrier.memory_scope),
                ordering: normalize_kir_order_v1(barrier.semantics.ordering)
                    .ok_or(ProductionMirPlironTranslationErrorV1::SynchronizationMismatch)?,
                address_space: singleton_kir_address_space_v1(&barrier.semantics.address_spaces)?,
            }),
            OperationKind::Fence(fence) => Some(NormalizedSynchronizationV1 {
                execution_scope: None,
                memory_scope: normalize_kir_scope_v1(fence.memory_scope),
                ordering: normalize_kir_order_v1(fence.semantics.ordering)
                    .ok_or(ProductionMirPlironTranslationErrorV1::SynchronizationMismatch)?,
                address_space: singleton_kir_address_space_v1(&fence.semantics.address_spaces)?,
            }),
            OperationKind::Gfx950LdsTranspose(Gfx950LdsTransposeOperationV1 {
                kind: Gfx950LdsTransposeOperationKindV1::Publish { .. },
                ..
            }) => Some(NormalizedSynchronizationV1 {
                execution_scope: Some(normalize_kir_scope_v1(SynchronizationScope::Workgroup)),
                memory_scope: normalize_kir_scope_v1(SynchronizationScope::Workgroup),
                ordering: normalize_kir_order_v1(MemoryOrdering::AcquireRelease)
                    .ok_or(ProductionMirPlironTranslationErrorV1::SynchronizationMismatch)?,
                address_space: normalize_kir_address_space_v1(AddressSpace::Workgroup),
            }),
            _ => None,
        };
        let executable_synchronizations = match collector {
            TranslationContractCollectorV18::Legacy(_) => operation
                .memory_effects()
                .into_iter()
                .filter(|effect| {
                    matches!(
                        effect,
                        MemoryEffect::Synchronize { .. } | MemoryEffect::Fence { .. }
                    )
                })
                .count(),
            TranslationContractCollectorV18::Count { .. }
            | TranslationContractCollectorV18::Fill { .. } => {
                let mut count = 0usize;
                operation.try_visit_local_memory_effects_v1(|effect| {
                    collector.charge(1)?;
                    if matches!(
                        effect,
                        fe2o3_kernel_ir::KirLocalMemoryEffectRefV1::Synchronize { .. }
                            | fe2o3_kernel_ir::KirLocalMemoryEffectRefV1::Fence { .. }
                    ) {
                        count = count
                            .checked_add(1)
                            .ok_or(ProductionMirPlironTranslationErrorV1::ResourceLimit)?;
                    }
                    Ok::<_, ProductionMirPlironTranslationErrorV1>(())
                })?;
                count
            }
        };
        if executable_synchronizations != usize::from(contract.is_some()) {
            return Err(ProductionMirPlironTranslationErrorV1::SynchronizationMismatch);
        }
        if let Some(contract) = contract {
            collector.push(contract)?;
        }
    }
    Ok(())
}

fn ranked_synchronization_contracts_v1(
    kernel: &fe2o3_pliron::ProductionRankedKernelV1,
) -> Result<Vec<NormalizedSynchronizationV1>, ProductionMirPlironTranslationErrorV1> {
    let mut contracts = Vec::new();
    visit_ranked_synchronization_contracts_v18(
        kernel,
        &mut TranslationContractCollectorV18::Legacy(&mut contracts),
    )?;
    contracts.sort_unstable();
    Ok(contracts)
}

fn visit_ranked_synchronization_contracts_v18(
    kernel: &fe2o3_pliron::ProductionRankedKernelV1,
    collector: &mut TranslationContractCollectorV18<'_, '_, NormalizedSynchronizationV1>,
) -> Result<(), ProductionMirPlironTranslationErrorV1> {
    collector.charge(kernel.blocks().len())?;
    for operation in kernel.blocks().iter().flat_map(|block| block.operations()) {
        collector.charge(1)?;
        let contract = match operation {
            ProductionRankedOperationV1::Barrier {
                execution_scope,
                memory_scope,
                address_space,
                order,
            } => Some(NormalizedSynchronizationV1 {
                execution_scope: Some(normalize_ranked_hierarchy_v1(*execution_scope)),
                memory_scope: normalize_ranked_memory_scope_v1(*memory_scope),
                ordering: normalize_ranked_order_v1(*order),
                address_space: normalize_ranked_address_space_v1(*address_space),
            }),
            ProductionRankedOperationV1::Fence {
                memory_scope,
                address_space,
                order,
            } => Some(NormalizedSynchronizationV1 {
                execution_scope: None,
                memory_scope: normalize_ranked_memory_scope_v1(*memory_scope),
                ordering: normalize_ranked_order_v1(*order),
                address_space: normalize_ranked_address_space_v1(*address_space),
            }),
            _ => None,
        };
        if let Some(contract) = contract {
            collector.push(contract)?;
        }
    }
    Ok(())
}

fn normalize_kir_scope_v1(scope: SynchronizationScope) -> u8 {
    match scope {
        SynchronizationScope::Invocation => 0,
        SynchronizationScope::Subgroup => 1,
        SynchronizationScope::Workgroup => 2,
        SynchronizationScope::Device => 3,
        SynchronizationScope::System => 4,
    }
}

fn normalize_ranked_hierarchy_v1(scope: dialect_gpu::HierarchyAttr) -> u8 {
    match scope {
        dialect_gpu::HierarchyAttr::Lane => 0,
        dialect_gpu::HierarchyAttr::Subgroup => 1,
        dialect_gpu::HierarchyAttr::Workgroup => 2,
        dialect_gpu::HierarchyAttr::Grid => 3,
    }
}

fn normalize_ranked_memory_scope_v1(scope: dialect_gpu::MemoryScopeAttr) -> u8 {
    match scope {
        dialect_gpu::MemoryScopeAttr::Subgroup => 1,
        dialect_gpu::MemoryScopeAttr::Workgroup => 2,
        dialect_gpu::MemoryScopeAttr::Device => 3,
        dialect_gpu::MemoryScopeAttr::System => 4,
    }
}

fn normalize_kir_order_v1(order: MemoryOrdering) -> Option<u8> {
    match order {
        MemoryOrdering::Relaxed => None,
        MemoryOrdering::Acquire => Some(1),
        MemoryOrdering::Release => Some(2),
        MemoryOrdering::AcquireRelease => Some(3),
        MemoryOrdering::SequentiallyConsistent => Some(4),
    }
}

fn normalize_ranked_order_v1(order: dialect_gpu::MemoryOrderAttr) -> u8 {
    match order {
        dialect_gpu::MemoryOrderAttr::Acquire => 1,
        dialect_gpu::MemoryOrderAttr::Release => 2,
        dialect_gpu::MemoryOrderAttr::AcquireRelease => 3,
        dialect_gpu::MemoryOrderAttr::SequentiallyConsistent => 4,
    }
}

fn normalize_kir_address_space_v1(space: AddressSpace) -> u8 {
    match space {
        AddressSpace::Private => 0,
        AddressSpace::Workgroup => 1,
        AddressSpace::Global => 2,
        AddressSpace::Constant => 3,
        AddressSpace::Generic => 4,
    }
}

fn normalize_ranked_address_space_v1(space: dialect_gpu::AddressSpaceAttr) -> u8 {
    match space {
        dialect_gpu::AddressSpaceAttr::Private => 0,
        dialect_gpu::AddressSpaceAttr::Workgroup => 1,
        dialect_gpu::AddressSpaceAttr::Global => 2,
        dialect_gpu::AddressSpaceAttr::Constant => 3,
        dialect_gpu::AddressSpaceAttr::Generic => 4,
    }
}

fn singleton_kir_address_space_v1(
    spaces: &BTreeSet<AddressSpace>,
) -> Result<u8, ProductionMirPlironTranslationErrorV1> {
    if spaces.len() != 1 {
        return Err(ProductionMirPlironTranslationErrorV1::SynchronizationMismatch);
    }
    let space = spaces
        .first()
        .copied()
        .ok_or(ProductionMirPlironTranslationErrorV1::SynchronizationMismatch)?;
    Ok(normalize_kir_address_space_v1(space))
}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct NormalizedTensorV1 {
    contract: TensorLayoutContractV1,
    active_lanes: u32,
    convergence: u8,
}

fn kir_tensor_contracts_v1(
    body: &FunctionBody,
) -> Result<Vec<NormalizedTensorV1>, ProductionMirPlironTranslationErrorV1> {
    let mut contracts = Vec::new();
    visit_kir_tensor_contracts_v18(
        body,
        &mut TranslationContractCollectorV18::Legacy(&mut contracts),
    )?;
    contracts.sort_unstable();
    Ok(contracts)
}

fn visit_kir_tensor_contracts_v18(
    body: &FunctionBody,
    collector: &mut TranslationContractCollectorV18<'_, '_, NormalizedTensorV1>,
) -> Result<(), ProductionMirPlironTranslationErrorV1> {
    collector.charge(body.blocks.len())?;
    for operation in body.blocks.iter().flat_map(|block| &block.operations) {
        collector.charge(1)?;
        let OperationKind::Matrix(matrix) = &operation.kind else {
            continue;
        };
        let Some(contract) = matrix.tensor_layout else {
            continue;
        };
        collector.push(NormalizedTensorV1 {
            contract,
            active_lanes: matrix.active_lanes,
            convergence: normalize_kir_scope_v1(matrix.convergence.scope()),
        })?;
    }
    Ok(())
}

fn ranked_tensor_contracts_v1(
    kernel: &fe2o3_pliron::ProductionRankedKernelV1,
) -> Result<Vec<NormalizedTensorV1>, ProductionMirPlironTranslationErrorV1> {
    let mut contracts = Vec::new();
    visit_ranked_tensor_contracts_v18(
        kernel,
        &mut TranslationContractCollectorV18::Legacy(&mut contracts),
    )?;
    contracts.sort_unstable();
    Ok(contracts)
}

fn visit_ranked_tensor_contracts_v18(
    kernel: &fe2o3_pliron::ProductionRankedKernelV1,
    collector: &mut TranslationContractCollectorV18<'_, '_, NormalizedTensorV1>,
) -> Result<(), ProductionMirPlironTranslationErrorV1> {
    collector.charge(kernel.blocks().len())?;
    for operation in kernel.blocks().iter().flat_map(|block| block.operations()) {
        collector.charge(1)?;
        let ProductionRankedOperationV1::TensorLayout {
            contract,
            convergence,
            active_lanes,
            ..
        } = operation
        else {
            continue;
        };
        let convergence = match convergence {
            dialect_kernel::TensorConvergenceAttr::UniformSubgroup => 1,
            dialect_kernel::TensorConvergenceAttr::UniformWorkgroup => 2,
            dialect_kernel::TensorConvergenceAttr::Divergent
            | dialect_kernel::TensorConvergenceAttr::Opaque => {
                return Err(ProductionMirPlironTranslationErrorV1::TensorContractMismatch);
            }
        };
        collector.push(NormalizedTensorV1 {
            contract: *contract,
            active_lanes: *active_lanes,
            convergence,
        })?;
    }
    Ok(())
}

fn indexed_ranked_source_matches_allocation(
    ranked: &dyn RankedCorrelationQueriesV18,
    source: &IndexedRankedAccessSourceV1,
    expected_access: dialect_kernel::AccessKindAttr,
    expected_memory_space: dialect_kernel::MemorySpaceAttr,
    parameter_index: u32,
) -> bool {
    let definition = match source.allocation {
        IndexedRankedAllocationV1::View(ProductionRankedValueV1::Local(view)) => ranked.view(view),
        IndexedRankedAllocationV1::View(_) => None,
        IndexedRankedAllocationV1::Direct(definition) => Some(definition),
    };
    let Some(definition) = definition else {
        return false;
    };
    source.access == expected_access
        && definition.memory_space == expected_memory_space
        && u64::from(parameter_index)
            .checked_add(1)
            .is_some_and(|expected| definition.allocation_origin == expected)
}

// Keep hostile shared predicate graphs bounded independently of the lowering budget.
const GUARDED_ADDRESS_PROOF_STEPS_PER_OPERATION_V1: usize = 32;

#[derive(Clone, Copy)]
enum GuardedAddressDefinitionV1<'module> {
    Parameter,
    Operation(&'module Operation),
}

struct GuardedAddressProofBudgetV1 {
    remaining: usize,
}

struct GuardedAccessCursorV1<'a> {
    rows: &'a [FormalMemoryAccess],
    next: usize,
}

impl<'a> GuardedAccessCursorV1<'a> {
    fn observe(
        &mut self,
        location: FunctionOperationLocation,
        budget: &mut GuardedAddressProofBudgetV1,
    ) -> Result<Option<&'a FormalMemoryAccess>, ProductionMemoryDischargeFailureV1> {
        budget.prepay(2)?;
        let row = self
            .rows
            .get(self.next)
            .filter(|row| row.location() == location);
        if row.is_some() {
            budget.prepay(2)?;
            self.next += 1;
        }
        Ok(row)
    }

    fn finish(
        &self,
        budget: &mut GuardedAddressProofBudgetV1,
    ) -> Result<(), ProductionMemoryDischargeFailureV1> {
        budget.prepay(1)?;
        if self.next != self.rows.len() {
            return Err(ProductionMemoryDischargeFailureV1::stage(
                "formal access rows do not match retained Kernel IR body order",
            ));
        }
        Ok(())
    }
}

impl GuardedAddressProofBudgetV1 {
    fn new(max_operations: usize) -> Result<Self, ProductionMemoryDischargeFailureV1> {
        let remaining = max_operations
            .checked_mul(GUARDED_ADDRESS_PROOF_STEPS_PER_OPERATION_V1)
            .ok_or_else(|| {
                ProductionMemoryDischargeFailureV1::stage(
                    "guarded proof resource budget overflowed",
                )
            })?;
        Ok(Self { remaining })
    }

    fn prepay(&mut self, amount: usize) -> Result<(), ProductionMemoryDischargeFailureV1> {
        self.remaining = self.remaining.checked_sub(amount).ok_or_else(|| {
            ProductionMemoryDischargeFailureV1::stage("guarded proof exceeded its work budget")
        })?;
        Ok(())
    }

    fn charge(&mut self) -> Result<(), ()> {
        self.remaining = self.remaining.checked_sub(1).ok_or(())?;
        Ok(())
    }
}

fn guarded_accesses_have_structural_bounds_result(
    module: &Module,
    kernel: &Kernel,
    report: &FormalMemoryObligations,
    witness_extents: [u64; 3],
    guarded_locations: &[FunctionOperationLocation],
    max_operations: usize,
    budget: &mut GuardedAddressProofBudgetV1,
) -> Result<(), ProductionMemoryDischargeFailureV1> {
    budget.prepay(20)?;
    let names = kernel
        .id
        .as_str()
        .len()
        .checked_add(kernel.entry.as_str().len())
        .ok_or_else(|| {
            ProductionMemoryDischargeFailureV1::stage("guarded proof name size overflowed")
        })?;
    budget.prepay(names)?;
    let count = witness_extents
        .into_iter()
        .try_fold(1_u64, |count, extent| count.checked_mul(extent));
    if report.kernel() != &kernel.id
        || report.entry() != &kernel.entry
        || report.index_width() != FormalIndexWidth::Bits64
        || count.is_none_or(|count| count == 0)
        || report
            .invocations()
            .is_none_or(|range| range.start() != 0 || Some(range.end_exclusive()) != count)
    {
        return Err(ProductionMemoryDischargeFailureV1::stage(
            "guarded proof report does not match its kernel and exact witness",
        ));
    }
    let Some(function) = module.function(&kernel.entry) else {
        return Err(ProductionMemoryDischargeFailureV1::stage(
            "guarded proof cannot find the selected kernel entry",
        ));
    };
    let Some(body) = function.body.as_ref() else {
        return Err(ProductionMemoryDischargeFailureV1::stage(
            "guarded proof selected a kernel declaration without a body",
        ));
    };

    let mut definitions = BTreeMap::new();
    for parameter in &body.parameters {
        if definitions
            .insert(*parameter, GuardedAddressDefinitionV1::Parameter)
            .is_some()
        {
            return Err(ProductionMemoryDischargeFailureV1::stage(
                "guarded proof found a duplicate function parameter definition",
            ));
        }
    }

    let mut actual = BTreeMap::new();
    let mut operation_count = 0_usize;
    let mut cursor = GuardedAccessCursorV1 {
        rows: report.accesses(),
        next: 0,
    };
    for block in &body.blocks {
        for parameter in &block.parameters {
            if definitions
                .insert(parameter.id, GuardedAddressDefinitionV1::Parameter)
                .is_some()
            {
                return Err(ProductionMemoryDischargeFailureV1::stage(
                    "guarded proof found a duplicate block parameter definition",
                ));
            }
        }
        for (ordinal, operation) in block.operations.iter().enumerate() {
            operation_count = match operation_count.checked_add(1) {
                Some(count) if count <= max_operations => count,
                _ => {
                    return Err(ProductionMemoryDischargeFailureV1::stage(
                        "guarded proof exceeded the operation resource limit",
                    ));
                }
            };
            for result in &operation.results {
                if definitions
                    .insert(result.id, GuardedAddressDefinitionV1::Operation(operation))
                    .is_some()
                {
                    return Err(ProductionMemoryDischargeFailureV1::access(
                        FunctionOperationLocation::new(block.id, ordinal),
                        "guarded proof found a duplicate operation result definition",
                    ));
                }
            }
            // Formal rows retain body order, not numeric block order. A pending
            // load without a row must leave a later row untouched.
            let location = FunctionOperationLocation::new(block.id, ordinal);
            let row = cursor.observe(location, budget)?;
            if matches!(
                &operation.kind,
                OperationKind::GuardedLoad { access, .. }
                    if access.address_space != AddressSpace::Private
            ) {
                if guarded_load_is_core_proved_v1(
                    function, report, location, operation, row, budget,
                )? {
                    continue;
                }
                if actual.insert(location, operation).is_some() {
                    return Err(ProductionMemoryDischargeFailureV1::access(
                        location,
                        "guarded proof found a duplicate guarded-load location",
                    ));
                }
            }
        }
    }

    cursor.finish(budget)?;
    budget.prepay(3)?;
    let provided = guarded_locations.iter().copied().collect::<BTreeSet<_>>();
    if actual.is_empty()
        || provided.len() != guarded_locations.len()
        || actual.keys().copied().collect::<BTreeSet<_>>() != provided
    {
        return Err(ProductionMemoryDischargeFailureV1::stage(
            "formal guarded-load locations do not match retained Kernel IR",
        ));
    }

    for (location, operation) in actual {
        if guarded_load_has_structural_bound(operation, &definitions, budget) {
            continue;
        }
        if let Some((_predicate, index, slice)) =
            guarded_load_bound_subject(operation, &definitions)
        {
            return Err(ProductionMemoryDischargeFailureV1::guarded_bound(
                location,
                index,
                slice,
                "guard predicate does not prove the selected index is in bounds",
            ));
        }
        return Err(ProductionMemoryDischargeFailureV1::access(
            location,
            "guarded load does not retain the required slice/index/zero-fallback structure",
        ));
    }
    Ok(())
}

fn guarded_load_is_core_proved_v1(
    function: &Function,
    report: &FormalMemoryObligations,
    location: FunctionOperationLocation,
    operation: &Operation,
    row: Option<&FormalMemoryAccess>,
    budget: &mut GuardedAddressProofBudgetV1,
) -> Result<bool, ProductionMemoryDischargeFailureV1> {
    budget.prepay(2)?;
    let Some(row) = row else { return Ok(false) };
    let FormalAccessDomainV1::SliceBounded(domain) = row.domain() else {
        return Ok(false);
    };
    budget.prepay(24)?;
    let OperationKind::GuardedLoad {
        pointer,
        predicate,
        access,
        ..
    } = &operation.kind
    else {
        return Err(ProductionMemoryDischargeFailureV1::access(
            location,
            "core guarded row does not name a guarded load",
        ));
    };
    let parameter = usize::try_from(domain.allocation().parameter_index()).ok();
    let slice = parameter.and_then(|parameter| function.signature.parameters.get(parameter));
    let value = parameter.and_then(|parameter| function.body.as_ref()?.parameters.get(parameter));
    if row.location() != location
        || row.kind() != FormalMemoryAccessKind::Read
        || domain.path() != FormalGuardedPathV1::ExplicitPredicate
        || domain.pointer() != *pointer
        || domain.predicate() != *predicate
        || domain.allocation() != row.allocation()
        || value != Some(&domain.slice())
        || !matches!(slice, Some(Type::Slice(slice)) if slice.address_space == access.address_space)
        || row.address_space() != access.address_space
        || row.alignment() != u64::from(access.alignment)
        || row.byte_width() != domain.element_bytes()
        || Some(row.invocations()) != report.invocations()
    {
        return Err(ProductionMemoryDischargeFailureV1::access(
            location,
            "core guarded row differs from its exact load and formal slice subject",
        ));
    }
    Ok(true)
}

#[cfg(test)]
fn guarded_accesses_have_structural_bounds(
    module: &Module,
    guarded_locations: &[FunctionOperationLocation],
    max_operations: usize,
) -> bool {
    let [kernel] = module.kernels.as_slice() else {
        return false;
    };
    let witness_extents = match &kernel.domain {
        LaunchDomain::D1 {
            x: LaunchExtent::Static(x),
        } => [u64::from(*x), 1, 1],
        _ => return false,
    };
    let Ok(analysis) = fe2o3_kernel_ir::derive_kernel_memory_obligations_for_launch(
        module,
        &kernel.id,
        fe2o3_kernel_ir::ExplicitLaunchExtent::Exact {
            rank: 1,
            extents: witness_extents,
        },
        FormalIndexWidth::Bits64,
    ) else {
        return false;
    };
    let Ok(mut budget) = GuardedAddressProofBudgetV1::new(max_operations) else {
        return false;
    };
    guarded_accesses_have_structural_bounds_result(
        module,
        kernel,
        analysis.obligations(),
        witness_extents,
        guarded_locations,
        max_operations,
        &mut budget,
    )
    .is_ok()
}

fn guarded_load_has_structural_bound(
    operation: &Operation,
    definitions: &BTreeMap<ValueId, GuardedAddressDefinitionV1<'_>>,
    budget: &mut GuardedAddressProofBudgetV1,
) -> bool {
    let Some((predicate, index, slice)) = guarded_load_bound_subject(operation, definitions) else {
        return false;
    };
    let mut visiting = BTreeSet::new();
    let mut memo = BTreeMap::new();
    predicate_implies_slice_bound(
        predicate,
        index,
        slice,
        definitions,
        budget,
        &mut visiting,
        &mut memo,
    )
    .unwrap_or(false)
}

fn guarded_load_bound_subject(
    operation: &Operation,
    definitions: &BTreeMap<ValueId, GuardedAddressDefinitionV1<'_>>,
) -> Option<(ValueId, ValueId, ValueId)> {
    let (pointer, predicate) = match &operation.kind {
        OperationKind::GuardedLoad {
            pointer, predicate, ..
        }
        | OperationKind::GuardedStore {
            pointer, predicate, ..
        } => (*pointer, *predicate),
        _ => return None,
    };
    let Some(OperationKind::GetElementPointer { base, offset }) =
        operation_definition(definitions, pointer).map(|operation| &operation.kind)
    else {
        return None;
    };
    let Some(OperationKind::SliceData { slice }) =
        operation_definition(definitions, *base).map(|operation| &operation.kind)
    else {
        return None;
    };
    let Some(OperationKind::Select {
        condition,
        true_value: index,
        false_value,
    }) = operation_definition(definitions, *offset).map(|operation| &operation.kind)
    else {
        return None;
    };
    if *condition != predicate
        || !matches!(
            operation_definition(definitions, *false_value).map(|operation| &operation.kind),
            Some(OperationKind::Constant(Constant::Index(0)))
        )
    {
        return None;
    }
    Some((predicate, *index, *slice))
}

fn operation_definition<'module>(
    definitions: &BTreeMap<ValueId, GuardedAddressDefinitionV1<'module>>,
    value: ValueId,
) -> Option<&'module Operation> {
    match definitions.get(&value) {
        Some(GuardedAddressDefinitionV1::Operation(operation)) => Some(*operation),
        Some(GuardedAddressDefinitionV1::Parameter) | None => None,
    }
}

fn predicate_implies_slice_bound(
    predicate: ValueId,
    index: ValueId,
    slice: ValueId,
    definitions: &BTreeMap<ValueId, GuardedAddressDefinitionV1<'_>>,
    budget: &mut GuardedAddressProofBudgetV1,
    visiting: &mut BTreeSet<ValueId>,
    memo: &mut BTreeMap<ValueId, bool>,
) -> Result<bool, ()> {
    if let Some(proved) = memo.get(&predicate) {
        return Ok(*proved);
    }
    budget.charge()?;
    if !visiting.insert(predicate) {
        return Err(());
    }
    let result = match definitions.get(&predicate) {
        Some(GuardedAddressDefinitionV1::Parameter) => Ok(false),
        Some(GuardedAddressDefinitionV1::Operation(operation)) => match &operation.kind {
            OperationKind::Compare {
                predicate: ComparePredicate::LessThan,
                lhs,
                rhs,
            } if *lhs == index => match definitions.get(rhs) {
                Some(GuardedAddressDefinitionV1::Operation(operation)) if matches!(operation.kind, OperationKind::SliceLength { slice: bound_slice } if bound_slice == slice) => {
                    Ok(true)
                }
                Some(_) => Ok(false),
                None => Err(()),
            },
            OperationKind::Binary {
                op: BinaryOp::BitAnd,
                lhs,
                rhs,
            } => {
                // A true conjunction inherits a bound implied by either conjunct.
                let lhs = predicate_implies_slice_bound(
                    *lhs,
                    index,
                    slice,
                    definitions,
                    budget,
                    visiting,
                    memo,
                )?;
                let rhs = predicate_implies_slice_bound(
                    *rhs,
                    index,
                    slice,
                    definitions,
                    budget,
                    visiting,
                    memo,
                )?;
                Ok(lhs || rhs)
            }
            _ => Ok(false),
        },
        None => Err(()),
    };
    visiting.remove(&predicate);
    if let Ok(proved) = result {
        memo.insert(predicate, proved);
    }
    result
}

fn mandatory_generic_checks_are_clean(lowering: &ProductionRankedKernelLoweringInputV1) -> bool {
    lowering.all_mandatory_reports_are_clean()
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ExpectedSemanticKirBlockCoverageV1 {
    correspondence_owner: SemanticFunctionIdV1,
    semantic_function: SemanticFunctionIdV1,
    semantic_block: SemanticBlockIdV1,
    kernel_ir_block: BlockId,
    source_statement_count: u32,
}

fn validate_semantic_kir_correspondence(
    owner: &ProductionSemanticSsaOwnerV1,
    module: &Module,
    expected_roots: &[SemanticFunctionIdV1],
    limits: ProductionSemanticKirLimitsV1,
    correspondence: &SemanticKirCorrespondenceV1,
) -> Result<(), ProductionSemanticKirErrorV1> {
    owner
        .verify_replay()
        .map_err(ProductionSemanticKirErrorV1::SemanticSsa)?;
    validate_semantic_kir_correspondence_after_source_replay_v1(
        owner,
        module,
        expected_roots,
        limits,
        correspondence,
    )
}

fn validate_semantic_kir_correspondence_after_source_replay_v1(
    owner: &ProductionSemanticSsaOwnerV1,
    module: &Module,
    expected_roots: &[SemanticFunctionIdV1],
    limits: ProductionSemanticKirLimitsV1,
    correspondence: &SemanticKirCorrespondenceV1,
) -> Result<(), ProductionSemanticKirErrorV1> {
    let semantic = owner.source_semantic();
    if correspondence.semantic_sha256 != *semantic.semantic_sha256().as_bytes()
        || correspondence.function_count != semantic.functions().len()
    {
        return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
    }
    if expected_roots.is_empty()
        || module.kernels.len() != expected_roots.len()
        || expected_roots
            .iter()
            .any(|root| !semantic.roots().contains(root))
    {
        return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
    }
    let semantic_roots_by_symbol = semantic
        .roots()
        .iter()
        .map(|root_id| {
            let entry = semantic
                .functions()
                .get(root_id.index() as usize)
                .and_then(SemanticFunctionDeclV1::kernel_entry)
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let symbol = std::str::from_utf8(entry.export_symbol().as_bytes())
                .map_err(|_| ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            Ok((symbol.to_owned(), *root_id))
        })
        .collect::<Result<BTreeMap<_, _>, ProductionSemanticKirErrorV1>>()?;
    if semantic_roots_by_symbol.len() != semantic.roots().len() {
        return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
    }
    let mut expected_entries = Vec::with_capacity(module.kernels.len());
    let mut expected_helpers = Vec::new();
    let mut retained_correspondence = BTreeSet::new();
    let mut closure_budget = ReachableClosureBudgetV1::new(limits.max_blocks);
    for (kernel, expected_root_id) in module.kernels.iter().zip(expected_roots) {
        let root_id = semantic_roots_by_symbol
            .get(kernel.id.as_str())
            .copied()
            .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
        if root_id != *expected_root_id || kernel.entry.as_str() != kernel.id.as_str() {
            return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
        }
        let selection = semantic
            .select_kernel_body_for_root_v1(root_id)
            .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
        let closure = reachable_defined_closure_v1(
            semantic,
            selection.body(),
            correspondence.function_count,
            &mut closure_budget,
        )
        .map_err(|_| ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
        let entry_function = closure
            .first()
            .copied()
            .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
        if !retained_correspondence.insert((
            root_id,
            entry_function,
            FunctionId::new(kernel.id.as_str()),
        )) {
            return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
        }
        expected_entries.push(SemanticKirFunctionCorrespondenceV1 {
            correspondence_owner: root_id,
            semantic_function: entry_function,
            kernel_ir_function: FunctionId::new(kernel.id.as_str()),
            role: SemanticKirFunctionRoleV1::KernelEntry,
        });
        for function_id in closure.into_iter().skip(1) {
            let function = semantic
                .functions()
                .get(function_id.index() as usize)
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let kernel_ir_function = helper_function_id_v1(function_id, function);
            if retained_correspondence.insert((root_id, function_id, kernel_ir_function.clone())) {
                expected_helpers.push(SemanticKirFunctionCorrespondenceV1 {
                    correspondence_owner: root_id,
                    semantic_function: function_id,
                    kernel_ir_function,
                    role: SemanticKirFunctionRoleV1::InternalHelper,
                });
            }
        }
    }
    let mut expected_functions = expected_entries;
    expected_functions.extend(expected_helpers);
    if correspondence.lowered_functions.as_ref() != expected_functions.as_slice()
        || module
            .functions
            .iter()
            .filter(|function| function.body.is_some())
            .map(|function| &function.id)
            .collect::<BTreeSet<_>>()
            != expected_functions
                .iter()
                .map(|function| &function.kernel_ir_function)
                .collect::<BTreeSet<_>>()
    {
        return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
    }

    let mut block_offset = 0_usize;
    let mut statement_offset = 0_usize;
    let mut terminator_offset = 0_usize;
    let mut used_synthetic = 0_usize;
    let mut parameter_offset = 0_usize;
    let mut parameter_component_offset = 0_usize;
    let mut ignored_parameter_offset = 0_usize;
    let mut call_return_offset = 0_usize;
    let mut argument_work = fe2o3_kernel_ir::CanonicalKernelIrWorkBudgetV1::new(
        limits.max_argument_correspondence_work,
    );
    let mut argument_budget = ArgumentBudgetV1::new(
        &mut argument_work,
        limits.max_argument_correspondence_storage,
    );
    let mut check = |argument_budget: &mut ArgumentBudgetV1<'_>| {
        require_execution_free_types_v29(semantic.types(), argument_budget)?;
        argument_budget.reserve_storage(CallReturnBufferV1::bytes(
            correspondence.call_returns.len(),
            correspondence.call_result_components.len(),
        )?)?;
        argument_budget.charge_work(argument_sum_v1(&[
            correspondence.parameter_bindings.len(),
            correspondence.parameter_component_bindings.len(),
            correspondence.ignored_parameter_bindings.len(),
            correspondence.call_returns.len(),
            argument_product_v1(expected_functions.len(), 4)?,
        ])?)?;
        let call_targets = CallTargetIndexV1::new(module, &expected_functions, argument_budget)?;
        validate_call_component_pool_v1(
            &correspondence.call_returns,
            &correspondence.call_result_components,
            argument_budget,
        )?;
        for expected_function in &expected_functions {
            let correspondence_owner = match expected_function.role {
                SemanticKirFunctionRoleV1::KernelEntry => semantic_roots_by_symbol
                    .get(expected_function.kernel_ir_function.as_str())
                    .copied()
                    .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?,
                SemanticKirFunctionRoleV1::InternalHelper => expected_function.correspondence_owner,
            };
            let semantic_function = semantic
                .functions()
                .get(expected_function.semantic_function.index() as usize)
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let target =
                call_targets.physical(&expected_function.kernel_ir_function, argument_budget)?;
            if target.role
                != match expected_function.role {
                    SemanticKirFunctionRoleV1::KernelEntry => {
                        fe2o3_kernel_ir::FunctionRole::KernelEntry
                    }
                    SemanticKirFunctionRoleV1::InternalHelper => {
                        fe2o3_kernel_ir::FunctionRole::InternalHelper
                    }
                }
            {
                return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
            }
            let target_body = target
                .body
                .as_ref()
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let order = owner
                .plan_for_function(expected_function.semantic_function)
                .filter(|plan| plan.function_identity() == semantic_function.identity())
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?
                .plan()
                .reverse_postorder()
                .iter()
                .map(|block| SemanticBlockIdV1::from_index(block.get()));
            let expected_blocks = order
                .map(|semantic_block| {
                    let source = semantic_function
                        .blocks()
                        .get(semantic_block.index() as usize)
                        .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
                    Ok(ExpectedSemanticKirBlockCoverageV1 {
                        correspondence_owner,
                        semantic_function: expected_function.semantic_function,
                        semantic_block,
                        kernel_ir_block: BlockId(semantic_block.index()),
                        source_statement_count: u32::try_from(source.statements().len())
                            .map_err(|_| ProductionSemanticKirErrorV1::CorrespondenceMismatch)?,
                    })
                })
                .collect::<Result<Vec<_>, ProductionSemanticKirErrorV1>>()?;
            let statement_count = expected_blocks
                .iter()
                .try_fold(0_usize, |count, block| {
                    count.checked_add(block.source_statement_count as usize)
                })
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let block_end = block_offset
                .checked_add(expected_blocks.len())
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let statement_end = statement_offset
                .checked_add(statement_count)
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let terminator_end = terminator_offset
                .checked_add(expected_blocks.len())
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let synthetic = correspondence
                .synthetic_operation_spans
                .iter()
                .filter(|span| span.semantic_function == expected_function.semantic_function)
                .filter(|span| span.correspondence_owner == correspondence_owner)
                .cloned()
                .collect::<Vec<_>>();
            used_synthetic = used_synthetic
                .checked_add(synthetic.len())
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let runtime_assert_rule = synthetic
                .iter()
                .any(|span| {
                    span.rule == SemanticKirSyntheticOperationRuleV1::RuntimeAssertFailureTrap
                })
                .then_some(SemanticKirSyntheticOperationRuleV1::RuntimeAssertFailureTrap);
            let parameter_count = correspondence.parameter_bindings[parameter_offset..]
                .iter()
                .take_while(|binding| {
                    binding.correspondence_owner == correspondence_owner
                        && binding.semantic_function == expected_function.semantic_function
                })
                .count();
            let parameter_end = parameter_offset
                .checked_add(parameter_count)
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let parameter_component_count = correspondence.parameter_component_bindings
                [parameter_component_offset..]
                .iter()
                .take_while(|binding| {
                    binding.correspondence_owner == correspondence_owner
                        && binding.semantic_function == expected_function.semantic_function
                })
                .count();
            let parameter_component_end = parameter_component_offset
                .checked_add(parameter_component_count)
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            let ignored_parameter_count = correspondence.ignored_parameter_bindings
                [ignored_parameter_offset..]
                .iter()
                .take_while(|binding| {
                    binding.correspondence_owner == correspondence_owner
                        && binding.semantic_function == expected_function.semantic_function
                })
                .count();
            let ignored_parameter_end = ignored_parameter_offset
                .checked_add(ignored_parameter_count)
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            if !validate_operation_correspondence_layout(
                &expected_blocks,
                &target_body.blocks,
                correspondence
                    .blocks
                    .get(block_offset..block_end)
                    .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?,
                correspondence
                    .statement_operation_spans
                    .get(statement_offset..statement_end)
                    .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?,
                correspondence
                    .terminator_operation_spans
                    .get(terminator_offset..terminator_end)
                    .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?,
                &synthetic,
                runtime_assert_rule,
            ) {
                return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
            }
            validate_parameter_correspondence_with_wave64_v1(
                owner,
                expected_function,
                target,
                ArgumentTraceV1 {
                    direct: correspondence
                        .parameter_bindings
                        .get(parameter_offset..parameter_end)
                        .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?,
                    components: correspondence
                        .parameter_component_bindings
                        .get(parameter_component_offset..parameter_component_end)
                        .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?,
                    ignored: correspondence
                        .ignored_parameter_bindings
                        .get(ignored_parameter_offset..ignored_parameter_end)
                        .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?,
                },
                argument_budget,
            )?;
            let call_return_end = call_return_offset
                + correspondence.call_returns[call_return_offset..]
                    .iter()
                    .take_while(|row| {
                        row.correspondence_owner == correspondence_owner
                            && row.semantic_function == expected_function.semantic_function
                    })
                    .count();
            validate_call_correspondence_v1(
                owner,
                expected_function,
                target,
                &call_targets,
                &correspondence.call_returns[call_return_offset..call_return_end],
                &correspondence.call_result_components,
                &correspondence.terminator_operation_spans[terminator_offset..terminator_end],
                argument_budget,
            )?;
            call_return_offset = call_return_end;
            block_offset = block_end;
            statement_offset = statement_end;
            terminator_offset = terminator_end;
            parameter_offset = parameter_end;
            parameter_component_offset = parameter_component_end;
            ignored_parameter_offset = ignored_parameter_end;
        }
        if block_offset != correspondence.blocks.len()
            || statement_offset != correspondence.statement_operation_spans.len()
            || terminator_offset != correspondence.terminator_operation_spans.len()
            || used_synthetic != correspondence.synthetic_operation_spans.len()
            || parameter_offset != correspondence.parameter_bindings.len()
            || parameter_component_offset != correspondence.parameter_component_bindings.len()
            || ignored_parameter_offset != correspondence.ignored_parameter_bindings.len()
            || call_return_offset != correspondence.call_returns.len()
        {
            return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
        }
        Ok(())
    };
    if ordinary_source_has_raw_wave64_shuffle_v1(owner.source_semantic()) {
        with_canonical_call_scratch_v1(&mut argument_budget, |budget| {
            with_wave64_retained_source_input_v1(owner, budget, |budget| check(budget))
        })
    } else {
        check(&mut argument_budget)
    }
}

