#[allow(clippy::too_many_arguments)]
fn lower_one_semantic_function_for_composition_v1<'facts>(
    semantic: &fe2o3_mir_model::semantic_mir_v1::AdmittedInertSemanticMirV1,
    plan: &LoweredFunctionPlanV1,
    semantic_ssa: &ProductionSemanticSsaFunctionPlanV1,
    defined_function_ids: &BTreeMap<SemanticFunctionIdV1, FunctionId>,
    defined_function_signatures: &BTreeMap<SemanticFunctionIdV1, LoweredFunctionSignatureV1>,
    required_workgroup: Option<[u32; 3]>,
    infallible_asserts: impl Into<InfallibleAssertDecisionsV1<'facts>>,
    launch_rank: u8,
    authenticated_ranked_control: bool,
    max_operations: usize,
    assert_origins: Option<&mut AssertOriginEmissionV1<'_, '_>>,
    private_array_work: &mut PrivateArrayLazyBudgetV1,
    private_array_sources: Option<(&PrivateArrayMergeV1, Option<&PrivateArrayMergeV1>)>,
    call_budget: &mut ArgumentBudgetV1<'_>,
    placement: SemanticEmissionPlacementV1,
    execution: Option<ExecutionAvailabilityV29<'_>>,
    ordered_composition: Option<OrderedCompositionPermitV1>,
    bf16: Option<&mut Bf16CallEmissionStateV1<'_>>,
    wave64_source_owner: Option<&ProductionSemanticSsaOwnerV1>,
) -> Result<LoweredFunctionResultV1, ProductionSemanticKirErrorV1> {
    lower_one_semantic_function_with_composition_v1(
        semantic,
        plan,
        semantic_ssa,
        defined_function_ids,
        defined_function_signatures,
        required_workgroup,
        infallible_asserts,
        launch_rank,
        authenticated_ranked_control,
        max_operations,
        assert_origins,
        private_array_work,
        private_array_sources.map(|(root, outer)| PrivateArraySourcesV1::Merged(root, outer)),
        call_budget,
        placement,
        execution,
        None,
        None,
        ordered_composition,
        bf16,
        wave64_source_owner,
    )
}

#[allow(clippy::too_many_arguments)]
fn lower_one_semantic_function_with_composition_v1<'facts>(
    semantic: &fe2o3_mir_model::semantic_mir_v1::AdmittedInertSemanticMirV1,
    plan: &LoweredFunctionPlanV1,
    semantic_ssa: &ProductionSemanticSsaFunctionPlanV1,
    defined_function_ids: &BTreeMap<SemanticFunctionIdV1, FunctionId>,
    defined_function_signatures: &BTreeMap<SemanticFunctionIdV1, LoweredFunctionSignatureV1>,
    required_workgroup: Option<[u32; 3]>,
    infallible_asserts: impl Into<InfallibleAssertDecisionsV1<'facts>>,
    launch_rank: u8,
    authenticated_ranked_control: bool,
    max_operations: usize,
    mut assert_origins: Option<&mut AssertOriginEmissionV1<'_, '_>>,
    private_array_work: &mut PrivateArrayLazyBudgetV1,
    private_array_sources: Option<PrivateArraySourcesV1<'_>>,
    call_budget: &mut ArgumentBudgetV1<'_>,
    placement: SemanticEmissionPlacementV1,
    execution: Option<ExecutionAvailabilityV29<'_>>,
    execution_calls: Option<&mut dyn ExecutionDefinedCallConsumerV29>,
    lifecycle: Option<&mut dyn ExecutionLifecycleConsumerV29>,
    ordered_composition: Option<OrderedCompositionPermitV1>,
    bf16: Option<&mut Bf16CallEmissionStateV1<'_>>,
    wave64_source_owner: Option<&ProductionSemanticSsaOwnerV1>,
) -> Result<LoweredFunctionResultV1, ProductionSemanticKirErrorV1> {
    if ordered_composition.is_some_and(|permit| !permit.matches(semantic)) {
        return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
    }
    let infallible_asserts = infallible_asserts.into();
    infallible_asserts.require_source(semantic, plan)?;
    // Diagnostic cursors lack the scoped output owner that retains this charge.
    let retained_header = execution.is_some() && execution_calls.is_some() && lifecycle.is_some();
    let source_call_instance = execution.as_ref().map(|cursor| cursor.instance);
    let initialization_subject = execution
        .as_ref()
        .map(ScopedInitializationSubjectV29::from_cursor);
    if initialization_subject.is_some_and(|subject| {
        subject.source.root != plan.correspondence_owner
            || subject.function != plan.semantic_function
    }) {
        return Err(scoped_initialization_error_v29());
    }
    if source_call_instance.is_some() && assert_origins.is_some() {
        return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
    }
    let mut instance_assert_origins = execution
        .as_ref()
        .map(|cursor| InstanceAssertCaptureV1::new(cursor, placement));
    let function = semantic
        .functions()
        .get(plan.semantic_function.index() as usize)
        .ok_or_else(|| {
            unsupported(
                plan.semantic_function.index(),
                None,
                None,
                "lowered semantic function is missing",
            )
        })?;
    let has_runtime_assert = semantic_requires_runtime_assert_failure(
        function,
        semantic.callables(),
        &infallible_asserts,
    );
    let statement_count = function
        .blocks()
        .iter()
        .try_fold(0_usize, |count, block| {
            count.checked_add(block.statements().len())
        })
        .ok_or(ProductionSemanticKirErrorV1::ResourceLimit {
            resource: ProductionSemanticKirResourceV1::Statements,
            actual: usize::MAX,
            limit: usize::MAX,
        })?;
    let mut parameter_bindings = Vec::new();
    parameter_bindings
        .try_reserve_exact(plan.parameter_declarations.len())
        .map_err(|_| ProductionSemanticKirErrorV1::AllocationFailure {
            resource: ProductionSemanticKirResourceV1::DebugBindings,
        })?;
    parameter_bindings.extend(plan.parameter_local_bindings.iter().filter_map(|binding| {
        match binding {
            PlannedParameterLocalBindingV1::Direct { local, value, .. } => {
                Some(SemanticKirParameterBindingV1 {
                    correspondence_owner: plan.correspondence_owner,
                    semantic_function: plan.semantic_function,
                    semantic_local: SemanticLocalIdV1::from_index(*local as u32),
                    kernel_ir_value: *value,
                })
            }
            PlannedParameterLocalBindingV1::Flattened { .. }
            | PlannedParameterLocalBindingV1::Bf16Nominal { .. }
            | PlannedParameterLocalBindingV1::Wave64Nominal { .. } => None,
        }
    }));
    let failure_block = has_runtime_assert
        .then(|| placement.block(function.blocks().len() as u32))
        .transpose()?;
    let mut lowering = SemanticFunctionLoweringV1::new_interprocedural(
        semantic.types(),
        semantic.callables(),
        function,
        semantic_ssa,
        plan.correspondence_owner,
        plan.semantic_function,
        defined_function_ids,
        defined_function_signatures,
        &plan.result_types,
        SemanticParameterBindingsV1 {
            declarations: &plan.parameter_declarations,
            values: &plan.parameter_values,
            types: &plan.parameter_types,
            local_bindings: Some(&plan.parameter_local_bindings),
        },
        failure_block,
        required_workgroup,
        infallible_asserts.borrowed(),
        launch_rank,
        authenticated_ranked_control,
        max_operations,
        PrivateArrayRecorderWorkV1::Shared(private_array_work),
        private_array_sources,
        CallReturnBufferV1::for_function(
            function,
            semantic.callables(),
            defined_function_signatures,
            plan.result_types.len(),
            call_budget,
        )?,
        Some(call_budget),
        placement,
        execution,
        match lifecycle {
            Some(consumer) => Some(&mut *consumer as &mut (dyn ExecutionLifecycleConsumerV29 + '_)),
            None => None,
        },
        wave64_source_owner,
    )?;
    lowering.ordered_composition = ordered_composition.is_some();
    lowering.execution_calls = match execution_calls {
        Some(consumer) => Some(&mut *consumer as &mut (dyn ExecutionDefinedCallConsumerV29 + '_)),
        None => None,
    };

    let order = semantic_ssa
        .plan()
        .reverse_postorder()
        .iter()
        .map(|block| SemanticBlockIdV1::from_index(block.get()))
        .collect::<Vec<_>>();
    let mut target_blocks = Vec::with_capacity(order.len() + usize::from(has_runtime_assert));
    let mut blocks = Vec::with_capacity(order.len());
    let mut statement_operation_spans = Vec::with_capacity(statement_count);
    let mut terminator_operation_spans = Vec::with_capacity(order.len());
    let mut synthetic_operation_spans = Vec::with_capacity(usize::from(has_runtime_assert));
    for semantic_block in order {
        let index = usize::try_from(semantic_block.index()).map_err(|_| {
            unsupported(
                plan.semantic_function.index(),
                None,
                None,
                "block identity does not fit this host",
            )
        })?;
        let source = function.blocks().get(index).ok_or_else(|| {
            unsupported(
                plan.semantic_function.index(),
                Some(semantic_block.index()),
                None,
                "block is missing",
            )
        })?;
        let mut target = BasicBlock::new(lowering.kernel_block_id_v1(semantic_block)?);
        let prologue = lowering.begin_block(semantic_block, &mut target)?;
        if prologue.retained_local_storage != 0 {
            synthetic_operation_spans.push(SemanticKirSyntheticOperationSpanV1 {
                correspondence_owner: plan.correspondence_owner,
                semantic_function: plan.semantic_function,
                rule: SemanticKirSyntheticOperationRuleV1::RetainedLocalStorage,
                kernel_ir_block: target.id,
                first_operation_ordinal: 0,
                operation_count: prologue.retained_local_storage,
            });
        }
        if prologue.enum_payload_storage != 0 {
            synthetic_operation_spans.push(SemanticKirSyntheticOperationSpanV1 {
                correspondence_owner: plan.correspondence_owner,
                semantic_function: plan.semantic_function,
                rule: SemanticKirSyntheticOperationRuleV1::EnumPayloadStorage,
                kernel_ir_block: target.id,
                first_operation_ordinal: prologue.retained_local_storage,
                operation_count: prologue.enum_payload_storage,
            });
        }
        for (statement, operation) in source.statements().iter().enumerate() {
            let statement = u32::try_from(statement).map_err(|_| {
                unsupported(
                    plan.semantic_function.index(),
                    Some(semantic_block.index()),
                    None,
                    "statement ordinal is too large",
                )
            })?;
            let first = target.operations.len();
            lowering.lower_statement(
                semantic_block,
                Some(statement),
                operation.kind(),
                &mut target.operations,
            )?;
            let (first_operation_ordinal, operation_count) = measured_operation_span(
                first,
                target.operations.len(),
                target.id,
                Some(statement),
            )?;
            statement_operation_spans.push(SemanticKirStatementOperationSpanV1 {
                correspondence_owner: plan.correspondence_owner,
                semantic_function: plan.semantic_function,
                semantic_block,
                statement_ordinal: statement,
                kernel_ir_block: target.id,
                first_operation_ordinal,
                operation_count,
            });
        }
        let terminator_first = target.operations.len();
        target.terminator = Some(lowering.lower_terminator(
            semantic_block,
            source.terminator().kind(),
            &mut target.operations,
        )?);
        if lowering.execution.is_some() {
            lowering.with_emission_budget_v1(|this, budget| {
                this.execution.as_mut().unwrap().finish_block(budget)
            })?;
        }
        let (first_operation_ordinal, operation_count) =
            measured_operation_span(terminator_first, target.operations.len(), target.id, None)?;
        terminator_operation_spans.push(SemanticKirTerminatorOperationSpanV1 {
            correspondence_owner: plan.correspondence_owner,
            semantic_function: plan.semantic_function,
            semantic_block,
            kernel_ir_block: target.id,
            first_operation_ordinal,
            operation_count,
        });
        if let Some(origins) = assert_origins.as_deref_mut() {
            origins.record(
                SemanticKirTerminatorOperationSpanV1 {
                    correspondence_owner: plan.correspondence_owner,
                    semantic_function: plan.semantic_function,
                    semantic_block,
                    kernel_ir_block: target.id,
                    first_operation_ordinal,
                    operation_count,
                },
                &plan.kernel_ir_function,
                source.terminator().kind(),
                target
                    .terminator
                    .as_ref()
                    .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?,
                lowering
                    .infallible_asserts
                    .contains(&semantic_block.index()),
            )?;
        }
        target_blocks.push(target);
        blocks.push(SemanticKirBlockCorrespondenceV1 {
            correspondence_owner: plan.correspondence_owner,
            semantic_function: plan.semantic_function,
            semantic_block,
            kernel_ir_block: lowering.kernel_block_id_v1(semantic_block)?,
            source_statement_count: u32::try_from(source.statements().len()).map_err(|_| {
                unsupported(
                    plan.semantic_function.index(),
                    Some(semantic_block.index()),
                    None,
                    "statement count is too large",
                )
            })?,
        });
    }
    require_semantic_ssa_definitions_consumed_v1(
        lowering.semantic_function.index(),
        &lowering.pending_semantic_ssa_definitions,
    )?;
    if lowering.execution.is_some() {
        lowering.with_emission_budget_v1(|this, budget| {
            this.execution.as_mut().unwrap().finish(budget)
        })?;
    }
    if let Some(failure_block) = lowering.assert_failure_block {
        let mut block = BasicBlock::new(failure_block);
        let first = block.operations.len();
        lowering.push_operation(&mut block.operations, || {
            AmdGpuDiagnosticOperation::Trap.operation(None)
        })?;
        let (first_operation_ordinal, operation_count) =
            measured_operation_span(first, block.operations.len(), failure_block, None)?;
        synthetic_operation_spans.push(SemanticKirSyntheticOperationSpanV1 {
            correspondence_owner: plan.correspondence_owner,
            semantic_function: plan.semantic_function,
            rule: SemanticKirSyntheticOperationRuleV1::RuntimeAssertFailureTrap,
            kernel_ir_block: failure_block,
            first_operation_ordinal,
            operation_count,
        });
        block.terminator = Some(Terminator::Unreachable);
        target_blocks.push(block);
    }
    let lifecycle_events = lowering.take_execution_lifecycle_events_v29()?;
    let scoped_memory_anchors = lowering
        .scoped_memory
        .take()
        .map(|recorder| {
            if recorder.frame.is_some() {
                return Err(scoped_memory_error_v29());
            }
            Ok(recorder.anchors)
        })
        .transpose()?;
    let emitted_operations = lowering.emitted_operations;
    let next_value = lowering.next_value;
    if let Some(origins) = assert_origins {
        if let Some(capture) = origins.scalar_capture.as_mut() {
            capture
                .record_function(plan, &lowering, &target_blocks, origins.budget)
                .map_err(|error| match error {
                    scalar_ssa_emission_v1::ProductionScalarSsaEmissionErrorV1::Resource(error) => {
                        ProductionSemanticKirErrorV1::from(error)
                    }
                    _ => ProductionSemanticKirErrorV1::CorrespondenceMismatch,
                })?;
        }
        if let Some(capture) = origins.tiled_capture.as_mut() {
            capture
                .record_function(
                    plan,
                    &lowering,
                    &target_blocks,
                    &terminator_operation_spans,
                    origins.budget,
                )
                .map_err(|error| match error {
                    tiled_region_v1::ProductionTiledRegionInspectionErrorV1::Resource(error) => {
                        ProductionSemanticKirErrorV1::from(error)
                    }
                    tiled_region_v1::ProductionTiledRegionInspectionErrorV1::Unavailable(
                        detail,
                    ) => unsupported(plan.semantic_function.index(), None, None, detail),
                    _ => ProductionSemanticKirErrorV1::CorrespondenceMismatch,
                })?;
        }
    }
    if let Some(state) = bf16 {
        // Reborrow the emitter's original ledger; do not create a second
        // mutable borrow while its source-SSA maps remain live.
        let emission_budget = lowering
            .emission_work
            .take()
            .ok_or(ArgumentResourceV1::Accounting)?;
        state
            .capture
            .record(state.source, plan, &lowering, emission_budget)?;
        lowering.emission_work = Some(emission_budget);
    }
    let direct_call_inputs = lowering
        .with_emission_budget_v1(|this, budget| this.take_direct_call_inputs_v26(budget))?;
    let execution_observation = lowering.with_emission_budget_v1(|this, budget| {
        this.take_execution_archive_v29(&target_blocks, &synthetic_operation_spans, budget)
    })?;
    drop(lowering.emission_work.take());
    let retained_local_slots = lowering.retained_local_slots;
    let initialized_at_entry = lowering.control_flow_ssa.retained_initialized_at_entry;
    let generated_terminator_values = lowering.generated_terminator_values;
    let mut call_returns = lowering.call_returns;
    let private_arrays = lowering.private_arrays.into_rows()?;
    let scoped_initialization = initialization_subject
        .map(|subject| {
            capture_scoped_initialization_v29(
                subject,
                function,
                semantic_ssa,
                &retained_local_slots,
                &initialized_at_entry,
                call_budget,
            )
        })
        .transpose()?;
    let scoped_slot_origins = source_call_instance
        .map(|_| capture_scoped_slot_origins_v29(&retained_local_slots, None, call_budget))
        .transpose()?;
    drop(retained_local_slots);
    // The shared emitter's final blocks are still untouched. Capture with the
    // same now-reborrowable ledger, before any helper expansion changes placement.
    if let Some(origins) = &mut instance_assert_origins {
        call_budget.charge_work(terminator_operation_spans.len())?;
        for (span, target) in terminator_operation_spans.iter().zip(&target_blocks) {
            let source = function
                .blocks()
                .get(span.semantic_block.index() as usize)
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            if target.id != span.kernel_ir_block {
                return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
            }
            origins.record(
                *span,
                &plan.kernel_ir_function,
                source.terminator().kind(),
                target
                    .terminator
                    .as_ref()
                    .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?,
                infallible_asserts.contains(&span.semantic_block.index()),
                call_budget,
            )?;
        }
    }
    call_returns.order_blocks(call_budget)?;
    let operation_capabilities = target_blocks
        .iter()
        .flat_map(|block| block.operations.iter())
        .flat_map(Operation::required_capabilities)
        .collect::<BTreeSet<_>>();
    let diagnostic_declarations = target_blocks
        .iter()
        .flat_map(|block| block.operations.iter())
        .filter_map(|operation| match &operation.kind {
            OperationKind::Call { callee, arguments } => {
                AmdGpuDiagnosticOperation::from_intrinsic_call(callee, arguments)
            }
            _ => None,
        })
        .map(|operation| {
            let declaration = operation.declaration();
            (declaration.id.clone(), declaration)
        })
        .collect::<BTreeMap<_, _>>();
    let float_declarations = target_blocks
        .iter()
        .flat_map(|block| block.operations.iter())
        .filter_map(|operation| match &operation.kind {
            OperationKind::Call { callee, arguments } => {
                FloatOperation::from_intrinsic_call(callee, arguments)
            }
            _ => None,
        })
        .map(|operation| {
            let declaration = operation.declaration();
            (declaration.id.clone(), declaration)
        })
        .collect::<BTreeMap<_, _>>();
    let (id, signature, parameters) = if retained_header {
        copy_emitted_function_header_v29(
            &plan.kernel_ir_function,
            &plan.parameter_types,
            &plan.result_types,
            &plan.parameter_values,
            call_budget,
        )?
    } else {
        (
            plan.kernel_ir_function.clone(),
            Signature::new(plan.parameter_types.clone(), plan.result_types.clone()),
            plan.parameter_values.clone(),
        )
    };
    let mut lowered = match plan.role {
        SemanticKirFunctionRoleV1::KernelEntry => {
            Function::kernel_entry(id, signature, parameters, target_blocks)
        }
        SemanticKirFunctionRoleV1::InternalHelper => {
            Function::internal_helper(id, signature, parameters, target_blocks)
        }
    };
    if has_runtime_assert {
        lowered
            .required_capabilities
            .extend(AmdGpuDiagnosticOperation::Trap.required_capabilities());
    }
    lowered
        .required_capabilities
        .extend(operation_capabilities.iter().cloned());
    Ok(LoweredFunctionResultV1 {
        next_value,
        execution_observation,
        direct_call_inputs,
        invocation_entry: None,
        source_call_instance,
        scoped_slot_origins,
        scoped_initialization,
        scoped_memory_anchors,
        instance_assert_origins,
        lifecycle_events,
        private_arrays,
        function: lowered,
        operation_capabilities,
        diagnostic_declarations,
        float_declarations,
        blocks,
        statement_operation_spans,
        terminator_operation_spans,
        generated_terminator_values,
        call_returns,
        synthetic_operation_spans,
        parameter_bindings,
        parameter_component_bindings: plan.parameter_component_bindings.clone(),
        ignored_parameter_bindings: plan.ignored_parameter_bindings.clone(),
        emitted_operations,
    })
}

#[allow(clippy::too_many_arguments)]
fn lower_one_source_function_with_calls_v29<'source, 'facts: 'source>(
    semantic: &'source fe2o3_mir_model::semantic_mir_v1::AdmittedInertSemanticMirV1,
    plan: &'source LoweredFunctionPlanV1,
    semantic_ssa: &'source ProductionSemanticSsaFunctionPlanV1,
    defined_function_ids: &'source BTreeMap<SemanticFunctionIdV1, FunctionId>,
    defined_function_signatures: impl Into<ExecutionSignatureSourceV29<'source>>,
    required_workgroup: Option<[u32; 3]>,
    infallible_asserts: impl Into<InfallibleAssertDecisionsV1<'facts>>,
    launch_rank: u8,
    authenticated_ranked_control: bool,
    max_operations: usize,
    assert_origins: Option<&mut AssertOriginEmissionV1<'_, '_>>,
    private_array_work: &mut PrivateArrayLazyBudgetV1,
    private_array_sources: Option<PrivateArraySourcesV1<'source>>,
    call_budget: &mut ArgumentBudgetV1<'_>,
    placement: SemanticEmissionPlacementV1,
    execution: Option<ExecutionAvailabilityV29<'source>>,
    execution_calls: Option<&mut dyn ExecutionDefinedCallConsumerV29>,
    lifecycle: Option<&mut dyn ExecutionLifecycleConsumerV29>,
) -> Result<LoweredFunctionResultV1, ProductionSemanticKirErrorV1> {
    #[cfg(not(test))]
    let detach_blocks = false;
    #[cfg(test)]
    let detach_blocks = DETACH_EMISSION_BLOCKS_V1.get();
    emit_function_frame_v1(
        semantic,
        FunctionEmissionPlanV1::Borrowed(plan),
        semantic_ssa,
        defined_function_ids,
        defined_function_signatures,
        required_workgroup,
        infallible_asserts,
        launch_rank,
        authenticated_ranked_control,
        max_operations,
        assert_origins,
        private_array_work,
        private_array_sources,
        call_budget,
        placement,
        execution,
        execution_calls,
        lifecycle,
        detach_blocks,
    )
}

fn retained_ranked_launch_root_v1(
    root: &ProductionRankedSemanticProjectionRootV1,
) -> Result<RetainedRankedLaunchRootV1, ProductionSemanticKirErrorV1> {
    let operation = root
        .lowering
        .kernel()
        .blocks()
        .first()
        .and_then(|block| block.operations().first());
    let Some(ProductionRankedOperationV1::ExecutionLayout {
        global_extents,
        workgroup_extents,
        full_physical_workgroups,
        ..
    }) = operation
    else {
        return Ok(RetainedRankedLaunchRootV1 {
            selected_root: root.selected_root,
            launch_rank: root.launch_rank,
            global_extents: [0; 3],
            workgroup_extents: [0; 3],
            full_physical_workgroups: false,
        });
    };
    Ok(RetainedRankedLaunchRootV1 {
        selected_root: root.selected_root,
        launch_rank: root.launch_rank,
        global_extents: *global_extents,
        workgroup_extents: *workgroup_extents,
        full_physical_workgroups: *full_physical_workgroups,
    })
}

// The normal standalone constructor has just created this SSA owner, so it
// has no prior occurrence receipt. Capture and materialization share the same
// existing fresh argument-work/storage profile; do not reset a second ledger.
fn capture_and_lower_fresh_wave64_source_v1(
    owner: &mut ProductionSemanticSsaOwnerV1,
    limits: ProductionSemanticKirLimitsV1,
) -> Result<(Module, SemanticKirCorrespondenceV1), ProductionSemanticKirErrorV1> {
    let mut work = fe2o3_kernel_ir::CanonicalKernelIrWorkBudgetV1::new(
        limits.max_argument_correspondence_work,
    );
    let mut budget = ArgumentBudgetV1::new(&mut work, limits.max_argument_correspondence_storage);
    let receipt = owner
        .try_capture_occurrences_with_budget_v1(&mut budget)
        .map_err(|error| {
            use fe2o3_pliron::ProductionSemanticSsaOccurrenceErrorV1 as Capture;
            match error {
                Capture::Replay(error) => ProductionSemanticKirErrorV1::SemanticSsa(error),
                Capture::Resource(error) => {
                    ProductionSemanticKirErrorV1::ArgumentCorrespondenceResource(error)
                }
                Capture::CaptureMismatch { function, block } => unsupported(
                    function.index(),
                    block.map(|block| block.get()),
                    None,
                    "original Wave64 source occurrence capture did not join its SSA owner",
                ),
                Capture::AlreadyCaptured => ArgumentResourceV1::Accounting.into(),
            }
        })?;
    // Capture transfers its real installed payload at the old floor. Reserve
    // that exact receipt before any subsequent controlled lowering allocation.
    let input = receipt.retained_storage();
    budget.reserve_storage(input)?;
    let result = lower_module_with_call_budget_v1(owner, limits, None, None, &mut budget);
    // This is the input charge only. Call outputs retain the existing receipt
    // and denial history; lower_module's Result cleanup restores its own floor.
    budget.release_storage(input)?;
    let result = result?;
    if budget.storage()
        != CallReturnBufferV1::bytes(
            result.1.call_returns.len(),
            result.1.call_result_components.len(),
        )?
    {
        return Err(ArgumentResourceV1::Accounting.into());
    }
    Ok(result)
}

fn lower_module(
    owner: &ProductionSemanticSsaOwnerV1,
    limits: ProductionSemanticKirLimitsV1,
    authenticated_launch_roots: Option<&[RetainedRankedLaunchRootV1]>,
) -> Result<(Module, SemanticKirCorrespondenceV1), ProductionSemanticKirErrorV1> {
    lower_module_with_assert_origins_v1(owner, limits, authenticated_launch_roots, None)
}

fn lower_module_with_assert_origins_v1(
    owner: &ProductionSemanticSsaOwnerV1,
    limits: ProductionSemanticKirLimitsV1,
    authenticated_launch_roots: Option<&[RetainedRankedLaunchRootV1]>,
    assert_origins: Option<&mut AssertOriginEmissionV1<'_, '_>>,
) -> Result<(Module, SemanticKirCorrespondenceV1), ProductionSemanticKirErrorV1> {
    lower_module_for_helper_admission_v1(
        owner,
        limits,
        authenticated_launch_roots,
        assert_origins,
        &mut HelperLoweringAdmissionV1::RawPure,
    )
}

// A pending continuation is not admission: the final merged graph still needs
// the independent physical and source/SSA helper checks before owner creation.
enum HelperLoweringAdmissionV1<'a> {
    PendingBf16Nominal(Bf16CallEmissionStateV1<'a>),
    RawPure,
    PendingUnitLocal { requires_source: bool },
    // Private same-source permit; final V17 structural admission is mandatory.
    PendingOrderedComposition(OrderedCompositionPermitV1),
}

struct PendingHelperSourceLoweringV1 {
    module: Module,
    correspondence: SemanticKirCorrespondenceV1,
    requires_source: bool,
}

fn lower_pending_module_with_assert_origins_v1(
    owner: &ProductionSemanticSsaOwnerV1,
    limits: ProductionSemanticKirLimitsV1,
    authenticated_launch_roots: &[RetainedRankedLaunchRootV1],
    assert_origins: &mut AssertOriginEmissionV1<'_, '_>,
) -> Result<PendingHelperSourceLoweringV1, ProductionSemanticKirErrorV1> {
    let mut admission = HelperLoweringAdmissionV1::PendingUnitLocal {
        requires_source: false,
    };
    let (module, correspondence) = lower_module_for_helper_admission_v1(
        owner,
        limits,
        Some(authenticated_launch_roots),
        Some(assert_origins),
        &mut admission,
    )?;
    let HelperLoweringAdmissionV1::PendingUnitLocal { requires_source } = admission else {
        return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
    };
    Ok(PendingHelperSourceLoweringV1 {
        module,
        correspondence,
        requires_source,
    })
}

fn lower_module_for_helper_admission_v1(
    owner: &ProductionSemanticSsaOwnerV1,
    limits: ProductionSemanticKirLimitsV1,
    authenticated_launch_roots: Option<&[RetainedRankedLaunchRootV1]>,
    assert_origins: Option<&mut AssertOriginEmissionV1<'_, '_>>,
    admission: &mut HelperLoweringAdmissionV1,
) -> Result<(Module, SemanticKirCorrespondenceV1), ProductionSemanticKirErrorV1> {
    let mut work = fe2o3_kernel_ir::CanonicalKernelIrWorkBudgetV1::new(
        limits.max_argument_correspondence_work,
    );
    let mut budget = ArgumentBudgetV1::new(&mut work, limits.max_argument_correspondence_storage);
    let lower = |budget: &mut ArgumentBudgetV1<'_>| match admission {
        HelperLoweringAdmissionV1::RawPure => lower_module_with_call_budget_v1(
            owner,
            limits,
            authenticated_launch_roots,
            assert_origins,
            budget,
        ),
        HelperLoweringAdmissionV1::PendingOrderedComposition(_)
        | HelperLoweringAdmissionV1::PendingBf16Nominal(_) => {
            return Err(ordered_composition_refusal_v1(
                "composition requires the caller-owned cumulative ledger",
            ));
        }
        HelperLoweringAdmissionV1::PendingUnitLocal { .. } => {
            lower_module_with_call_budget_for_helper_admission_v1(
                owner,
                limits,
                authenticated_launch_roots,
                assert_origins,
                budget,
                admission,
            )
        }
    };
    let result = if ordinary_source_has_raw_wave64_shuffle_v1(owner.source_semantic()) {
        with_wave64_retained_source_input_v1(owner, &mut budget, lower)?
    } else {
        lower(&mut budget)?
    };
    if budget.storage()
        != CallReturnBufferV1::bytes(
            result.1.call_returns.len(),
            result.1.call_result_components.len(),
        )?
    {
        return Err(ArgumentResourceV1::Accounting.into());
    }
    Ok(result)
}

fn lower_module_with_call_budget_v1(
    owner: &ProductionSemanticSsaOwnerV1,
    limits: ProductionSemanticKirLimitsV1,
    authenticated_launch_roots: Option<&[RetainedRankedLaunchRootV1]>,
    assert_origins: Option<&mut AssertOriginEmissionV1<'_, '_>>,
    call_budget: &mut ArgumentBudgetV1<'_>,
) -> Result<(Module, SemanticKirCorrespondenceV1), ProductionSemanticKirErrorV1> {
    lower_module_with_call_budget_for_helper_admission_v1(
        owner,
        limits,
        authenticated_launch_roots,
        assert_origins,
        call_budget,
        &mut HelperLoweringAdmissionV1::RawPure,
    )
}

fn lower_module_with_call_budget_for_helper_admission_v1(
    owner: &ProductionSemanticSsaOwnerV1,
    limits: ProductionSemanticKirLimitsV1,
    authenticated_launch_roots: Option<&[RetainedRankedLaunchRootV1]>,
    assert_origins: Option<&mut AssertOriginEmissionV1<'_, '_>>,
    call_budget: &mut ArgumentBudgetV1<'_>,
    admission: &mut HelperLoweringAdmissionV1,
) -> Result<(Module, SemanticKirCorrespondenceV1), ProductionSemanticKirErrorV1> {
    let floor = call_budget.storage();
    let result = lower_module_with_call_budget_inner_v1(
        owner,
        limits,
        authenticated_launch_roots,
        assert_origins,
        call_budget,
        admission,
    )
    .and_then(|(module, rows)| {
        validate_call_component_pool_v1(
            &rows.call_returns,
            &rows.call_result_components,
            call_budget,
        )?;
        Ok((module, rows))
    });
    let retained = match &result {
        Ok((_, rows)) => {
            CallReturnBufferV1::bytes(rows.call_returns.len(), rows.call_result_components.len())?
        }
        Err(_) => 0,
    };
    let live = argument_sum_v1(&[floor, retained])?;
    call_budget.release_storage(
        call_budget
            .storage()
            .checked_sub(live)
            .ok_or(ArgumentResourceV1::Accounting)?,
    )?;
    result
}

fn lower_module_with_call_budget_inner_v1(
    owner: &ProductionSemanticSsaOwnerV1,
    limits: ProductionSemanticKirLimitsV1,
    authenticated_launch_roots: Option<&[RetainedRankedLaunchRootV1]>,
    mut assert_origins: Option<&mut AssertOriginEmissionV1<'_, '_>>,
    call_budget: &mut ArgumentBudgetV1<'_>,
    admission: &mut HelperLoweringAdmissionV1,
) -> Result<(Module, SemanticKirCorrespondenceV1), ProductionSemanticKirErrorV1> {
    let semantic = owner.source_semantic();
    // Admission binds every execution role (including nested/ignored carriers) to V29.
    // Never flatten those roles through the ordinary aggregate/ZST lowering path.
    if semantic.wire_version() == fe2o3_mir_model::semantic_mir_v1::SemanticMirWireVersionV1::V29 {
        return Err(unsupported(
            0,
            None,
            None,
            "execution capabilities require checked canonical KIR materialization",
        ));
    }
    require_execution_free_types_v29(semantic.types(), call_budget)?;
    let Some(authenticated_launch_roots) = authenticated_launch_roots else {
        let selection = semantic.select_kernel_body_v1().ok_or_else(|| {
            unsupported(
                0,
                None,
                None,
                "one direct kernel body or an exact transparent KernelResult wrapper is required",
            )
        })?;
        let mut closure_budget = ReachableClosureBudgetV1::new(limits.max_blocks);
        let mut private_array_work = PrivateArrayLazyBudgetV1::new(1, limits.max_operations);
        let (module, mut correspondence, _) = lower_single_root_module(
            owner,
            limits,
            selection.root(),
            None,
            &mut closure_budget,
            true,
            assert_origins,
            &mut private_array_work,
            None,
            call_budget,
            admission,
        )?;
        if correspondence.private_arrays.active {
            private_array_order_correspondence_v1(
                &mut correspondence.private_arrays,
                &mut private_array_work,
            )?;
        }
        return Ok((module, correspondence));
    };
    if authenticated_launch_roots.is_empty()
        || authenticated_launch_roots.len() != semantic.roots().len()
    {
        return Err(unsupported(
            0,
            None,
            None,
            "authenticated launch roster is not a complete semantic root bijection",
        ));
    }
    if authenticated_launch_roots
        .iter()
        .map(|root| &root.selected_root)
        .ne(semantic.roots().iter())
    {
        return Err(unsupported(
            0,
            None,
            None,
            "authenticated launch roster duplicated or substituted a semantic root",
        ));
    }

    let mut private_array_work =
        PrivateArrayLazyBudgetV1::new(authenticated_launch_roots.len(), limits.max_operations);
    let mut private_arrays: Option<PrivateArrayMergeV1> = None;
    let mut merged = Module::new(format!(
        "fe2o3::semantic::{}",
        hex_identity(semantic.semantic_sha256().as_bytes())
    ));
    let mut entry_functions = Vec::with_capacity(authenticated_launch_roots.len());
    let mut auxiliary_functions = Vec::new();
    let mut function_index = BTreeMap::<FunctionId, (Function, (bool, usize))>::new();
    let mut entry_correspondence = Vec::with_capacity(authenticated_launch_roots.len());
    let mut auxiliary_correspondence = Vec::new();
    let mut correspondence_functions = BTreeSet::new();
    let mut blocks = Vec::new();
    let mut statement_spans = Vec::new();
    let mut terminator_spans = Vec::new();
    let mut generated_terminator_values = Vec::new();
    let mut call_returns = CallReturnBufferV1::empty();
    let mut synthetic_spans = Vec::new();
    let mut parameter_bindings = Vec::new();
    let mut parameter_component_bindings = Vec::new();
    let mut ignored_parameter_bindings = Vec::new();
    let mut closure_budget = ReachableClosureBudgetV1::new(limits.max_blocks);

    for (root_ordinal, launch) in authenticated_launch_roots.iter().copied().enumerate() {
        let (root_module, mut root_correspondence, root_payload) = lower_single_root_module(
            owner,
            limits,
            launch.selected_root,
            Some(launch),
            &mut closure_budget,
            false,
            assert_origins.as_deref_mut(),
            &mut private_array_work,
            private_arrays.as_ref(),
            call_budget,
            admission,
        )?;
        let [kernel] = root_module.kernels.as_slice() else {
            return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
        };
        if merged
            .kernels
            .iter()
            .any(|retained| retained.id == kernel.id || retained.entry == kernel.entry)
        {
            return Err(unsupported(
                launch.selected_root.index(),
                None,
                None,
                "canonical multi-root lowering produced a duplicate kernel identity",
            ));
        }
        merged.kernels.push(kernel.clone());
        merged
            .required_capabilities
            .extend(root_module.required_capabilities.iter().cloned());
        let mut private_instance = 0;
        for (function_ordinal, function) in root_module.functions.into_iter().enumerate() {
            let physical = if let Some((retained, physical)) = function_index.get(&function.id) {
                if retained != &function {
                    return Err(unsupported(
                        launch.selected_root.index(),
                        None,
                        None,
                        "canonical multi-root lowering cross-wired a shared helper identity",
                    ));
                }
                *physical
            } else {
                let physical = if function.id == kernel.entry {
                    (true, root_ordinal)
                } else {
                    (false, auxiliary_functions.len())
                };
                function_index.insert(function.id.clone(), (function.clone(), physical));
                if function.id == kernel.entry {
                    entry_functions.push(function);
                } else {
                    auxiliary_functions.push(function);
                }
                physical
            };
            let private_candidate = if root_correspondence.private_arrays.active {
                // Candidate lookup and its possible ordinal comparison, including misses.
                private_array_work.charge_private_array_work(2)?;
                root_correspondence
                    .private_arrays
                    .instances
                    .get_mut(private_instance)
            } else {
                None
            };
            if let Some(instance) = private_candidate
                && instance.module_function_ordinal == function_ordinal
            {
                private_array_work.charge_private_array_work(3)?;
                instance.module_function_ordinal = if physical.0 {
                    physical.1
                } else {
                    private_array_work.charge_private_array_work(1)?;
                    authenticated_launch_roots
                        .len()
                        .checked_add(physical.1)
                        .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?
                };
                private_instance = private_instance
                    .checked_add(1)
                    .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            }
        }
        if root_correspondence.private_arrays.active {
            private_array_work.charge_private_array_work(1)?;
            if private_instance != root_correspondence.private_arrays.instances.len() {
                return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
            }
        }
        let mut private_instance = 0;
        let mut root_function_keys = BTreeSet::new();
        for (function_ordinal, function) in root_correspondence
            .lowered_functions
            .into_vec()
            .into_iter()
            .enumerate()
        {
            if function.correspondence_owner != launch.selected_root
                || !root_function_keys
                    .insert((function.correspondence_owner, function.semantic_function))
            {
                return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
            }
            let key = (
                function.correspondence_owner,
                function.semantic_function,
                function.kernel_ir_function.clone(),
            );
            if !correspondence_functions.insert(key) {
                return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
            }
            let private_candidate = if root_correspondence.private_arrays.active {
                // Candidate lookup and its possible ordinal comparison, including misses.
                private_array_work.charge_private_array_work(2)?;
                root_correspondence
                    .private_arrays
                    .instances
                    .get_mut(private_instance)
            } else {
                None
            };
            if let Some(instance) = private_candidate
                && instance.lowered_function_ordinal == function_ordinal
            {
                private_array_work.charge_private_array_work(6)?;
                if instance.owner != function.correspondence_owner
                    || instance.function != function.semantic_function
                {
                    return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
                }
                instance.lowered_function_ordinal =
                    if function.role == SemanticKirFunctionRoleV1::KernelEntry {
                        root_ordinal
                    } else {
                        authenticated_launch_roots
                            .len()
                            .checked_add(auxiliary_correspondence.len())
                            .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?
                    };
                private_instance = private_instance
                    .checked_add(1)
                    .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
            }
            if function.role == SemanticKirFunctionRoleV1::KernelEntry {
                entry_correspondence.push(function);
            } else {
                auxiliary_correspondence.push(function);
            }
        }
        if root_correspondence.private_arrays.active {
            private_array_work.charge_private_array_work(1)?;
            if private_instance != root_correspondence.private_arrays.instances.len() {
                return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
            }
        }
        if root_correspondence.private_arrays.active {
            if private_arrays.is_none() {
                private_arrays = Some(PrivateArrayMergeV1::new(private_array_work.active_limit()?));
            }
            private_arrays
                .as_mut()
                .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?
                .append(
                    root_correspondence.private_arrays,
                    root_payload,
                    &mut private_array_work,
                )?;
        }
        let exact_root_record = |owner, function| {
            owner == launch.selected_root && root_function_keys.contains(&(owner, function))
        };
        if root_correspondence
            .blocks
            .iter()
            .any(|record| !exact_root_record(record.correspondence_owner, record.semantic_function))
            || root_correspondence
                .statement_operation_spans
                .iter()
                .any(|record| {
                    !exact_root_record(record.correspondence_owner, record.semantic_function)
                })
            || root_correspondence
                .terminator_operation_spans
                .iter()
                .any(|record| {
                    !exact_root_record(record.correspondence_owner, record.semantic_function)
                })
            || root_correspondence
                .generated_terminator_values
                .iter()
                .any(|record| {
                    !exact_root_record(record.correspondence_owner, record.semantic_function)
                })
            || root_correspondence.call_returns.iter().any(|record| {
                !exact_root_record(record.correspondence_owner, record.semantic_function)
            })
            || root_correspondence
                .synthetic_operation_spans
                .iter()
                .any(|record| {
                    !exact_root_record(record.correspondence_owner, record.semantic_function)
                })
            || root_correspondence.parameter_bindings.iter().any(|record| {
                !exact_root_record(record.correspondence_owner, record.semantic_function)
            })
            || root_correspondence
                .parameter_component_bindings
                .iter()
                .any(|record| {
                    !exact_root_record(record.correspondence_owner, record.semantic_function)
                })
            || root_correspondence
                .ignored_parameter_bindings
                .iter()
                .any(|record| {
                    !exact_root_record(record.correspondence_owner, record.semantic_function)
                })
        {
            return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
        }
        append_correspondence_records_v1(
            &mut blocks,
            root_correspondence.blocks.into_vec(),
            ProductionSemanticKirResourceV1::Blocks,
            limits.max_blocks,
        )?;
        append_correspondence_records_v1(
            &mut statement_spans,
            root_correspondence.statement_operation_spans.into_vec(),
            ProductionSemanticKirResourceV1::Statements,
            limits.max_statements,
        )?;
        append_correspondence_records_v1(
            &mut terminator_spans,
            root_correspondence.terminator_operation_spans.into_vec(),
            ProductionSemanticKirResourceV1::Blocks,
            limits.max_blocks,
        )?;
        append_correspondence_records_v1(
            &mut generated_terminator_values,
            root_correspondence.generated_terminator_values.into_vec(),
            ProductionSemanticKirResourceV1::DebugBindings,
            limits.max_operations,
        )?;
        call_returns.append(
            CallReturnBufferV1::from_box(
                root_correspondence.call_returns,
                root_correspondence.call_result_components,
            ),
            limits.max_blocks,
            call_budget,
        )?;
        append_correspondence_records_v1(
            &mut synthetic_spans,
            root_correspondence.synthetic_operation_spans.into_vec(),
            ProductionSemanticKirResourceV1::Blocks,
            limits.max_blocks,
        )?;
        append_correspondence_records_v1(
            &mut parameter_bindings,
            root_correspondence.parameter_bindings.into_vec(),
            ProductionSemanticKirResourceV1::Operations,
            limits.max_operations,
        )?;
        append_correspondence_records_v1(
            &mut parameter_component_bindings,
            root_correspondence.parameter_component_bindings.into_vec(),
            ProductionSemanticKirResourceV1::DebugBindings,
            limits.max_operations,
        )?;
        append_correspondence_records_v1(
            &mut ignored_parameter_bindings,
            root_correspondence.ignored_parameter_bindings.into_vec(),
            ProductionSemanticKirResourceV1::DebugBindings,
            limits.max_operations,
        )?;
    }
    merged.functions.extend(entry_functions);
    merged.functions.extend(auxiliary_functions);
    let defined_functions = merged
        .functions
        .iter()
        .filter(|function| function.body.is_some())
        .count();
    enforce_limit(
        ProductionSemanticKirResourceV1::Functions,
        defined_functions,
        limits.max_functions,
    )?;
    let emitted_blocks = merged
        .functions
        .iter()
        .filter_map(|function| function.body.as_ref())
        .try_fold(0_usize, |count, body| count.checked_add(body.blocks.len()))
        .ok_or(ProductionSemanticKirErrorV1::ResourceLimit {
            resource: ProductionSemanticKirResourceV1::Blocks,
            actual: usize::MAX,
            limit: limits.max_blocks,
        })?;
    enforce_limit(
        ProductionSemanticKirResourceV1::Blocks,
        emitted_blocks,
        limits.max_blocks,
    )?;
    enforce_limit(
        ProductionSemanticKirResourceV1::Statements,
        statement_spans.len(),
        limits.max_statements,
    )?;
    let emitted_operations = merged
        .functions
        .iter()
        .filter_map(|function| function.body.as_ref())
        .flat_map(|body| &body.blocks)
        .try_fold(0_usize, |count, block| {
            count.checked_add(block.operations.len())
        })
        .ok_or(ProductionSemanticKirErrorV1::ResourceLimit {
            resource: ProductionSemanticKirResourceV1::Operations,
            actual: usize::MAX,
            limit: limits.max_operations,
        })?;
    enforce_limit(
        ProductionSemanticKirResourceV1::Operations,
        emitted_operations,
        limits.max_operations,
    )?;
    let mut lowered_functions = entry_correspondence;
    lowered_functions.extend(auxiliary_correspondence);
    let mut function_ordinals = BTreeMap::new();
    for (ordinal, function) in lowered_functions.iter().enumerate() {
        if function_ordinals
            .insert(
                (function.correspondence_owner, function.semantic_function),
                ordinal,
            )
            .is_some()
        {
            return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
        }
    }
    blocks = order_correspondence_records_v1(blocks, &function_ordinals, |record| {
        (record.correspondence_owner, record.semantic_function)
    })?;
    statement_spans =
        order_correspondence_records_v1(statement_spans, &function_ordinals, |record| {
            (record.correspondence_owner, record.semantic_function)
        })?;
    terminator_spans =
        order_correspondence_records_v1(terminator_spans, &function_ordinals, |record| {
            (record.correspondence_owner, record.semantic_function)
        })?;
    generated_terminator_values = order_correspondence_records_v1(
        generated_terminator_values,
        &function_ordinals,
        |record| (record.correspondence_owner, record.semantic_function),
    )?;
    call_returns.order(&function_ordinals, call_budget)?;
    synthetic_spans =
        order_correspondence_records_v1(synthetic_spans, &function_ordinals, |record| {
            (record.correspondence_owner, record.semantic_function)
        })?;
    parameter_bindings =
        order_correspondence_records_v1(parameter_bindings, &function_ordinals, |record| {
            (record.correspondence_owner, record.semantic_function)
        })?;
    parameter_component_bindings = order_correspondence_records_v1(
        parameter_component_bindings,
        &function_ordinals,
        |record| (record.correspondence_owner, record.semantic_function),
    )?;
    ignored_parameter_bindings = order_correspondence_records_v1(
        ignored_parameter_bindings,
        &function_ordinals,
        |record| (record.correspondence_owner, record.semantic_function),
    )?;
    let mut private_arrays = match private_arrays {
        Some(rows) => rows.into_correspondence(&mut private_array_work)?.0,
        None => PrivateArrayCorrespondenceV1::default(),
    };
    if private_arrays.active {
        private_array_order_correspondence_v1(&mut private_arrays, &mut private_array_work)?;
    }
    let (call_returns, call_result_components) = call_returns.into_box(call_budget)?;
    let correspondence = SemanticKirCorrespondenceV1 {
        private_arrays,
        semantic_sha256: *semantic.semantic_sha256().as_bytes(),
        function_count: semantic.functions().len(),
        lowered_functions: lowered_functions.into_boxed_slice(),
        blocks: blocks.into_boxed_slice(),
        statement_operation_spans: statement_spans.into_boxed_slice(),
        terminator_operation_spans: terminator_spans.into_boxed_slice(),
        generated_terminator_values: generated_terminator_values.into_boxed_slice(),
        call_returns,
        call_result_components,
        synthetic_operation_spans: synthetic_spans.into_boxed_slice(),
        parameter_bindings: parameter_bindings.into_boxed_slice(),
        parameter_component_bindings: parameter_component_bindings.into_boxed_slice(),
        ignored_parameter_bindings: ignored_parameter_bindings.into_boxed_slice(),
    };
    correspondence.validate_layout_against(owner, &merged, semantic.roots(), limits)?;
    Ok((merged, correspondence))
}

fn append_correspondence_records_v1<T>(
    destination: &mut Vec<T>,
    mut source: Vec<T>,
    resource: ProductionSemanticKirResourceV1,
    limit: usize,
) -> Result<(), ProductionSemanticKirErrorV1> {
    let total = destination.len().saturating_add(source.len());
    enforce_limit(resource, total, limit)?;
    destination.append(&mut source);
    Ok(())
}

type ByValueKernelParameterComponentV1 = (
    Vec<SemanticKirParameterProjectionV1>,
    SemanticTypeIdV1,
    Type,
    u64,
    ParameterAbiLeafV1,
);

fn order_correspondence_records_v1<T, F>(
    records: Vec<T>,
    function_ordinals: &BTreeMap<(SemanticFunctionIdV1, SemanticFunctionIdV1), usize>,
    mut function_key: F,
) -> Result<Vec<T>, ProductionSemanticKirErrorV1>
where
    F: FnMut(&T) -> (SemanticFunctionIdV1, SemanticFunctionIdV1),
{
    let record_count = records.len();
    let mut buckets = (0..function_ordinals.len())
        .map(|_| Vec::new())
        .collect::<Vec<_>>();
    for record in records {
        let ordinal = function_ordinals
            .get(&function_key(&record))
            .copied()
            .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
        let bucket = buckets
            .get_mut(ordinal)
            .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
        bucket.push(record);
    }
    let mut ordered = Vec::with_capacity(record_count);
    for mut bucket in buckets {
        ordered.append(&mut bucket);
    }
    Ok(ordered)
}

fn pending_unit_local_candidates_v1(
    module: &Module,
    plans: &[LoweredFunctionPlanV1],
    effects: &fe2o3_kernel_ir::InterproceduralEffectAnalysisV1,
    budget: &mut ArgumentBudgetV1<'_>,
) -> Result<bool, ProductionSemanticKirErrorV1> {
    // Screen the whole roster before deferring its first legacy failure. This
    // preserves that diagnostic for a nested call or another unsupported helper.
    for plan in plans.iter().skip(1) {
        let lookup_work = argument_sum_v1(&[plan.kernel_ir_function.as_str().len(), 1])?;
        budget.charge_work(argument_product_v1(effects.functions().len(), lookup_work)?)?;
        let Some(decision) = effects.function(&plan.kernel_ir_function) else {
            return Ok(false);
        };
        if decision.is_complete_and_pure() {
            continue;
        }
        if !decision.is_complete() {
            return Ok(false);
        }
        let mut selected = None;
        for function in &module.functions {
            budget.charge_work(lookup_work)?;
            if function.id == plan.kernel_ir_function {
                selected = Some(function);
                break;
            }
        }
        let Some(function) = selected else {
            return Ok(false);
        };
        budget.charge_work(4)?;
        if !function.signature.parameters.is_empty() || !function.signature.results.is_empty() {
            return Ok(false);
        }
        let Some(body) = &function.body else {
            return Ok(false);
        };
        for block in &body.blocks {
            budget.charge_work(3)?;
            match &block.terminator {
                Some(Terminator::Branch { .. } | Terminator::ConditionalBranch { .. }) => {}
                Some(Terminator::Return { values }) if values.is_empty() => {}
                Some(Terminator::Unreachable) if block.operations.len() == 1 => {}
                _ => return Ok(false),
            }
            for operation in &block.operations {
                budget.charge_work(2)?;
                match &operation.kind {
                    OperationKind::Constant(_)
                    | OperationKind::Cast { .. }
                    | OperationKind::Compare { .. }
                    | OperationKind::Alloca { .. }
                    | OperationKind::GetElementPointer { .. }
                    | OperationKind::Load { .. }
                    | OperationKind::Store { .. } => {}
                    OperationKind::Call { callee, arguments }
                        if arguments.is_empty()
                            && operation.results.is_empty()
                            && block.operations.len() == 1
                            && matches!(block.terminator, Some(Terminator::Unreachable)) =>
                    {
                        // The V1 decoder scans eight fixed descriptors. Zero
                        // arguments exclude every allocating Print descriptor.
                        budget.charge_work(argument_sum_v1(&[
                            argument_product_v1(argument_sum_v1(&[callee.as_str().len(), 2])?, 8)?,
                            4,
                        ])?)?;
                        if !matches!(
                            AmdGpuDiagnosticOperation::from_intrinsic_call(callee, arguments),
                            Some(AmdGpuDiagnosticOperation::Trap)
                        ) {
                            return Ok(false);
                        }
                    }
                    _ => return Ok(false),
                }
            }
        }
    }
    Ok(true)
}

#[allow(
    clippy::too_many_arguments,
    reason = "Keep shared root budgets and outer retained storage independently borrowed"
)]
fn lower_single_root_module(
    owner: &ProductionSemanticSsaOwnerV1,
    limits: ProductionSemanticKirLimitsV1,
    selected_root: SemanticFunctionIdV1,
    authenticated_launch: Option<RetainedRankedLaunchRootV1>,
    closure_budget: &mut ReachableClosureBudgetV1,
    validate_correspondence: bool,
    mut assert_origins: Option<&mut AssertOriginEmissionV1<'_, '_>>,
    private_array_work: &mut PrivateArrayLazyBudgetV1,
    outer_private_arrays: Option<&PrivateArrayMergeV1>,
    call_budget: &mut ArgumentBudgetV1<'_>,
    admission: &mut HelperLoweringAdmissionV1,
) -> Result<
    (Module, SemanticKirCorrespondenceV1, PrivateArrayPayloadV1),
    ProductionSemanticKirErrorV1,
> {
    let semantic = owner.source_semantic();
    let launch_rank = authenticated_launch.map_or(1, |launch| launch.launch_rank);
    if !(1..=3).contains(&launch_rank) {
        return Err(unsupported(
            0,
            None,
            None,
            "authenticated launch rank is outside the supported range",
        ));
    }
    enforce_limit(
        ProductionSemanticKirResourceV1::Functions,
        semantic.functions().len(),
        limits.max_functions,
    )?;
    let selection = semantic
        .select_kernel_body_for_root_v1(selected_root)
        .ok_or_else(|| {
        unsupported(
            0,
            None,
            None,
            "the selected direct kernel body or exact transparent KernelResult wrapper is unavailable",
        )
    })?;
    if !semantic.allocations().is_empty()
        || !semantic.statics().is_empty()
        || !semantic.vtables().is_empty()
    {
        return Err(unsupported(
            0,
            None,
            None,
            "allocations, statics, and vtables are not lowered yet",
        ));
    }
    let root = semantic
        .functions()
        .get(selection.root().index() as usize)
        .ok_or_else(|| unsupported(0, None, None, "the selected kernel root is missing"))?;
    let entry = root
        .kernel_entry()
        .ok_or_else(|| unsupported(0, None, None, "kernel export metadata is missing"))?;
    let symbol = std::str::from_utf8(entry.export_symbol().as_bytes())
        .map_err(|_| unsupported(0, None, None, "kernel export symbol is not UTF-8"))?;
    let closure = reachable_defined_closure_v1(
        semantic,
        selection.body(),
        limits.max_functions,
        closure_budget,
    )?;
    // Bound logical mappings before allocating plans, including empty source
    // tuples and ignored ABI rows. Calls and reused roots consume work too.
    for function_id in &closure {
        let function = &semantic.functions()[function_id.index() as usize];
        closure_budget
            .charge_arguments(logical_argument_rows_v1(function), limits.max_operations)?;
        for block in function.blocks() {
            if let SemanticTerminatorKindV1::Call(call) = block.terminator().kind()
                && let Some(SemanticCallableDeclV1::Defined { function: callee }) =
                    semantic.callables().get(call.callee().index() as usize)
            {
                closure_budget.charge_arguments(
                    logical_argument_rows_v1(&semantic.functions()[callee.index() as usize]),
                    limits.max_operations,
                )?;
            }
        }
    }
    let body = semantic
        .functions()
        .get(selection.body().index() as usize)
        .ok_or_else(|| unsupported(0, None, None, "the selected kernel body is missing"))?;
    let mut defined_function_ids = BTreeMap::new();
    defined_function_ids.insert(selection.body(), FunctionId::new(symbol));
    for function_id in closure.iter().copied().skip(1) {
        let function = semantic
            .functions()
            .get(function_id.index() as usize)
            .ok_or_else(|| unsupported(function_id.index(), None, None, "helper is missing"))?;
        defined_function_ids.insert(function_id, helper_function_id_v1(function_id, function));
    }
    if defined_function_ids.values().collect::<BTreeSet<_>>().len() != defined_function_ids.len() {
        return Err(unsupported(
            selection.body().index(),
            None,
            None,
            "deterministic helper symbol construction collided",
        ));
    }

    let mut plans = Vec::with_capacity(closure.len());
    plans.push(kernel_entry_plan_v1(
        semantic,
        selected_root,
        selection.body(),
        FunctionId::new(symbol),
        limits.max_operations,
        closure_budget,
    )?);
    for function_id in closure.iter().copied().skip(1) {
        let plan = match admission {
            HelperLoweringAdmissionV1::PendingBf16Nominal(state) => bf16_parameter_plan_v1(
                state.source,
                semantic,
                selected_root,
                function_id,
                defined_function_ids[&function_id].clone(),
                closure_budget,
                call_budget,
            )?,
            _ => match checked_wave64_helper_parameter_plan_v1(
                owner,
                selected_root,
                function_id,
                defined_function_ids[&function_id].clone(),
                limits.max_operations,
                closure_budget,
                call_budget,
            )? {
                Some(plan) => plan,
                None => direct_scalar_helper_plan_v1(
                    semantic,
                    selected_root,
                    function_id,
                    defined_function_ids[&function_id].clone(),
                    limits.max_operations,
                    closure_budget,
                )?,
            },
        };
        plans.push(plan);
    }
    // Declaration expansion was charged before growing each parameter roster.
    // Charge its repetition at call sites before cloning signatures or bodies.
    let expanded_parameter_rows = plans
        .iter()
        .map(|plan| {
            (
                plan.semantic_function,
                plan.parameter_types
                    .len()
                    .saturating_sub(logical_argument_rows_v1(
                        &semantic.functions()[plan.semantic_function.index() as usize],
                    )),
            )
        })
        .collect::<BTreeMap<_, _>>();
    for plan in &plans {
        let function = &semantic.functions()[plan.semantic_function.index() as usize];
        for block in function.blocks() {
            if let SemanticTerminatorKindV1::Call(call) = block.terminator().kind()
                && let Some(SemanticCallableDeclV1::Defined { function: callee }) =
                    semantic.callables().get(call.callee().index() as usize)
            {
                let rows = expanded_parameter_rows
                    .get(callee)
                    .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
                closure_budget.charge_arguments(*rows, limits.max_operations)?;
            }
        }
    }
    let defined_function_signatures = plans
        .iter()
        .map(|plan| {
            (
                plan.semantic_function,
                LoweredFunctionSignatureV1 {
                    wave64_nominal: plan.parameter_local_bindings.iter().any(|binding| {
                        matches!(
                            binding,
                            PlannedParameterLocalBindingV1::Wave64Nominal { .. }
                        )
                    }),
                    bf16_nominal: plan.parameter_local_bindings.iter().any(|binding| {
                        matches!(binding, PlannedParameterLocalBindingV1::Bf16Nominal { .. })
                    }),
                    parameter_semantic_types: semantic.functions()
                        [plan.semantic_function.index() as usize]
                        .abi()
                        .source_input_types()
                        .to_vec(),
                    call_arguments: plan.call_arguments.clone(),
                    parameter_types: plan.parameter_types.clone(),
                    result_types: plan.result_types.clone(),
                    result_semantic_type: semantic.functions()
                        [plan.semantic_function.index() as usize]
                        .abi()
                        .source_output_type(),
                },
            )
        })
        .collect::<BTreeMap<_, _>>();

    let required_workgroup = entry
        .source_contract()
        .launch()
        .and_then(|launch| launch.required())
        .map(|required| required.as_array());
    let entry_infallible_asserts = match (authenticated_launch, required_workgroup) {
        (Some(_), Some(required_workgroup)) => InfallibleBoundsAssertAnalysisV1::analyze(
            semantic.types(),
            semantic.callables(),
            body,
            required_workgroup,
        )?,
        (None, _) | (_, None) => BTreeSet::new(),
    };
    with_masked_assertion_plans_v1(
        owner,
        &plans,
        entry_infallible_asserts,
        call_budget,
        |assertions, call_budget| {
            let mut total_blocks = 0_usize;
            let mut total_statements = 0_usize;
            for (index, plan) in plans.iter().enumerate() {
                let function = &semantic.functions()[plan.semantic_function.index() as usize];
                let infallible = masked_decisions_for_plan_v1(semantic, plan, &assertions[index])?;
                total_blocks = total_blocks
                    .checked_add(function.blocks().len())
                    .and_then(|count| {
                        count.checked_add(usize::from(semantic_requires_runtime_assert_failure(
                            function,
                            semantic.callables(),
                            &infallible,
                        )))
                    })
                    .ok_or(ProductionSemanticKirErrorV1::ResourceLimit {
                        resource: ProductionSemanticKirResourceV1::Blocks,
                        actual: usize::MAX,
                        limit: limits.max_blocks,
                    })?;
                total_statements = function
                    .blocks()
                    .iter()
                    .try_fold(total_statements, |count, block| {
                        count.checked_add(block.statements().len())
                    })
                    .ok_or(ProductionSemanticKirErrorV1::ResourceLimit {
                        resource: ProductionSemanticKirResourceV1::Statements,
                        actual: usize::MAX,
                        limit: limits.max_statements,
                    })?;
            }
            enforce_limit(
                ProductionSemanticKirResourceV1::Blocks,
                total_blocks,
                limits.max_blocks,
            )?;
            enforce_limit(
                ProductionSemanticKirResourceV1::Statements,
                total_statements,
                limits.max_statements,
            )?;

            let mut module = Module::new(format!(
                "fe2o3::semantic::{}",
                hex_identity(semantic.semantic_sha256().as_bytes())
            ));
            let mut lowered_functions = Vec::with_capacity(plans.len());
            let mut correspondence_blocks = Vec::new();
            let mut statement_operation_spans = Vec::new();
            let mut terminator_operation_spans = Vec::new();
            let mut generated_terminator_values = Vec::new();
            let mut call_returns = CallReturnBufferV1::empty();
            let mut synthetic_operation_spans = Vec::new();
            let mut parameter_bindings = Vec::new();
            let mut parameter_component_bindings = Vec::new();
            let mut ignored_parameter_bindings = Vec::new();
            let mut diagnostic_declarations = BTreeMap::new();
            let mut float_declarations = BTreeMap::new();
            let mut remaining_operations = limits.max_operations;
            let mut private_arrays = PrivateArrayMergeV1::new(limits.max_operations);
            for (index, plan) in plans.iter().enumerate() {
                let semantic_ssa = owner
                    .plan_for_function(plan.semantic_function)
                    .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
                let lowered = lower_one_semantic_function_for_composition_v1(
                    semantic,
                    plan,
                    semantic_ssa,
                    &defined_function_ids,
                    &defined_function_signatures,
                    (index == 0).then_some(required_workgroup).flatten(),
                    masked_decisions_for_plan_v1(semantic, plan, &assertions[index])?,
                    launch_rank,
                    authenticated_launch.is_some() && index == 0,
                    remaining_operations,
                    assert_origins.as_deref_mut(),
                    private_array_work,
                    Some((&private_arrays, outer_private_arrays)),
                    call_budget,
                    SemanticEmissionPlacementV1::default(),
                    None,
                    match admission {
                        HelperLoweringAdmissionV1::PendingOrderedComposition(permit) => {
                            Some(*permit)
                        }
                        _ => None,
                    },
                    match admission {
                        HelperLoweringAdmissionV1::PendingBf16Nominal(state) => Some(state),
                        _ => None,
                    },
                    Some(owner),
                )?;
                remaining_operations = remaining_operations
                    .checked_sub(lowered.emitted_operations)
                    .ok_or(ProductionSemanticKirErrorV1::ResourceLimit {
                        resource: ProductionSemanticKirResourceV1::Operations,
                        actual: limits.max_operations.saturating_add(1),
                        limit: limits.max_operations,
                    })?;
                private_arrays.append_function(
                    plan.correspondence_owner,
                    plan.semantic_function,
                    index,
                    lowered.emitted_operations,
                    lowered.private_arrays,
                    outer_private_arrays,
                    private_array_work,
                )?;
                module
                    .required_capabilities
                    .extend(lowered.operation_capabilities.iter().cloned());
                diagnostic_declarations.extend(lowered.diagnostic_declarations);
                float_declarations.extend(lowered.float_declarations);
                correspondence_blocks.extend(lowered.blocks);
                statement_operation_spans.extend(lowered.statement_operation_spans);
                terminator_operation_spans.extend(lowered.terminator_operation_spans);
                generated_terminator_values.extend(lowered.generated_terminator_values);
                call_returns.append(lowered.call_returns, limits.max_blocks, call_budget)?;
                synthetic_operation_spans.extend(lowered.synthetic_operation_spans);
                parameter_bindings.extend(lowered.parameter_bindings);
                append_correspondence_records_v1(
                    &mut parameter_component_bindings,
                    lowered.parameter_component_bindings,
                    ProductionSemanticKirResourceV1::DebugBindings,
                    limits.max_operations,
                )?;
                append_correspondence_records_v1(
                    &mut ignored_parameter_bindings,
                    lowered.ignored_parameter_bindings,
                    ProductionSemanticKirResourceV1::DebugBindings,
                    limits.max_operations,
                )?;
                lowered_functions.push(SemanticKirFunctionCorrespondenceV1 {
                    correspondence_owner: plan.correspondence_owner,
                    semantic_function: plan.semantic_function,
                    kernel_ir_function: plan.kernel_ir_function.clone(),
                    role: plan.role,
                });
                module.functions.push(lowered.function);
            }
            for declaration in diagnostic_declarations
                .into_values()
                .chain(float_declarations.into_values())
            {
                if module
                    .functions
                    .iter()
                    .any(|function| function.id == declaration.id)
                {
                    return Err(unsupported(
                        selection.body().index(),
                        None,
                        None,
                        "helper identity collides with a compiler intrinsic declaration",
                    ));
                }
                module.functions.push(declaration);
            }

            if let HelperLoweringAdmissionV1::PendingOrderedComposition(permit) = admission {
                propagate_ordered_composition_capabilities_v1(
                    &mut module,
                    semantic,
                    *permit,
                    symbol,
                    call_budget,
                )?;
            }
            if let HelperLoweringAdmissionV1::PendingBf16Nominal(state) = admission {
                bf16_pending_capabilities_v1(state, &plans, &mut module, symbol, call_budget)?;
            }
            finish_semantic_root_module_v1(
                &mut module,
                symbol,
                required_workgroup,
                launch_rank,
                authenticated_launch,
            )?;

            let effects = analyze_interprocedural_effects_v1(&module)
                .map_err(ProductionSemanticKirErrorV1::InvalidKernelIr)?;
            for plan in plans.iter().skip(1) {
                if !effects
                    .function(&plan.kernel_ir_function)
                    .is_some_and(|decision| decision.is_complete_and_pure())
                {
                    // This private pending category is not an effect summary.
                    // The only producer holds the live checked BF16 relation,
                    // and cannot return an owner until exact nominal replay.
                    if let HelperLoweringAdmissionV1::PendingBf16Nominal(state) = admission {
                        bf16_pending_helper_v1(state, plan, &module, call_budget)?;
                        continue;
                    }
                    // Source context has checked every helper scalar/marker statement.
                    // This private continuation cannot escape as an owner until the
                    // complete immutable V17 composition independently validates it.
                    if matches!(
                        admission,
                        HelperLoweringAdmissionV1::PendingOrderedComposition(_)
                    ) {
                        continue;
                    }
                    if let HelperLoweringAdmissionV1::PendingUnitLocal { requires_source } =
                        admission
                    {
                        let emission = assert_origins
                            .as_mut()
                            .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?;
                        if pending_unit_local_candidates_v1(
                            &module,
                            &plans,
                            &effects,
                            emission.budget,
                        )? {
                            *requires_source = true;
                            break;
                        }
                    }
                    let declaration_source = semantic
                        .functions()
                        .get(plan.semantic_function.index() as usize)
                        .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?
                        .source();
                    return Err(ProductionSemanticKirErrorV1::HelperEffectsUnavailable {
                        function: plan.semantic_function.index(),
                        declaration_source: Box::new(declaration_source),
                    });
                }
            }

            if private_arrays.active {
                private_array_work.charge_private_array_work(2)?;
                if private_arrays.recorded_instance_operations
                    > limits
                        .max_operations
                        .checked_sub(remaining_operations)
                        .ok_or(ProductionSemanticKirErrorV1::CorrespondenceMismatch)?
                {
                    return Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch);
                }
            }
            let (private_arrays, private_payload) =
                private_arrays.into_correspondence(private_array_work)?;
            let (call_returns, call_result_components) = call_returns.into_box(call_budget)?;
            let correspondence = SemanticKirCorrespondenceV1 {
                private_arrays,
                semantic_sha256: *semantic.semantic_sha256().as_bytes(),
                function_count: semantic.functions().len(),
                lowered_functions: lowered_functions.into_boxed_slice(),
                blocks: correspondence_blocks.into_boxed_slice(),
                statement_operation_spans: statement_operation_spans.into_boxed_slice(),
                terminator_operation_spans: terminator_operation_spans.into_boxed_slice(),
                generated_terminator_values: generated_terminator_values.into_boxed_slice(),
                call_returns,
                call_result_components,
                synthetic_operation_spans: synthetic_operation_spans.into_boxed_slice(),
                parameter_bindings: parameter_bindings.into_boxed_slice(),
                parameter_component_bindings: parameter_component_bindings.into_boxed_slice(),
                ignored_parameter_bindings: ignored_parameter_bindings.into_boxed_slice(),
            };
            if validate_correspondence {
                correspondence.validate_layout_against(owner, &module, &[selected_root], limits)?;
            }
            Ok((module, correspondence, private_payload))
        },
    )
}

fn semantic_source_argument_for_kir_parameter_v1(
    correspondence: &SemanticKirCorrespondenceV1,
    correspondence_owner: SemanticFunctionIdV1,
    function: &SemanticFunctionDeclV1,
    value: ValueId,
) -> Option<u32> {
    let semantic_function = correspondence
        .lowered_functions()
        .iter()
        .find(|record| {
            record.correspondence_owner() == correspondence_owner
                && record.role() == SemanticKirFunctionRoleV1::KernelEntry
        })?
        .semantic_function();
    let direct = correspondence
        .parameter_bindings()
        .iter()
        .filter_map(|binding| {
            (binding.correspondence_owner() == correspondence_owner
                && binding.semantic_function() == semantic_function
                && binding.kernel_ir_value() == value)
                .then_some(binding.semantic_local())
        });
    let component = correspondence
        .parameter_component_bindings()
        .iter()
        .filter_map(|binding| {
            (binding.correspondence_owner() == correspondence_owner
                && binding.semantic_function() == semantic_function
                && binding.kernel_ir_value() == value)
                .then_some(binding.semantic_local())
        });
    let mut matching = direct.chain(component);
    let local = matching.next()?;
    if matching.next().is_some() {
        return None;
    }
    match function.locals().get(local.index() as usize)?.role() {
        SemanticLocalRoleV1::Argument(argument) => Some(argument),
        SemanticLocalRoleV1::Return
        | SemanticLocalRoleV1::Temporary
        | SemanticLocalRoleV1::RustCallTupleField { .. } => None,
    }
}

