    fn lower_bf16_multiply_storage_for_test(
        lhs_storage: SemanticMfmaStorageLayoutV1,
        rhs_storage: SemanticMfmaStorageLayoutV1,
    ) -> Result<Vec<Operation>, ProductionSemanticKirErrorV1> {
        let unit = SemanticTypeIdV1::from_index(0);
        let lhs_fragment = SemanticTypeIdV1::from_index(1);
        let rhs_fragment = SemanticTypeIdV1::from_index(2);
        let accumulator_fragment = SemanticTypeIdV1::from_index(3);
        let source = SemanticSourceProvenanceV1::unavailable();
        let types = [
            unit_type(),
            SemanticTypeDeclV1::new(
                SemanticTypeIdentityV1::from_sha256([151; 32]),
                SemanticLayoutIdentityV1::from_sha256([152; 32]),
                SemanticTypeLayoutV1::new(Some(16), 4).unwrap(),
                SemanticTypeShapeV1::Opaque,
            ),
            SemanticTypeDeclV1::new(
                SemanticTypeIdentityV1::from_sha256([181; 32]),
                SemanticLayoutIdentityV1::from_sha256([182; 32]),
                SemanticTypeLayoutV1::new(Some(16), 4).unwrap(),
                SemanticTypeShapeV1::Opaque,
            ),
            SemanticTypeDeclV1::new(
                SemanticTypeIdentityV1::from_sha256([183; 32]),
                SemanticLayoutIdentityV1::from_sha256([184; 32]),
                SemanticTypeLayoutV1::new(Some(16), 4).unwrap(),
                SemanticTypeShapeV1::Opaque,
            ),
        ];
        let abi = SemanticFunctionAbiV1::from_rustc(
            SemanticAbiIdentityV1::from_sha256([153; 32]),
            SemanticLayoutIdentityV1::from_sha256([154; 32]),
            SemanticCanonAbiV1::Rust,
            SemanticExternAbiV1::Rust,
            false,
            false,
            0,
            vec![],
            SemanticAbiValueV1::new(unit, SemanticAbiPassModeV1::Ignore),
        )
        .unwrap();
        let callables = [SemanticCallableDeclV1::CompilerIntrinsic {
            binding: SemanticNonBodyCallableBindingV1::new(
                SemanticFunctionIdentityV1::from_sha256([155; 32]),
                SemanticItemDefinitionIdentityV1::from_sha256([156; 32]),
                SemanticMonomorphizationIdentityV1::from_sha256([157; 32]),
                SemanticGenericTypeArgumentsIdentityV1::from_sha256([158; 32]),
                SemanticConstGenericArgumentsIdentityV1::from_sha256([159; 32]),
                source,
                abi.clone(),
            ),
            operation: SemanticCompilerIntrinsicOperationV1::MatrixMultiplyAccumulate {
                context: unit,
                lhs_fragment,
                rhs_fragment,
                accumulator_fragment,
                lhs: operand_contract(SemanticMfmaOperandRoleV1::A),
                rhs: operand_contract(SemanticMfmaOperandRoleV1::B),
                accumulator: accumulator_contract(),
            },
            operation_identity: SemanticCompilerIntrinsicIdentityV1::from_sha256([160; 32]),
        }];
        let locals = [
            unit,
            unit,
            lhs_fragment,
            rhs_fragment,
            accumulator_fragment,
            accumulator_fragment,
        ]
        .into_iter()
        .enumerate()
        .map(|(ordinal, ty)| {
            SemanticLocalDeclV1::new(
                SemanticLocalIdentityV1::from_sha256([161 + ordinal as u8; 32]),
                ty,
                if ordinal == 0 {
                    SemanticLocalRoleV1::Return
                } else {
                    SemanticLocalRoleV1::Temporary
                },
                source,
            )
        })
        .collect();
        let blocks = [
            SemanticTerminatorKindV1::Goto(SemanticControlFlowEdgeV1::new(
                SemanticEdgeRoleV1::Goto,
                SemanticBlockIdV1::from_index(1),
            )),
            SemanticTerminatorKindV1::Return,
        ]
        .into_iter()
        .enumerate()
        .map(|(ordinal, terminator)| {
            SemanticBasicBlockV1::new(
                SemanticBlockIdentityV1::from_sha256([170 + ordinal as u8; 32]),
                source,
                vec![],
                SemanticTerminatorV1::new(source, terminator),
            )
            .unwrap()
        })
        .collect();
        let function = SemanticFunctionDeclV1::new(
            SemanticFunctionIdentityV1::from_sha256([172; 32]),
            SemanticFunctionRoleV1::InternalHelper,
            SemanticItemDefinitionIdentityV1::from_sha256([173; 32]),
            SemanticMonomorphizationIdentityV1::from_sha256([174; 32]),
            SemanticGenericTypeArgumentsIdentityV1::from_sha256([175; 32]),
            SemanticConstGenericArgumentsIdentityV1::from_sha256([176; 32]),
            source,
            abi,
            locals,
            SemanticBlockIdV1::from_index(0),
            blocks,
        )
        .unwrap();
        let mut test_emission_work = fe2o3_kernel_ir::CanonicalKernelIrWorkBudgetV1::new(1_000_000);
        let mut test_emission_budget =
            ArgumentBudgetV1::new(&mut test_emission_work, 16 * 1024 * 1024);
        let mut lowering = SemanticFunctionLoweringV1::new(
            &types,
            &callables,
            &function,
            SemanticParameterBindingsV1 {
                declarations: &[],
                values: &[],
                types: &[],
                local_bindings: None,
            },
            None,
            None,
            BTreeSet::new(),
            1,
            false,
            64,
            &mut test_emission_budget,
        )?;
        lowering.locals[1] = Some(SemanticValueBindingV1::MatrixContext);
        for (local, role, storage, base) in [
            (2, SemanticMfmaOperandRoleV1::A, lhs_storage, 0),
            (3, SemanticMfmaOperandRoleV1::B, rhs_storage, 4),
        ] {
            lowering.locals[local] = Some(SemanticValueBindingV1::MatrixFragment {
                values: (base..base + 4)
                    .map(|id| (ValueId(id), Type::Scalar(ScalarType::Bf16)))
                    .collect(),
                contract: operand_contract(role),
                storage_layout: storage,
                wave: SemanticCurrentWaveV1::new(64),
            });
        }
        lowering.locals[4] = Some(SemanticValueBindingV1::AccumulatorFragment {
            values: (8..12)
                .map(|id| (ValueId(id), Type::Scalar(ScalarType::F32)))
                .collect(),
            contract: accumulator_contract(),
            wave: SemanticCurrentWaveV1::new(64),
        });
        lowering.next_value = 12;
        let place = |local, ty| {
            SemanticPlaceV1::new(SemanticLocalIdV1::from_index(local), vec![], ty).unwrap()
        };
        let call = SemanticDirectCallV1::new_callable(
            SemanticCallableIdV1::from_index(0),
            [
                (1, unit),
                (2, lhs_fragment),
                (3, rhs_fragment),
                (4, accumulator_fragment),
            ]
            .into_iter()
            .map(|(local, ty)| SemanticOperandV1::Copy(place(local, ty)))
            .collect(),
            Some(SemanticCallDestinationV1::new(
                place(5, accumulator_fragment),
                SemanticControlFlowEdgeV1::new(
                    SemanticEdgeRoleV1::CallReturn,
                    SemanticBlockIdV1::from_index(1),
                ),
            )),
            SemanticUnwindActionV1::Unreachable,
        )
        .unwrap();
        let mut operations = Vec::new();
        lowering.lower_call(SemanticBlockIdV1::from_index(0), &call, &mut operations)?;
        Ok(operations)
    }

    #[test]
    fn bf16_multiply_preserves_the_register_operation_and_rejects_column_major_a() {
        let row = lower_bf16_multiply_storage_for_test(
            SemanticMfmaStorageLayoutV1::RowMajor,
            SemanticMfmaStorageLayoutV1::RowMajor,
        )
        .unwrap();
        let column = lower_bf16_multiply_storage_for_test(
            SemanticMfmaStorageLayoutV1::RowMajor,
            SemanticMfmaStorageLayoutV1::ColumnMajor,
        )
        .unwrap();
        assert_eq!(row, column);
        assert_eq!(
            column
                .iter()
                .filter(|operation| matches!(operation.kind, OperationKind::Matrix(_)))
                .count(),
            1
        );
        assert!(matches!(
            lower_bf16_multiply_storage_for_test(
                SemanticMfmaStorageLayoutV1::ColumnMajor,
                SemanticMfmaStorageLayoutV1::RowMajor
            ),
            Err(ProductionSemanticKirErrorV1::Unsupported {
                detail: "BF16 matrix source layout is not admitted for its operand role",
                ..
            })
        ));
    }

    #[test]
    fn production_semantic_kir_rejects_the_retired_option_load_and_accepts_v2() {
        let legacy = SemanticCompilerIntrinsicOperationV1::Bf16MatrixLoad {
            option_fragment: SemanticTypeIdV1::from_index(0),
            view: SemanticTypeIdV1::from_index(1),
            lane: SemanticTypeIdV1::from_index(2),
            fragment: SemanticTypeIdV1::from_index(3),
            contract: operand_contract(SemanticMfmaOperandRoleV1::A),
            storage_layout: SemanticMfmaStorageLayoutV1::RowMajor,
        };
        assert!(matches!(
            require_current_production_intrinsic_v1(&legacy),
            Err(ProductionSemanticKirErrorV1::Unsupported {
                function: 0,
                block: None,
                statement: None,
                detail: "the retired Option-returning BF16 matrix load is not admitted; use Bf16MatrixLoadZeroFilledV2",
            })
        ));

        let zero_filled = SemanticCompilerIntrinsicOperationV1::Bf16MatrixLoadZeroFilledV2 {
            fragment: SemanticTypeIdV1::from_index(3),
            view: SemanticTypeIdV1::from_index(1),
            lane: SemanticTypeIdV1::from_index(2),
            contract: operand_contract(SemanticMfmaOperandRoleV1::A),
            storage_layout: SemanticMfmaStorageLayoutV1::RowMajor,
        };
        assert!(require_current_production_intrinsic_v1(&zero_filled).is_ok());
    }

    #[test]
    fn mfma_operand_roles_map_independent_nonzero_bases_to_row_major_coordinates() {
        let minor_base = 11_u64;
        let reduction_base = 37_u64;
        let lane_minor = 5_u64;
        let lane_group = 8_u64;
        let component = 3_u64;
        let stride = 101_u64;

        let a = semantic_mfma_operand_bases_v1(
            SemanticMfmaOperandRoleV1::A,
            minor_base,
            reduction_base,
        );
        let b = semantic_mfma_operand_bases_v1(
            SemanticMfmaOperandRoleV1::B,
            reduction_base,
            minor_base,
        );
        assert_eq!(a, b);

        let minor = a.minor + lane_minor;
        let reduction = a.reduction + lane_group + component;
        assert_eq!(minor, 16);
        assert_eq!(reduction, 48);
        assert_eq!(minor * stride + reduction, 1_664);
        assert_eq!(reduction * stride + minor, 4_864);
    }

    #[test]
    fn mfma_operand_role_mapping_exposes_hostile_swapped_contracts() {
        let minor_base = 11_u64;
        let reduction_base = 37_u64;
        let expected = SemanticMfmaOperandBasesV1 {
            minor: minor_base,
            reduction: reduction_base,
        };

        assert_eq!(
            semantic_mfma_operand_bases_v1(
                SemanticMfmaOperandRoleV1::A,
                minor_base,
                reduction_base,
            ),
            expected
        );
        assert_eq!(
            semantic_mfma_operand_bases_v1(
                SemanticMfmaOperandRoleV1::B,
                reduction_base,
                minor_base,
            ),
            expected
        );
        assert_ne!(
            semantic_mfma_operand_bases_v1(
                SemanticMfmaOperandRoleV1::B,
                minor_base,
                reduction_base,
            ),
            expected
        );
        assert_ne!(
            semantic_mfma_operand_bases_v1(
                SemanticMfmaOperandRoleV1::A,
                reduction_base,
                minor_base,
            ),
            expected
        );
    }

