    struct GuardedAddressFixture {
        module: Module,
        locations: Vec<FunctionOperationLocation>,
    }

    fn generated_matrix_tail_fixture(component_count: usize) -> GuardedAddressFixture {
        fn emit(
            block: &mut BasicBlock,
            next_value: &mut u32,
            ty: Type,
            kind: OperationKind,
        ) -> ValueId {
            let id = ValueId(*next_value);
            *next_value += 1;
            block
                .operations
                .push(Operation::effect_free(ValueDef::new(id, ty), kind));
            id
        }

        let slice_type = Type::slice(
            Type::Scalar(ScalarType::U16),
            AddressSpace::Global,
            AccessMode::ReadOnly,
        );
        let pointer_type = Type::pointer(
            Type::Scalar(ScalarType::U16),
            AddressSpace::Global,
            AccessMode::ReadOnly,
        );
        let protected_slice = ValueId(0);
        let other_slice = ValueId(1);
        let base_index = ValueId(2);
        let mut next_value = 3;
        let mut block = BasicBlock::new(BlockId(0));
        let data = emit(
            &mut block,
            &mut next_value,
            pointer_type.clone(),
            OperationKind::SliceData {
                slice: protected_slice,
            },
        );
        let length = emit(
            &mut block,
            &mut next_value,
            Type::INDEX,
            OperationKind::SliceLength {
                slice: protected_slice,
            },
        );
        let zero = emit(
            &mut block,
            &mut next_value,
            Type::INDEX,
            OperationKind::Constant(Constant::Index(0)),
        );
        let valid = emit(
            &mut block,
            &mut next_value,
            Type::BOOL,
            OperationKind::Constant(Constant::Bool(true)),
        );
        let fallback = emit(
            &mut block,
            &mut next_value,
            Type::Scalar(ScalarType::U16),
            OperationKind::Constant(Constant::U16(0)),
        );

        let mut locations = Vec::new();
        for component in 0..component_count {
            let component = emit(
                &mut block,
                &mut next_value,
                Type::INDEX,
                OperationKind::Constant(Constant::Index(component as u64)),
            );
            let index = emit(
                &mut block,
                &mut next_value,
                Type::INDEX,
                OperationKind::Binary {
                    op: BinaryOp::Add,
                    lhs: base_index,
                    rhs: component,
                },
            );
            let in_bounds = emit(
                &mut block,
                &mut next_value,
                Type::BOOL,
                OperationKind::Compare {
                    predicate: ComparePredicate::LessThan,
                    lhs: index,
                    rhs: length,
                },
            );
            let guard = emit(
                &mut block,
                &mut next_value,
                Type::BOOL,
                OperationKind::Binary {
                    op: BinaryOp::BitAnd,
                    lhs: valid,
                    rhs: in_bounds,
                },
            );
            let safe_index = emit(
                &mut block,
                &mut next_value,
                Type::INDEX,
                OperationKind::Select {
                    condition: guard,
                    true_value: index,
                    false_value: zero,
                },
            );
            let pointer = emit(
                &mut block,
                &mut next_value,
                pointer_type.clone(),
                OperationKind::GetElementPointer {
                    base: data,
                    offset: safe_index,
                },
            );
            locations.push(FunctionOperationLocation::new(
                block.id,
                block.operations.len(),
            ));
            emit(
                &mut block,
                &mut next_value,
                Type::Scalar(ScalarType::U16),
                OperationKind::GuardedLoad {
                    pointer,
                    predicate: guard,
                    fallback,
                    access: MemoryAccess::new(AddressSpace::Global, 2),
                },
            );
        }
        block.terminator = Some(Terminator::Return { values: vec![] });

        let mut module = Module::new("generated-matrix-tail");
        module.functions.push(Function::kernel_entry(
            "generated_matrix_tail",
            Signature::new(vec![slice_type.clone(), slice_type, Type::INDEX], vec![]),
            vec![protected_slice, other_slice, base_index],
            vec![block],
        ));
        module.kernels.push(Kernel::new(
            "generated-matrix-tail",
            "generated_matrix_tail",
            LaunchDomain::D1 {
                x: LaunchExtent::Static(64),
            },
        ));
        verify_module(&module).expect("generated guarded-tail fixture must be valid Kernel IR");
        GuardedAddressFixture { module, locations }
    }

    fn guarded_fixture_operations_mut(fixture: &mut GuardedAddressFixture) -> &mut Vec<Operation> {
        &mut fixture.module.functions[0]
            .body
            .as_mut()
            .expect("fixture function is defined")
            .blocks[0]
            .operations
    }

    fn append_guarded_output_store(fixture: &mut GuardedAddressFixture) {
        let output_slice = Type::slice(
            Type::Scalar(ScalarType::U16),
            AddressSpace::Global,
            AccessMode::WriteOnly,
        );
        let output_pointer = Type::pointer(
            Type::Scalar(ScalarType::U16),
            AddressSpace::Global,
            AccessMode::WriteOnly,
        );
        fixture.module.functions[0].signature.parameters[1] = output_slice;
        let operations = guarded_fixture_operations_mut(fixture);
        let next_value = operations
            .iter()
            .flat_map(|operation| operation.results.iter().map(|result| result.id.0))
            .max()
            .unwrap()
            + 1;
        operations.push(Operation::effect_free(
            ValueDef::new(ValueId(next_value), output_pointer.clone()),
            OperationKind::SliceData { slice: ValueId(1) },
        ));
        operations.push(Operation::effect_free(
            ValueDef::new(ValueId(next_value + 1), output_pointer),
            OperationKind::GetElementPointer {
                base: ValueId(next_value),
                offset: ValueId(5),
            },
        ));
        operations.push(Operation::new(
            vec![],
            OperationKind::GuardedStore {
                pointer: ValueId(next_value + 1),
                predicate: ValueId(6),
                value: ValueId(7),
                access: MemoryAccess::new(AddressSpace::Global, 2),
            },
        ));
        verify_module(&fixture.module)
            .expect("guarded output store fixture must remain valid Kernel IR");
    }

    #[test]
    fn generated_matrix_tail_guarded_loads_have_structural_address_proofs() {
        let fixture = generated_matrix_tail_fixture(4);
        let operation_count = fixture.module.functions[0].body.as_ref().unwrap().blocks[0]
            .operations
            .len();
        assert!(guarded_accesses_have_structural_bounds(
            &fixture.module,
            &fixture.locations,
            operation_count,
        ));
    }

    #[test]
    fn guarded_load_audit_ignores_formally_analyzed_guarded_output_stores() {
        let mut fixture = generated_matrix_tail_fixture(2);
        append_guarded_output_store(&mut fixture);
        let operation_count = fixture.module.functions[0].body.as_ref().unwrap().blocks[0]
            .operations
            .len();
        assert!(guarded_accesses_have_structural_bounds(
            &fixture.module,
            &fixture.locations,
            operation_count,
        ));
    }

    #[test]
    fn guarded_address_proof_audits_unreported_structural_loads() {
        let mut fixture = generated_matrix_tail_fixture(2);
        let operations = guarded_fixture_operations_mut(&mut fixture);
        let always_true = operations[3].results[0].id;
        let OperationKind::Select { condition, .. } = &mut operations[16].kind else {
            panic!("second fixture select changed");
        };
        *condition = always_true;
        let OperationKind::GuardedLoad { predicate, .. } = &mut operations[18].kind else {
            panic!("second fixture guarded load changed");
        };
        *predicate = always_true;
        verify_module(&fixture.module)
            .expect("hostile unreported predicate remains valid Kernel IR");
        assert!(!guarded_accesses_have_structural_bounds(
            &fixture.module,
            &fixture.locations,
            19,
        ));
    }

    #[test]
    fn guarded_address_proof_rejects_true_predicate_with_unsafe_index() {
        let mut fixture = generated_matrix_tail_fixture(1);
        let operations = guarded_fixture_operations_mut(&mut fixture);
        let always_true = operations[3].results[0].id;
        let OperationKind::Select { condition, .. } = &mut operations[9].kind else {
            panic!("fixture select changed");
        };
        *condition = always_true;
        let OperationKind::GuardedLoad { predicate, .. } = &mut operations[11].kind else {
            panic!("fixture guarded load changed");
        };
        *predicate = always_true;
        verify_module(&fixture.module).expect("hostile true predicate remains structurally valid");
        assert!(!guarded_accesses_have_structural_bounds(
            &fixture.module,
            &fixture.locations,
            12,
        ));
    }

    #[test]
    fn guarded_address_proof_rejects_wrong_bound_slice_and_select() {
        let mut wrong_bound = generated_matrix_tail_fixture(1);
        let OperationKind::Compare { predicate, .. } =
            &mut guarded_fixture_operations_mut(&mut wrong_bound)[7].kind
        else {
            panic!("fixture comparison changed");
        };
        *predicate = ComparePredicate::Equal;
        verify_module(&wrong_bound.module).expect("hostile comparison remains valid Kernel IR");
        let kernel = &wrong_bound.module.kernels[0];
        let witness_extents = [64, 1, 1];
        let analysis = fe2o3_kernel_ir::derive_kernel_memory_obligations_for_launch(
            &wrong_bound.module,
            &kernel.id,
            fe2o3_kernel_ir::ExplicitLaunchExtent::Exact {
                rank: 1,
                extents: witness_extents,
            },
            FormalIndexWidth::Bits64,
        )
        .unwrap();
        let mut budget = GuardedAddressProofBudgetV1::new(12).unwrap();
        let failure = guarded_accesses_have_structural_bounds_result(
            &wrong_bound.module,
            kernel,
            analysis.obligations(),
            witness_extents,
            &wrong_bound.locations,
            12,
            &mut budget,
        )
        .expect_err("wrong comparison must not prove a slice bound");
        assert!(matches!(
            failure,
            ProductionMemoryDischargeFailureV1::GuardedBound {
                location,
                index: ValueId(9),
                slice: ValueId(0),
                ..
            } if location == wrong_bound.locations[0]
        ));
        assert!(
            failure
                .to_string()
                .contains("must be below the length of slice")
        );

        let mut wrong_slice = generated_matrix_tail_fixture(1);
        let OperationKind::SliceLength { slice } =
            &mut guarded_fixture_operations_mut(&mut wrong_slice)[1].kind
        else {
            panic!("fixture slice length changed");
        };
        *slice = ValueId(1);
        verify_module(&wrong_slice.module).expect("other slice has the same valid type");
        assert!(!guarded_accesses_have_structural_bounds(
            &wrong_slice.module,
            &wrong_slice.locations,
            12,
        ));

        let mut wrong_select = generated_matrix_tail_fixture(1);
        let OperationKind::Select { false_value, .. } =
            &mut guarded_fixture_operations_mut(&mut wrong_select)[9].kind
        else {
            panic!("fixture select changed");
        };
        *false_value = ValueId(2);
        verify_module(&wrong_select.module).expect("hostile fallback index remains well typed");
        assert!(!guarded_accesses_have_structural_bounds(
            &wrong_select.module,
            &wrong_select.locations,
            12,
        ));
    }

    #[test]
    fn guarded_address_proof_fails_closed_for_locations_defs_cycles_and_budget() {
        let fixture = generated_matrix_tail_fixture(1);
        assert!(!guarded_accesses_have_structural_bounds(
            &fixture.module,
            &[],
            12,
        ));
        assert!(!guarded_accesses_have_structural_bounds(
            &fixture.module,
            &[fixture.locations[0], fixture.locations[0]],
            12,
        ));
        assert!(!guarded_accesses_have_structural_bounds(
            &fixture.module,
            &fixture.locations,
            0,
        ));

        let mut missing = generated_matrix_tail_fixture(1);
        guarded_fixture_operations_mut(&mut missing).remove(7);
        assert!(!guarded_accesses_have_structural_bounds(
            &missing.module,
            &[FunctionOperationLocation::new(BlockId(0), 10)],
            11,
        ));

        let mut ambiguous = generated_matrix_tail_fixture(1);
        let duplicate = guarded_fixture_operations_mut(&mut ambiguous)[7].clone();
        guarded_fixture_operations_mut(&mut ambiguous).push(duplicate);
        assert!(!guarded_accesses_have_structural_bounds(
            &ambiguous.module,
            &ambiguous.locations,
            13,
        ));

        let mut cyclic = generated_matrix_tail_fixture(1);
        let guard = guarded_fixture_operations_mut(&mut cyclic)[8].results[0].id;
        let OperationKind::Binary { lhs, .. } =
            &mut guarded_fixture_operations_mut(&mut cyclic)[8].kind
        else {
            panic!("fixture guard changed");
        };
        *lhs = guard;
        assert!(!guarded_accesses_have_structural_bounds(
            &cyclic.module,
            &cyclic.locations,
            12,
        ));
    }

    use super::bf16_ranked_module_receipt_v1::{
        PrivateBf16FormalAttemptForTestV1 as PrivateBf16FormalAttemptV1,
        PrivateBf16GuardedFormalResultForTestV1 as PrivateBf16GuardedFormalResultV1,
        private_bf16_ranked_formal_frame_storage_for_test_v1 as private_bf16_ranked_formal_frame_storage_v1,
        with_private_bf16_ranked_formal_frame_for_test_v1 as with_private_bf16_ranked_formal_frame_v1,
    };

    // Inert graph/resource controls for the private continuation. Actual intact
    // owner/source qualification remains a separate fresh frontend endpoint.
    fn ranked_formal_fixture_attempt_v1(
        fixture: &GuardedAddressFixture,
    ) -> PrivateBf16FormalAttemptV1 {
        fe2o3_kernel_ir::derive_kernel_memory_obligations_for_launch(
            &fixture.module,
            &fixture.module.kernels[0].id,
            fe2o3_kernel_ir::ExplicitLaunchExtent::Exact {
                rank: 1,
                extents: [64, 1, 1],
            },
            FormalIndexWidth::Bits64,
        )
    }

    fn observe_ranked_formal_success_v1(
        attempt: &PrivateBf16FormalAttemptV1,
        proof: &PrivateBf16GuardedFormalResultV1,
        _: &mut ArgumentBudgetV1<'_>,
    ) -> Result<(), ProductionSemanticKirErrorV1> {
        assert!(proof.is_ok());
        assert!(
            matches!(attempt, Ok(fe2o3_kernel_ir::FormalMemoryObligationAnalysis::Incomplete { reasons, .. }) if !reasons.is_empty())
        );
        Ok(())
    }

    fn ranked_formal_resource_trial_v1(
        work_limit: usize,
        storage_limit: usize,
    ) -> (bool, usize, usize, Option<usize>, Option<usize>) {
        let fixture = generated_matrix_tail_fixture(4);
        let attempt = ranked_formal_fixture_attempt_v1(&fixture);
        let original = attempt.clone();
        let max = fixture.module.functions[0].body.as_ref().unwrap().blocks[0]
            .operations
            .len();
        let mut work = fe2o3_kernel_ir::CanonicalKernelIrWorkBudgetV1::new(work_limit);
        let mut budget = ArgumentBudgetV1::new(&mut work, storage_limit);
        budget.reserve_storage(7).unwrap();
        let ledger = budget.work_ledger_identity_v1();
        let result = with_private_bf16_ranked_formal_frame_v1(
            &fixture.module,
            &fixture.module.kernels[0],
            [64, 1, 1],
            max,
            0,
            &attempt,
            &mut budget,
            observe_ranked_formal_success_v1,
        );
        assert_eq!(
            attempt, original,
            "raw incomplete analysis/reasons must not be edited"
        );
        assert!(budget.work_ledger_identity_v1() == ledger);
        assert_eq!(budget.storage(), 7);
        (
            result.is_ok(),
            budget.work(),
            budget.peak_storage(),
            budget.failed_work(),
            budget.failed_storage(),
        )
    }

    #[test]
    fn private_ranked_formal_frame_exact_and_one_short_preserve_raw_reasons() {
        let (ok, work, peak, failed_work, failed_storage) =
            ranked_formal_resource_trial_v1(100_000, 100_000);
        assert!(ok);
        assert_eq!((failed_work, failed_storage), (None, None));
        assert_eq!(
            ranked_formal_resource_trial_v1(work, peak),
            (true, work, peak, None, None)
        );
        let short_work = ranked_formal_resource_trial_v1(work - 1, peak);
        assert!(!short_work.0);
        assert!(short_work.3.is_some());
        let short_storage = ranked_formal_resource_trial_v1(work, peak - 1);
        assert!(!short_storage.0);
        assert!(short_storage.4.is_some());
    }

    #[test]
    fn private_ranked_formal_altered_guard_slice_index_and_select_refuse() {
        for mutation in 0..5 {
            let mut fixture = generated_matrix_tail_fixture(1);
            let operations = guarded_fixture_operations_mut(&mut fixture);
            match mutation {
                0 => {
                    let true_value = operations[3].results[0].id;
                    let OperationKind::Select { condition, .. } = &mut operations[9].kind else {
                        panic!()
                    };
                    *condition = true_value;
                    let OperationKind::GuardedLoad { predicate, .. } = &mut operations[11].kind
                    else {
                        panic!()
                    };
                    *predicate = true_value;
                }
                1 => {
                    let OperationKind::SliceLength { slice } = &mut operations[1].kind else {
                        panic!()
                    };
                    *slice = ValueId(1);
                }
                2 => {
                    let OperationKind::Compare { lhs, .. } = &mut operations[7].kind else {
                        panic!()
                    };
                    *lhs = ValueId(5);
                }
                3 => {
                    let OperationKind::Compare { predicate, .. } = &mut operations[7].kind else {
                        panic!()
                    };
                    *predicate = ComparePredicate::Equal;
                }
                4 => {
                    let OperationKind::Select { false_value, .. } = &mut operations[9].kind else {
                        panic!()
                    };
                    *false_value = ValueId(2);
                }
                _ => unreachable!(),
            }
            verify_module(&fixture.module).unwrap();
            let attempt = ranked_formal_fixture_attempt_v1(&fixture);
            assert!(
                attempt.is_ok(),
                "mutation remains valid formal-analysis input"
            );
            let mut work = fe2o3_kernel_ir::CanonicalKernelIrWorkBudgetV1::new(100_000);
            let mut budget = ArgumentBudgetV1::new(&mut work, 100_000);
            budget.reserve_storage(7).unwrap();
            let mut observed = false;
            let result = with_private_bf16_ranked_formal_frame_v1(
                &fixture.module,
                &fixture.module.kernels[0],
                [64, 1, 1],
                12,
                0,
                &attempt,
                &mut budget,
                |_, proof, _| {
                    observed = true;
                    assert!(proof.is_err());
                    Ok(()) // Deliberately ignoring refusal cannot authorize success.
                },
            );
            assert!(observed);
            assert!(matches!(
                result,
                Err(ProductionSemanticKirErrorV1::Unsupported {
                    detail: "private nominal ranked formal guard discharge refused",
                    ..
                })
            ));
            assert_eq!(budget.storage(), 7);
            assert!(budget.check_prior_denials_v1().is_ok());
        }
    }

    #[test]
    fn private_ranked_formal_pending_coverage_unrelated_reasons_and_witness_refuse() {
        for mutation in 0..7 {
            let fixture = generated_matrix_tail_fixture(2);
            let mut attempt = ranked_formal_fixture_attempt_v1(&fixture);
            let Ok(fe2o3_kernel_ir::FormalMemoryObligationAnalysis::Incomplete { reasons, .. }) =
                &mut attempt
            else {
                panic!("fixture requires ranked discharge")
            };
            match mutation {
                0 => {
                    reasons.pop();
                }
                1 => {
                    reasons.push(reasons[0].clone());
                }
                2 => {
                    reasons[0] = FormalMemoryIncompleteReason::GuardedAccessRequiresRankedProof {
                        location: FunctionOperationLocation::new(BlockId(999), 11),
                    };
                }
                3 => {
                    reasons[0] = FormalMemoryIncompleteReason::GuardedAccessRequiresRankedProof {
                        location: FunctionOperationLocation::new(BlockId(0), 10),
                    };
                }
                4 => {
                    reasons.push(FormalMemoryIncompleteReason::LaunchExtentUnknown);
                }
                5 => {
                    reasons.clear();
                }
                6 => {}
                _ => unreachable!(),
            }
            let original = attempt.clone();
            let mut work = fe2o3_kernel_ir::CanonicalKernelIrWorkBudgetV1::new(100_000);
            let mut budget = ArgumentBudgetV1::new(&mut work, 100_000);
            budget.reserve_storage(7).unwrap();
            let result = with_private_bf16_ranked_formal_frame_v1(
                &fixture.module,
                &fixture.module.kernels[0],
                if mutation == 6 {
                    [65, 1, 1]
                } else {
                    [64, 1, 1]
                },
                19,
                0,
                &attempt,
                &mut budget,
                |_, proof, _| {
                    assert!(proof.is_err());
                    Ok(())
                },
            );
            assert!(result.is_err());
            assert_eq!(attempt, original);
            assert_eq!(budget.storage(), 7);
        }
    }

    #[test]
    fn private_ranked_formal_original_denials_precede_any_new_debit() {
        let fixture = generated_matrix_tail_fixture(1);
        let attempt = ranked_formal_fixture_attempt_v1(&fixture);
        for storage in [false, true] {
            let mut work = fe2o3_kernel_ir::CanonicalKernelIrWorkBudgetV1::new(5);
            let mut budget = ArgumentBudgetV1::new(&mut work, 7);
            budget.reserve_storage(7).unwrap();
            budget.charge_work(5).unwrap();
            let original = if storage {
                budget.reserve_storage(1).unwrap_err()
            } else {
                budget.charge_work(4).unwrap_err()
            };
            let before = (
                budget.work(),
                budget.storage(),
                budget.peak_storage(),
                budget.failed_work(),
                budget.failed_storage(),
            );
            for _ in 0..2 {
                let result = with_private_bf16_ranked_formal_frame_v1(
                    &fixture.module,
                    &fixture.module.kernels[0],
                    [64, 1, 1],
                    12,
                    0,
                    &attempt,
                    &mut budget,
                    |_, _, _| panic!("prior denial must precede callback"),
                );
                assert!(matches!(result,
                    Err(ProductionSemanticKirErrorV1::ArgumentCorrespondenceResource(error))
                        if error == original));
                assert_eq!(
                    (
                        budget.work(),
                        budget.storage(),
                        budget.peak_storage(),
                        budget.failed_work(),
                        budget.failed_storage()
                    ),
                    before
                );
            }
        }
    }

    #[test]
    fn private_ranked_formal_callback_refusal_surplus_and_panic_do_not_escape_cleanup() {
        let fixture = generated_matrix_tail_fixture(1);
        let attempt = ranked_formal_fixture_attempt_v1(&fixture);
        for action in 0..4 {
            let mut work = fe2o3_kernel_ir::CanonicalKernelIrWorkBudgetV1::new(100_000);
            let mut budget = ArgumentBudgetV1::new(&mut work, 100_000);
            budget.reserve_storage(7).unwrap();
            let inspect = |_: &PrivateBf16FormalAttemptV1,
                           proof: &PrivateBf16GuardedFormalResultV1,
                           budget: &mut ArgumentBudgetV1<'_>| {
                assert!(proof.is_ok());
                match action {
                    0 => Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch),
                    1 => {
                        budget.reserve_storage(1)?;
                        Ok(())
                    }
                    2 => {
                        budget.release_storage(1)?;
                        Ok(())
                    }
                    3 => panic!("private ranked proof callback"),
                    _ => unreachable!(),
                }
            };
            let scratch = private_bf16_ranked_formal_frame_storage_v1(&inspect).unwrap()
                + std::mem::size_of::<FunctionOperationLocation>();
            let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                with_private_bf16_ranked_formal_frame_v1(
                    &fixture.module,
                    &fixture.module.kernels[0],
                    [64, 1, 1],
                    12,
                    0,
                    &attempt,
                    &mut budget,
                    inspect,
                )
            }));
            match action {
                0 => {
                    assert!(matches!(
                        result,
                        Ok(Err(ProductionSemanticKirErrorV1::CorrespondenceMismatch))
                    ));
                    assert_eq!(budget.storage(), 7);
                }
                1 | 2 => {
                    assert!(matches!(
                        result,
                        Ok(Err(
                            ProductionSemanticKirErrorV1::ArgumentCorrespondenceResource(
                                ArgumentResourceV1::Accounting
                            )
                        ))
                    ));
                    assert_eq!(
                        budget.storage(),
                        if action == 1 {
                            7 + scratch + 1
                        } else {
                            7 + scratch - 1
                        }
                    );
                }
                3 => {
                    assert!(result.is_err());
                    assert_eq!(budget.storage(), 7 + scratch);
                }
                _ => unreachable!(),
            }
        }
    }

