    #[test]
    fn workgroup_scan_geometry_accepts_every_bounded_1d_extent_and_rejects_substitution() {
        for size in [1_u32, 3, 65, 255, 256] {
            assert_eq!(
                validate_workgroup_scan_geometry_v1(Some([size, 1, 1]), Some(size)),
                Ok(size)
            );
        }
        for dimensions in [[0, 1, 1], [257, 1, 1], [3, 2, 1], [3, 1, 2]] {
            assert!(
                validate_workgroup_scan_geometry_v1(Some(dimensions), Some(dimensions[0])).is_err()
            );
        }
        assert!(validate_workgroup_scan_geometry_v1(None, Some(3)).is_err());
        assert!(validate_workgroup_scan_geometry_v1(Some([3, 1, 1]), Some(4)).is_err());
        assert!(validate_workgroup_reduction_geometry_v1(Some([3, 1, 1]), Some(3), None).is_err());
        assert_eq!(
            [1_u32, 3, 65, 255, 256].map(workgroup_scan_rounds_v1),
            [0, 2, 7, 8, 8]
        );
    }

    struct NeutralRecipeReplayFixtureV1 {
        body: FunctionBody,
        correspondence: SemanticKirCorrespondenceV1,
        contract: NeutralWorkgroupRecipeContractV1,
    }

    fn push_neutral_recipe_result_v1(
        operations: &mut Vec<Operation>,
        next_value: &mut u32,
        ty: Type,
        kind: OperationKind,
    ) -> ValueId {
        let value = ValueId(*next_value);
        *next_value += 1;
        operations.push(Operation::effect_free(ValueDef::new(value, ty), kind));
        value
    }

    fn neutral_recipe_barrier_v1() -> Operation {
        Operation::new(
            Vec::new(),
            OperationKind::WorkgroupBarrier(WorkgroupBarrier {
                memory_scope: SynchronizationScope::Workgroup,
                semantics: BarrierSemantics::new(
                    MemoryOrdering::AcquireRelease,
                    [AddressSpace::Workgroup],
                ),
                convergence: Convergence::uniform(SynchronizationScope::Workgroup),
            }),
        )
    }

    fn neutral_recipe_replay_fixture_v1(
        elements: u32,
        scalar: ScalarType,
    ) -> NeutralRecipeReplayFixtureV1 {
        assert!(elements.is_power_of_two());
        let semantic_function = SemanticFunctionIdV1::from_index(0);
        let producer_block = 0_u32;
        let consumer_block = 1_u32;
        let scalar_ty = Type::Scalar(scalar);
        let pointer_ty = Type::pointer(
            scalar_ty.clone(),
            AddressSpace::Workgroup,
            AccessMode::ReadWrite,
        );
        let mut next_value = 0_u32;
        let mut producer = BasicBlock::new(BlockId(producer_block));
        let base = push_neutral_recipe_result_v1(
            &mut producer.operations,
            &mut next_value,
            pointer_ty.clone(),
            OperationKind::WorkgroupMemory(WorkgroupMemory {
                element: scalar_ty.clone(),
                extent: WorkgroupMemoryExtent::Static(elements),
                alignment: 4,
            }),
        );
        producer.terminator = Some(Terminator::Branch {
            target: BlockId(consumer_block),
            arguments: Vec::new(),
        });

        let mut consumer = BasicBlock::new(BlockId(consumer_block));
        let input_constant = match scalar {
            ScalarType::U32 => Constant::U32(7),
            ScalarType::I32 => Constant::I32(-7),
            ScalarType::F32 => Constant::F32Bits(7.0_f32.to_bits()),
            _ => panic!("unsupported neutral-recipe test scalar"),
        };
        let input = push_neutral_recipe_result_v1(
            &mut consumer.operations,
            &mut next_value,
            scalar_ty.clone(),
            OperationKind::Constant(input_constant),
        );
        let first_recipe_operation = consumer.operations.len();
        let rank = push_neutral_recipe_result_v1(
            &mut consumer.operations,
            &mut next_value,
            Type::INDEX,
            OperationKind::Intrinsic(IntrinsicOperation::new(
                IntrinsicKind::InvocationIndex {
                    kind: IndexKind::Local,
                    axis: Axis::X,
                },
                Type::INDEX,
            )),
        );
        let initial_pointer = push_neutral_recipe_result_v1(
            &mut consumer.operations,
            &mut next_value,
            pointer_ty.clone(),
            OperationKind::GetElementPointer { base, offset: rank },
        );
        consumer.operations.push(Operation::new(
            Vec::new(),
            OperationKind::Store {
                pointer: initial_pointer,
                value: input,
                access: MemoryAccess::new(AddressSpace::Workgroup, 4),
            },
        ));
        consumer.operations.push(neutral_recipe_barrier_v1());

        let mut offset = elements >> 1;
        while offset != 0 {
            let offset_value = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                Type::INDEX,
                OperationKind::Constant(Constant::Index(u64::from(offset))),
            );
            let active = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                Type::BOOL,
                OperationKind::Compare {
                    predicate: ComparePredicate::LessThan,
                    lhs: rank,
                    rhs: offset_value,
                },
            );
            let pair = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                Type::INDEX,
                OperationKind::Binary {
                    op: BinaryOp::Add,
                    lhs: rank,
                    rhs: offset_value,
                },
            );
            let zero = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                Type::INDEX,
                OperationKind::Constant(Constant::Index(0)),
            );
            let safe_pair = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                Type::INDEX,
                OperationKind::Select {
                    condition: active,
                    true_value: pair,
                    false_value: zero,
                },
            );
            let lhs_pointer = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                pointer_ty.clone(),
                OperationKind::GetElementPointer { base, offset: rank },
            );
            let lhs = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                scalar_ty.clone(),
                OperationKind::Load {
                    pointer: lhs_pointer,
                    access: MemoryAccess::new(AddressSpace::Workgroup, 4),
                },
            );
            let rhs_pointer = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                pointer_ty.clone(),
                OperationKind::GetElementPointer {
                    base,
                    offset: safe_pair,
                },
            );
            let rhs = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                scalar_ty.clone(),
                OperationKind::Load {
                    pointer: rhs_pointer,
                    access: MemoryAccess::new(AddressSpace::Workgroup, 4),
                },
            );
            let sum = push_neutral_recipe_sum_v1(
                &mut consumer.operations,
                &mut next_value,
                &scalar_ty,
                lhs,
                rhs,
            );
            let selected = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                scalar_ty.clone(),
                OperationKind::Select {
                    condition: active,
                    true_value: sum,
                    false_value: lhs,
                },
            );
            consumer.operations.push(neutral_recipe_barrier_v1());
            let store_pointer = push_neutral_recipe_result_v1(
                &mut consumer.operations,
                &mut next_value,
                pointer_ty.clone(),
                OperationKind::GetElementPointer { base, offset: rank },
            );
            consumer.operations.push(Operation::new(
                Vec::new(),
                OperationKind::Store {
                    pointer: store_pointer,
                    value: selected,
                    access: MemoryAccess::new(AddressSpace::Workgroup, 4),
                },
            ));
            consumer.operations.push(neutral_recipe_barrier_v1());
            offset >>= 1;
        }
        let zero = push_neutral_recipe_result_v1(
            &mut consumer.operations,
            &mut next_value,
            Type::INDEX,
            OperationKind::Constant(Constant::Index(0)),
        );
        let final_pointer = push_neutral_recipe_result_v1(
            &mut consumer.operations,
            &mut next_value,
            pointer_ty,
            OperationKind::GetElementPointer { base, offset: zero },
        );
        let output = push_neutral_recipe_result_v1(
            &mut consumer.operations,
            &mut next_value,
            scalar_ty,
            OperationKind::Load {
                pointer: final_pointer,
                access: MemoryAccess::new(AddressSpace::Workgroup, 4),
            },
        );
        consumer.operations.push(neutral_recipe_barrier_v1());
        consumer.terminator = Some(Terminator::Return { values: Vec::new() });
        let recipe_operation_count = consumer.operations.len() - first_recipe_operation;

        let body = Function::kernel_entry(
            "neutral_recipe_replay",
            Signature::new(Vec::new(), Vec::new()),
            Vec::new(),
            vec![producer, consumer],
        )
        .body
        .expect("the neutral recipe fixture has a body");
        let correspondence = SemanticKirCorrespondenceV1 {
            private_arrays: PrivateArrayCorrespondenceV1::default(),
            semantic_sha256: [191; 32],
            function_count: 1,
            lowered_functions: vec![SemanticKirFunctionCorrespondenceV1 {
                correspondence_owner: semantic_function,
                semantic_function,
                kernel_ir_function: FunctionId::from("neutral_recipe_replay"),
                role: SemanticKirFunctionRoleV1::KernelEntry,
            }]
            .into_boxed_slice(),
            blocks: vec![
                SemanticKirBlockCorrespondenceV1 {
                    correspondence_owner: semantic_function,
                    semantic_function,
                    semantic_block: SemanticBlockIdV1::from_index(producer_block),
                    kernel_ir_block: BlockId(producer_block),
                    source_statement_count: 0,
                },
                SemanticKirBlockCorrespondenceV1 {
                    correspondence_owner: semantic_function,
                    semantic_function,
                    semantic_block: SemanticBlockIdV1::from_index(consumer_block),
                    kernel_ir_block: BlockId(consumer_block),
                    source_statement_count: 0,
                },
            ]
            .into_boxed_slice(),
            statement_operation_spans: Box::new([]),
            terminator_operation_spans: vec![
                SemanticKirTerminatorOperationSpanV1 {
                    correspondence_owner: semantic_function,
                    semantic_function,
                    semantic_block: SemanticBlockIdV1::from_index(producer_block),
                    kernel_ir_block: BlockId(producer_block),
                    first_operation_ordinal: 0,
                    operation_count: 1,
                },
                SemanticKirTerminatorOperationSpanV1 {
                    correspondence_owner: semantic_function,
                    semantic_function,
                    semantic_block: SemanticBlockIdV1::from_index(consumer_block),
                    kernel_ir_block: BlockId(consumer_block),
                    first_operation_ordinal: first_recipe_operation as u32,
                    operation_count: recipe_operation_count as u32,
                },
            ]
            .into_boxed_slice(),
            call_returns: Box::new([]),
            call_result_components: Box::new([]),
            generated_terminator_values: vec![SemanticKirGeneratedTerminatorValuesV1 {
                correspondence_owner: semantic_function,
                semantic_function,
                semantic_block: SemanticBlockIdV1::from_index(consumer_block),
                destination_local: SemanticLocalIdV1::from_index(1),
                input,
                output,
            }]
            .into_boxed_slice(),
            synthetic_operation_spans: Box::new([]),
            parameter_bindings: Box::new([]),
            parameter_component_bindings: Box::new([]),
            ignored_parameter_bindings: Box::new([]),
        };
        NeutralRecipeReplayFixtureV1 {
            body,
            correspondence,
            contract: NeutralWorkgroupRecipeContractV1 {
                correspondence_owner: semantic_function,
                semantic_function,
                producer_block,
                consumer_block,
                kind: NeutralWorkgroupRecipeKindV1::Reduction,
                elements,
                scalar,
                recipe_identity: [193; 32],
                allocation_origin: 0x1930,
                noalias_class: 0x1931,
                input,
                output,
            },
        }
    }

    fn replay_neutral_recipe_fixture_v1(
        fixture: &NeutralRecipeReplayFixtureV1,
    ) -> Result<Vec<ReplayedGeneratedEffectV1>, ProductionMirPlironTranslationErrorV1> {
        let mut budget = UnsupportedIndexCorrelationBudgetV1 { remaining: 16_384 };
        let kir = build_kir_correlation_index(&fixture.body, 256, &mut budget)
            .expect("bounded neutral fixture must index");
        replay_neutral_workgroup_recipe_v1(
            fixture.contract,
            &fixture.body,
            &fixture.correspondence,
            &kir,
        )
    }

    fn neutral_consumer_operations_mut_v1(
        fixture: &mut NeutralRecipeReplayFixtureV1,
    ) -> &mut Vec<Operation> {
        &mut fixture.body.blocks[1].operations
    }

    fn assert_neutral_recipe_mismatch_v1(fixture: &NeutralRecipeReplayFixtureV1) {
        assert!(matches!(
            replay_neutral_recipe_fixture_v1(fixture),
            Err(
                ProductionMirPlironTranslationErrorV1::GeneratedEffectRecipeMismatch {
                    semantic_block: 1,
                    ..
                }
            )
        ));
    }

    #[test]
    fn neutral_recipe_replay_accepts_exact_width_and_scalar_matrix() {
        for elements in [1_u32, 2, 64, 256] {
            for scalar in [ScalarType::I32, ScalarType::U32, ScalarType::F32] {
                let fixture = neutral_recipe_replay_fixture_v1(elements, scalar);
                let events = replay_neutral_recipe_fixture_v1(&fixture)
                    .expect("the exact generated recipe must replay");
                assert_eq!(events.len(), (5 * elements.ilog2() + 4) as usize);
                assert_eq!(
                    events
                        .iter()
                        .filter(|event| matches!(
                            event.effect,
                            NormalizedGeneratedExecutableEffectV1::Synchronization(_)
                        ))
                        .count(),
                    (2 * elements.ilog2() + 2) as usize,
                );
            }
        }
    }

    #[test]
    fn neutral_recipe_replay_rejects_deleted_duplicated_reordered_and_trailing_operations() {
        let mut deleted = neutral_recipe_replay_fixture_v1(2, ScalarType::U32);
        let barrier = neutral_consumer_operations_mut_v1(&mut deleted)
            .iter()
            .position(|operation| matches!(operation.kind, OperationKind::WorkgroupBarrier(_)))
            .unwrap();
        neutral_consumer_operations_mut_v1(&mut deleted).remove(barrier);
        deleted.correspondence.terminator_operation_spans[1].operation_count -= 1;
        assert_neutral_recipe_mismatch_v1(&deleted);

        let mut duplicated = neutral_recipe_replay_fixture_v1(2, ScalarType::U32);
        let barrier = neutral_consumer_operations_mut_v1(&mut duplicated)
            .iter()
            .position(|operation| matches!(operation.kind, OperationKind::WorkgroupBarrier(_)))
            .unwrap();
        let duplicate = neutral_consumer_operations_mut_v1(&mut duplicated)[barrier].clone();
        neutral_consumer_operations_mut_v1(&mut duplicated).insert(barrier, duplicate);
        duplicated.correspondence.terminator_operation_spans[1].operation_count += 1;
        assert_neutral_recipe_mismatch_v1(&duplicated);

        let mut reordered = neutral_recipe_replay_fixture_v1(2, ScalarType::U32);
        let store = neutral_consumer_operations_mut_v1(&mut reordered)
            .iter()
            .position(|operation| matches!(operation.kind, OperationKind::Store { .. }))
            .unwrap();
        neutral_consumer_operations_mut_v1(&mut reordered).swap(store, store + 1);
        assert_neutral_recipe_mismatch_v1(&reordered);

        let mut moved_barrier = neutral_recipe_replay_fixture_v1(2, ScalarType::U32);
        let barrier_position = neutral_consumer_operations_mut_v1(&mut moved_barrier)
            .iter()
            .position(|operation| matches!(operation.kind, OperationKind::WorkgroupBarrier(_)))
            .unwrap();
        let barrier =
            neutral_consumer_operations_mut_v1(&mut moved_barrier).remove(barrier_position);
        neutral_consumer_operations_mut_v1(&mut moved_barrier)
            .insert(barrier_position + 2, barrier);
        assert_neutral_recipe_mismatch_v1(&moved_barrier);

        let mut trailing = neutral_recipe_replay_fixture_v1(2, ScalarType::U32);
        let store = neutral_consumer_operations_mut_v1(&mut trailing)
            .iter()
            .find(|operation| matches!(operation.kind, OperationKind::Store { .. }))
            .unwrap()
            .clone();
        neutral_consumer_operations_mut_v1(&mut trailing).push(store);
        trailing.correspondence.terminator_operation_spans[1].operation_count += 1;
        assert_neutral_recipe_mismatch_v1(&trailing);
    }

    #[test]
    fn neutral_recipe_replay_binds_rank_pair_safe_pair_zero_gep_base_and_types() {
        let mutate_and_reject = |mutation: fn(&mut Vec<Operation>)| {
            let mut fixture = neutral_recipe_replay_fixture_v1(2, ScalarType::I32);
            mutation(neutral_consumer_operations_mut_v1(&mut fixture));
            assert_neutral_recipe_mismatch_v1(&fixture);
        };
        mutate_and_reject(|operations| {
            let OperationKind::Intrinsic(intrinsic) = &mut operations[1].kind else {
                unreachable!();
            };
            intrinsic.kind = IntrinsicKind::InvocationIndex {
                kind: IndexKind::Local,
                axis: Axis::Y,
            };
        });
        mutate_and_reject(|operations| {
            let operation = operations
                .iter_mut()
                .find(|operation| {
                    matches!(
                        operation.kind,
                        OperationKind::Binary {
                            op: BinaryOp::Add,
                            ..
                        }
                    ) && operation
                        .results
                        .first()
                        .is_some_and(|result| result.ty == Type::INDEX)
                })
                .unwrap();
            let OperationKind::Binary { rhs, lhs, .. } = &mut operation.kind else {
                unreachable!();
            };
            *rhs = *lhs;
        });
        mutate_and_reject(|operations| {
            let operation = operations
                .iter_mut()
                .find(|operation| {
                    matches!(operation.kind, OperationKind::Select { .. })
                        && operation
                            .results
                            .first()
                            .is_some_and(|result| result.ty == Type::INDEX)
                })
                .unwrap();
            let OperationKind::Select {
                true_value,
                false_value,
                ..
            } = &mut operation.kind
            else {
                unreachable!();
            };
            *false_value = *true_value;
        });
        mutate_and_reject(|operations| {
            let operation = operations
                .iter_mut()
                .find(|operation| {
                    matches!(operation.kind, OperationKind::Constant(Constant::Index(0)))
                })
                .unwrap();
            operation.kind = OperationKind::Constant(Constant::Index(1));
        });
        mutate_and_reject(|operations| {
            let OperationKind::GetElementPointer { offset, .. } = &mut operations[2].kind else {
                unreachable!();
            };
            *offset = ValueId(u32::MAX);
        });
        mutate_and_reject(|operations| {
            let OperationKind::GetElementPointer { base, .. } = &mut operations[2].kind else {
                unreachable!();
            };
            *base = ValueId(u32::MAX);
        });
        mutate_and_reject(|operations| {
            operations[2].results[0].ty = Type::pointer(
                Type::Scalar(ScalarType::I32),
                AddressSpace::Global,
                AccessMode::ReadWrite,
            );
        });

        let mut wrong_allocation = neutral_recipe_replay_fixture_v1(2, ScalarType::I32);
        let OperationKind::WorkgroupMemory(allocation) =
            &mut wrong_allocation.body.blocks[0].operations[0].kind
        else {
            unreachable!();
        };
        allocation.element = Type::Scalar(ScalarType::U32);
        assert_neutral_recipe_mismatch_v1(&wrong_allocation);
    }

    #[test]
    fn neutral_recipe_replay_binds_memory_and_barrier_contracts() {
        let barrier_mutations: [fn(&mut WorkgroupBarrier); 4] = [
            |barrier: &mut WorkgroupBarrier| {
                barrier.memory_scope = SynchronizationScope::Device;
            },
            |barrier: &mut WorkgroupBarrier| {
                barrier.semantics.ordering = MemoryOrdering::Relaxed;
            },
            |barrier: &mut WorkgroupBarrier| {
                barrier.semantics.address_spaces = BTreeSet::from([AddressSpace::Global]);
            },
            |barrier: &mut WorkgroupBarrier| {
                barrier.convergence = Convergence::uniform(SynchronizationScope::Subgroup);
            },
        ];
        for mutation in barrier_mutations {
            let mut fixture = neutral_recipe_replay_fixture_v1(2, ScalarType::F32);
            let operation = neutral_consumer_operations_mut_v1(&mut fixture)
                .iter_mut()
                .find(|operation| matches!(operation.kind, OperationKind::WorkgroupBarrier(_)))
                .unwrap();
            let OperationKind::WorkgroupBarrier(barrier) = &mut operation.kind else {
                unreachable!();
            };
            mutation(barrier);
            assert_neutral_recipe_mismatch_v1(&fixture);
        }

        let mut execution_scope = neutral_recipe_replay_fixture_v1(2, ScalarType::F32);
        let operation = neutral_consumer_operations_mut_v1(&mut execution_scope)
            .iter_mut()
            .find(|operation| matches!(operation.kind, OperationKind::WorkgroupBarrier(_)))
            .unwrap();
        operation.kind = OperationKind::Barrier(fe2o3_kernel_ir::Barrier {
            execution_scope: SynchronizationScope::Subgroup,
            memory_scope: SynchronizationScope::Workgroup,
            semantics: BarrierSemantics::new(
                MemoryOrdering::AcquireRelease,
                [AddressSpace::Workgroup],
            ),
        });
        assert_neutral_recipe_mismatch_v1(&execution_scope);

        let access_mutations: [fn(&mut MemoryAccess); 3] = [
            |access: &mut MemoryAccess| access.address_space = AddressSpace::Global,
            |access: &mut MemoryAccess| access.alignment = 8,
            |access: &mut MemoryAccess| access.volatile = true,
        ];
        for mutation in access_mutations {
            let mut fixture = neutral_recipe_replay_fixture_v1(2, ScalarType::F32);
            let operation = neutral_consumer_operations_mut_v1(&mut fixture)
                .iter_mut()
                .find(|operation| matches!(operation.kind, OperationKind::Store { .. }))
                .unwrap();
            let OperationKind::Store { access, .. } = &mut operation.kind else {
                unreachable!();
            };
            mutation(access);
            assert_neutral_recipe_mismatch_v1(&fixture);
        }
    }

    #[test]
    fn neutral_recipe_replay_binds_input_output_and_producer_span_custody() {
        let mut input = neutral_recipe_replay_fixture_v1(2, ScalarType::U32);
        let OperationKind::Store { value, .. } = neutral_consumer_operations_mut_v1(&mut input)
            .iter_mut()
            .find(|operation| matches!(operation.kind, OperationKind::Store { .. }))
            .map(|operation| &mut operation.kind)
            .unwrap()
        else {
            unreachable!();
        };
        *value = ValueId(u32::MAX);
        assert_neutral_recipe_mismatch_v1(&input);

        let mut output = neutral_recipe_replay_fixture_v1(2, ScalarType::U32);
        output.contract.output = ValueId(u32::MAX);
        assert_neutral_recipe_mismatch_v1(&output);

        let mut producer = neutral_recipe_replay_fixture_v1(2, ScalarType::U32);
        producer.correspondence.terminator_operation_spans[0].operation_count = 0;
        assert_neutral_recipe_mismatch_v1(&producer);
    }

    #[test]
    fn generated_effect_source_gate_rejects_location_ordinal_and_zero_recipe_substitution() {
        let recipe = [201; 32];
        let (allocation_origin, noalias_class) =
            dialect_kernel::neutral_workgroup_allocation_contract_v1(recipe);
        let effects = vec![
            ProductionRankedOperationV1::AllocationEffect {
                kind: AccessKindAttr::Write,
                memory_space: dialect_kernel::MemorySpaceAttr::Workgroup,
                allocation_origin,
                noalias_class,
            },
            ProductionRankedOperationV1::Barrier {
                execution_scope: dialect_gpu::HierarchyAttr::Workgroup,
                memory_scope: dialect_gpu::MemoryScopeAttr::Workgroup,
                address_space: dialect_gpu::AddressSpaceAttr::Workgroup,
                order: dialect_gpu::MemoryOrderAttr::AcquireRelease,
            },
        ];
        let lowering = ranked_correlation_input_for_effects(effects, 9);
        let exact = [
            ProductionRankedExecutableEffectSourceV1::new(
                7,
                0,
                0,
                3,
                ProductionRankedExecutableEffectOriginV1::GeneratedFromSemanticTerminator,
                recipe,
            ),
            ProductionRankedExecutableEffectSourceV1::new(
                7,
                1,
                0,
                4,
                ProductionRankedExecutableEffectOriginV1::GeneratedFromSemanticTerminator,
                recipe,
            ),
        ];
        assert!(ranked_executable_effect_sources_are_well_formed(
            lowering.kernel(),
            &exact,
        ));

        let mut duplicate_location = exact;
        duplicate_location[1].ranked_operation = 3;
        assert!(!ranked_executable_effect_sources_are_well_formed(
            lowering.kernel(),
            &duplicate_location,
        ));
        let mut duplicate_ordinal = exact;
        duplicate_ordinal[1].semantic_effect_ordinal = 0;
        assert!(!ranked_executable_effect_sources_are_well_formed(
            lowering.kernel(),
            &duplicate_ordinal,
        ));
        let mut missing_location = exact;
        missing_location[1].ranked_operation = u32::MAX;
        assert!(!ranked_executable_effect_sources_are_well_formed(
            lowering.kernel(),
            &missing_location,
        ));
        let mut zero_recipe = exact;
        zero_recipe[1].recipe_identity = [0; 32];
        assert!(!ranked_executable_effect_sources_are_well_formed(
            lowering.kernel(),
            &zero_recipe,
        ));
    }

    #[test]
    fn rust_usize_and_kernel_index_are_edge_transport_equivalent() {
        let index = Type::INDEX;
        let u64_type = Type::Scalar(ScalarType::U64);
        assert!(index_and_u64_are_transport_equivalent(&index, &u64_type));
        assert!(index_and_u64_are_transport_equivalent(&u64_type, &index));
        assert!(!index_and_u64_are_transport_equivalent(
            &index,
            &Type::Scalar(ScalarType::U32),
        ));
        assert!(!index_and_u64_are_transport_equivalent(
            &Type::Scalar(ScalarType::U64),
            &Type::Scalar(ScalarType::I64),
        ));
    }

